window.DIGEST_ARCHIVE=window.DIGEST_ARCHIVE||{};window.DIGEST_ARCHIVE["2026-07-20"]={"date": "2026-07-20", "dateKR": "2026년 7월 20일", "dateEN": "20 July 2026", "total": 169, "sections": [{"code": "TOP", "type": "news", "kTitle": "Section 1. 주요 뉴스", "eTitle": "Section 1. Top News", "items": [{"code": "TOP", "title": "이란 혁명수비대 \"경고 무시한 선박 2척 호르무즈서 사고\"", "src": "gCaptain", "date": "2026-07-19", "kSum": "이란 혁명수비대(IRGC)는 7월 19일 미국의 뒷배를 믿고 경고를 무시한 채 호르무즈 해협(Strait of Hormuz)의 '위험 항로'로 진입하려던 선박 2척이 '사고'를 당했으며, 다른 2척은 해당 항로를 포기했다고 타스님(Tasnim) 통신을 통해 밝혔다. 수비대는 \"미국의 말에 휘둘려 위험 항로로 들어오는 선박은 반드시 사고를 당할 것\"이라고 경고했다.", "eSum": "Iran's Revolutionary Guards said on July 19 that two ships were involved in an 'accident' after trying to transit the Strait of Hormuz via an 'unsafe route' in defiance of Iranian warnings, while two other vessels turned back, according to the semi-official Tasnim news agency. The IRGC warned that vessels swayed by US assurances and entering unsafe routes would 'certainly face accidents.'", "kImp": "호르무즈 통항 리스크가 말이 아닌 실제 선박 피해로 번지는 국면으로, 중동 통항·기항 선대를 운용하는 선박관리자는 항로 재설정, 전쟁위험보험(WRI) 급등, 선원 승선 기피와 안전 대응을 즉시 재점검해야 한다.", "eImp": "The threat to Hormuz transits is now translating into actual vessel damage, forcing ship managers with Gulf-bound tonnage to urgently review rerouting, surging war-risk insurance premiums, and seafarer safety and reluctance to transit.", "url": "https://gcaptain.com/irans-guards-say-two-ships-involved-in-accident-after-defying-hormuz-warnings/"}, {"code": "TOP", "title": "발효된 IMO 자율운항선박 안전코드(MASS Code)", "src": "The Maritime Executive", "date": "2026-07-17", "kSum": "2026년 7월 1일자로 도입된 국제 자율운항선박 안전코드(MASS Code)를 계기로, 자율·원격 운항 선박의 설계·운항·책임 체계 등 새 규제 프레임워크의 의미를 짚는 논평이다. 자율운항 기술 상용화가 빨라지는 가운데 국제 규범이 본격 정비되기 시작했음을 보여준다.", "eSum": "An editorial marking the International Code of Safety for Maritime Autonomous Surface Ships (MASS Code), introduced on 1 July 2026, examines what the new regulatory framework means for the design, operation and liability of autonomous and remotely operated ships. It signals that international rulemaking is now catching up with fast-advancing autonomous technology.", "kImp": "자율운항 규범의 초기 틀이 잡히면서, 선박관리자는 향후 원격운항·무인화 도입 시 안전관리체계(SMS), 선원 자격, 책임 소재 변화에 대비한 규제 대응 전략을 미리 마련할 필요가 있다.", "eImp": "With the first framework for autonomous shipping taking shape, ship managers must begin preparing their safety management systems, crew competency and liability arrangements for the eventual adoption of remote and unmanned operations.", "url": "https://maritime-executive.com/editorials/the-mass-code"}, {"code": "TOP", "title": "피레우스 항만, 대학 협력으로 스마트항 개발 추진", "src": "Splash247", "date": "2026-07-18", "kSum": "피레우스 항만공사(PPA)가 아테네 국립기술대학교(NTUA)와 장기 연구·기술 협약을 체결하고 스마트 항만 기술, 디지털 전환, 물류, 해상안전, 차세대 항만운영시스템 개발에 협력하기로 했다. COSCO가 지배하는 피레우스는 물리적 확장보다 데이터·자동화 중심의 현대화로 전환하는 신호를 보냈다.", "eSum": "Piraeus Port Authority has signed a long-term research and technology agreement with the National Technical University of Athens to develop smart-port technologies, digital transformation, logistics, maritime safety and advanced port operating systems. COSCO-controlled Piraeus is signalling a shift toward data- and automation-led modernisation rather than physical capacity alone.", "kImp": "주요 관문항의 디지털·자동화 전환은 기항 선박의 접안 효율과 데이터 연계에 영향을 주므로, 선박관리자는 스마트항 인프라와의 시스템 연동 및 사이버보안 준비 상황을 점검해 두어야 한다.", "eImp": "Digital and automation upgrades at a major gateway affect berthing efficiency and data integration for calling ships, so ship managers should check their systems' interoperability with smart-port infrastructure and cyber-security readiness.", "url": "https://splash247.com/piraeus-targets-smart-port-development-through-university-partnership/"}, {"code": "TOP", "title": "흑해 CPC 터미널 인근서 유조선 '노르딕 제니스' 드론 피격", "src": "MarineLink", "date": "2026-07-17", "kSum": "엑슨모빌이 용선한 수에즈막스 유조선 '노르딕 제니스(Nordic Zenith)'가 러시아 흑해 연안 CPC(카스피 파이프라인 컨소시엄) 터미널 인근에서 7월 17일 드론 2대의 공격을 받아 화재가 발생했다. 인근 CPC 선박이 선원 13명을 대피시켰고 9명은 잔류했으며, 선박은 하역 일정에서 제외됐다. 최근 흑해·아조프해에서 러시아·우크라이나 간 선박 공격이 급격히 확대되는 흐름의 일부다.", "eSum": "The Suezmax tanker Nordic Zenith, chartered by ExxonMobil, was hit by two drones and caught fire near the Caspian Pipeline Consortium (CPC) terminal on Russia's Black Sea coast on July 17. Nearby CPC vessels evacuated 13 crew while nine remained aboard, and the tanker has been removed from the loading schedule amid a sharp escalation of Russia-Ukraine attacks on shipping in the Black and Azov seas.", "kImp": "흑해가 새로운 고위험 해역으로 부상하면서, 해당 수역을 오가는 선대의 선박관리자는 전쟁위험 담보, 선원 안전, 대체 항로 및 하역항 리스크를 재평가해야 한다.", "eImp": "With the Black Sea emerging as a new high-risk zone, ship managers with vessels calling there must reassess war-risk cover, seafarer safety, and the exposure of alternative routes and loading ports.", "url": "https://www.marinelink.com/news/oil-tanker-attacked-drone-black-sea-541328"}, {"code": "TOP", "title": "China Merchants maps out $728m VLOC order", "src": "Splash247", "date": "2026-07-20", "kSum": "상하이 상장사 차이나 머천츠 에너지 시핑(China Merchants Energy Shipping)이 계열 조선소에 34만 3,000dwt급 초대형 광석운반선(VLOC) 6척을 최대 49억 3,000만 위안(7억 2,800만 달러)에 발주하기로 했다. 인도는 2029~2030년으로 예정돼 있고 척당 약 1억 2,100만 달러 수준이며, 7월 28일 주주총회 승인을 앞두고 있다. 이는 이 회사가 10여 년 만에 처음 내놓는 VLOC 신조 발주다.", "eSum": "China Merchants Energy Shipping has lined up six 343,000 dwt very large ore carriers (VLOCs) at an affiliated yard in a related-party deal worth up to RMB4.93bn ($728m), with deliveries scheduled across 2029-2030 at about $121m per ship. Subject to a July 28 shareholder vote, it is the owner's first VLOC newbuild order in more than a decade.", "kImp": "대형 벌크·광석운반선 신조 수요가 다시 살아나는 신호로, 중국 국영 선사가 장기 운송계약(COA)을 바탕으로 선대를 확장하면서 발주를 자국 조선소에 집중시키는 흐름을 보여준다.", "eImp": "Signals renewed appetite for large bulk/ore carrier newbuildings and shows Chinese state-owned owners expanding fleets on long-term COAs while concentrating orders at domestic yards.", "url": "https://splash247.com/china-merchants-maps-out-728m-vloc-order/"}, {"code": "TOP", "title": "Diana Shipping lifts ultramax rate in Fednav switch", "src": "Splash247", "date": "2026-07-20", "kSum": "다이애나 시핑(Diana Shipping)이 2015년 건조된 6만 500dwt 울트라막스 'DSI Pegasus'를 캐나다 벌크 오퍼레이터 페드나브(Fednav)와 일일 1만 8,350달러(5% 수수료 별도)에 신규 용선 계약했다. 이는 종전 카길(Cargill) 용선 대비 약 30%(일 4,100달러) 인상된 수준이다. 용선 기간은 7월 27일부터 최소 2027년 8월 중순까지로, 약 695만 달러의 총수익이 예상된다.", "eSum": "Diana Shipping fixed its 2015-built 60,500 dwt ultramax DSI Pegasus to Canada's Fednav at $18,350/day (excluding 5% commission), nearly 30% ($4,100/day) above the prior Cargill rate. The charter runs from July 27 until at least mid-August 2027, yielding an estimated $6.95m in gross revenue.", "kImp": "건화물(드라이 벌크) 용선료가 견조하게 반등하고 있음을 보여주는 개별 픽스처로, 중형 벌크선 시황 회복 기대를 시사한다.", "eImp": "An individual fixture evidencing firming dry bulk charter rates, pointing to improving sentiment in the mid-size bulker market.", "url": "https://splash247.com/diana-shipping-lifts-ultramax-rate-in-fednav-switch/"}, {"code": "TOP", "title": "Subcontractor Killed in Fourth Incident at HD Hyundai Sites in 2026", "src": "The Maritime Executive", "date": "2026-07-20", "kSum": "7월 18일 한국 울산의 HD현대(HD Hyundai) 조선소에서 건조 중인 LNG운반선 마무리 작업을 하던 26세 우즈베키스탄 국적 하청 노동자가 곤돌라(gondola)와 비계 사이에 끼여 사망했다. 올해 들어 회사 사업장에서 발생한 네 번째 사망 사고로, 고용노동부와 안전보건공단이 즉시 조사에 착수하고 선체 작업에 부분 작업중지 명령을 내렸다. 금속노조는 안전 대책 미흡을 비판하며 경영진의 사과를 요구했다.", "eSum": "A 26-year-old Uzbek subcontractor doing finishing work on an LNG carrier under construction at HD Hyundai's Ulsan yard was crushed to death between a gondola and scaffolding on July 18 - the fourth death at company sites this year. Authorities launched an immediate investigation and imposed a partial stop-work order on hull work, while the metal union demanded stronger safety measures and a CEO apology.", "kImp": "세계 최대 조선사에서 반복되는 중대재해와 하청·안전관리 문제가 부각되며, 노사 갈등 심화와 조선업 안전규제 강화 압력으로 이어질 수 있다.", "eImp": "Recurring fatalities at the world's top shipbuilder spotlight subcontractor safety and management failings, adding to labor tensions and pressure for tighter shipyard safety enforcement.", "url": "https://maritime-executive.com/article/subcontractor-killed-in-fourth-incident-at-hd-hyundai-sites-in-2026"}, {"code": "TOP", "title": "Ship-to-Ship Oil Transfers in Gulf of Oman Slow After Recent Vessel Attacks", "src": "MarineLink", "date": "2026-07-20", "kSum": "이란군의 잇단 선박 공격 이후 호르무즈 해협(Strait of Hormuz) 외해 오만 인근에서 이뤄지던 유조선 간 선박대선박(STS) 원유 환적이 급감했다. 로이터가 검토한 7월 18일 위성영상에는 STS를 수행하는 유조선이 단 1쌍만 포착됐고(7월 11일에는 3쌍), 해협 통항도 최근 일주일 하루 평균 초대형유조선 2척으로 전주 5척에서 줄었다.", "eSum": "Ship-to-ship (STS) crude transfers between tankers off Oman outside the Strait of Hormuz have slowed sharply after a wave of Iranian attacks on vessels. Satellite imagery on July 18 showed just one pair of tankers doing STS (down from three pairs on July 11), while strait transits fell to about two supertankers per day, down from five the prior week.", "kImp": "호르무즈 통항 위험 고조가 걸프 원유 수출 물류에 실질적 차질을 주고 있음을 보여주며, 유가·해상보험·항로 안전에 직접적 파급을 미친다.", "eImp": "Shows escalating Hormuz risk is materially disrupting Gulf crude export logistics, with direct implications for oil prices, marine insurance and route security.", "url": "https://www.marinelink.com/news/shiptoship-oil-transfers-gulf-oman-slow-541357"}]}, {"code": "ACC", "type": "accident", "kTitle": "Section 2. 해양사고", "eTitle": "Section 2. Accidents", "items": [{"code": "ACC", "title": "Thurgau Gold - River Cruise Ship Runs Aground on the Rhine near Bonn", "src": "Shipwreck Log", "date": "2026-07-16", "kSum": "135m 여객선 투르가우 골드(Thurgau Gold)가 2026년 7월 16일 오전 독일 본(Bonn) 인근 라인강에서 뒤셀도르프발 코블렌츠행 항해 중 접안을 시도하다 선수 좌현이 모래톱에 좌초했다. 승객 75명·승무원 40명이 탑승했으며 부상자·침수·오염은 없었고, 오후에 도착한 자항 바지선 사르디우스 II(Sardius II)가 예인해 이초시켰다.", "eSum": "The 135-meter passenger ship Thurgau Gold ran aground on a sandbank on the Rhine near Bonn, Germany, on the morning of July 16, 2026, while maneuvering to dock during a Duesseldorf-to-Koblenz voyage. With 75 passengers and 40 crew aboard and no injuries, ingress or pollution, the self-propelled barge Sardius II pulled her free in the afternoon.", "kCause": "초기 조사에 따르면 하천 수위(약 2m)가 선박 흘수(1.6m)에 비해 불충분한 상태에서 접안 조종 중 좌초했다.", "eCause": "Initial findings indicate the river water level (about 2 m) was insufficient for the vessel's 1.6 m draft during the docking maneuver.", "kLes": "하천 여객선 접안 시 실시간 수심·수위 확인과 충분한 여유 흘수(UKC) 확보, 저수위 구간에서의 신중한 조선이 필요하다(추정).", "eLes": "River passenger vessels should verify real-time depth/water levels, keep adequate under-keel clearance, and maneuver cautiously in shallow reaches (presumed).", "url": "https://shipwrecklog.com/log/2026/07/thurgau-gold-2/"}, {"code": "ACC", "title": "Aging Bulker Luni Breaks in Half and Sinks off Bandar Abbas", "src": "The Maritime Executive", "date": "2026-07-14", "kSum": "선령 32년 세인트키츠네비스 선적 벌크선 루니(Luni, IMO 9070711)가 2026년 7월 14일 이란 반다르아바스(Bandar Abbas) 인근 호르무즈 해협에서 선체 손상·침수 후 두 동강 나 부분 침몰했다. 선원 23명은 전원 구조돼 케슘(Qeshm)으로 이송됐다.", "eSum": "The 32-year-old St Kitts and Nevis-flagged bulk carrier Luni (IMO 9070711) suffered hull damage and flooding, then broke in two and partially sank near Bandar Abbas in the Strait of Hormuz on July 14, 2026. All 23 crew were rescued and evacuated to Qeshm.", "kCause": "수일 전 다른 선박과의 충돌로 입은 선체 손상이 침수와 구조 붕괴로 이어진 것으로 보도됐으나 당국은 미확정 상태이며, 노후 선체와 다수의 PSC 결함이 배경으로 지적된다(폭발음·피격설은 미확인).", "eCause": "Reports attribute the loss to earlier collision damage leading to flooding and structural failure, though authorities have not confirmed it; the aged hull and many PSC deficiencies are cited as background (claims of explosions/strike unverified).", "kLes": "노후 선박의 선체 강도·구조 정비 관리와 PSC 결함 시정, 침수 발생 시 신속한 손상통제·구조 대응이 중요하다(추정).", "eLes": "For aging vessels, hull-strength and structural maintenance, rectifying PSC deficiencies, and prompt damage control/evacuation on flooding are critical (presumed).", "url": "https://maritime-executive.com/article/aging-bulker-breaks-in-half-and-sinks-off-bandar-abbas"}, {"code": "ACC", "title": "Boat Capsizes near Alcatraz in San Francisco Bay, One Dead and Three Missing", "src": "CBS News", "date": "2026-07-14", "kSum": "2026년 7월 14일 오후 미국 샌프란시스코만 알카트라즈섬 인근에서 유가족 20명이 유해 산골(散骨)을 위해 탄 약 49피트 유람선이 큰 파도를 맞아 우현으로 크게 기울며 전복·침몰했다. 1명이 사망하고 3명이 실종됐으며, 나머지는 주변 선박과 해안경비대에 구조됐다.", "eSum": "On the afternoon of July 14, 2026, a roughly 49-foot pleasure boat carrying 20 family members scattering ashes was struck by a wave, heeled heavily to starboard and capsized/sank near Alcatraz Island in San Francisco Bay. One person died, three went missing, and the rest were rescued by nearby boats and the Coast Guard.", "kCause": "거친 해상에서 파도를 맞아 복원성을 상실하고 전복한 것으로 초기 정황이 파악됐으며, 정확한 원인은 조사 중이다.", "eCause": "Initial accounts indicate the boat took a wave in rough seas, lost stability and rolled over; the exact cause is under investigation.", "kLes": "소형 여객·유람선은 출항 전 기상·해상 상태를 확인하고 정원·복원성 한계를 준수하며 승선객의 구명동의 착용을 철저히 해야 한다(추정).", "eLes": "Small passenger/pleasure craft should check weather/sea state before departure, respect capacity and stability limits, and ensure lifejacket use (presumed).", "url": "https://www.cbsnews.com/sanfrancisco/news/boat-sinks-alcatraz-san-francisco-bay-fatal-capsizing-victims/"}, {"code": "ACC", "title": "Tanker Mugello Allides with Moored Tanker Makenita H on the Parana River", "src": "Shipwreck Log", "date": "2026-07-13", "kSum": "2026년 7월 13일 228m 탱커 무겔로(Mugello, IMO 1030040)가 아르헨티나 캄파나(Campana) 항 파라나강에서 조선(操船) 중 정박해 있던 152m 탱커 마케니타 H(Makenita H, IMO 9477775)를 들이받았다. 무겔로는 우현 흘수선 상부에 파공이, 마케니타 H는 좌현 선미에 함몰이 발생했으며 인명피해는 없었다.", "eSum": "On July 13, 2026, the 228-meter tanker Mugello (IMO 1030040) allided with the moored 152-meter tanker Makenita H (IMO 9477775) while maneuvering at the port of Campana on the Parana River, Argentina. Mugello was holed above the waterline on the starboard side and Makenita H was dented on the port stern; there were no injuries.", "kCause": "항내 조선 중 정박선과 접촉한 사고로, 아르헨티나 당국이 원인 조사에 착수했다(조종·조류 영향 추정).", "eCause": "An allision with a moored vessel during in-port maneuvering; Argentine authorities have opened an investigation (maneuvering/current effects presumed).", "kLes": "하천 항만에서의 조선 시 속력·조류 통제, 정박선과의 안전거리 확보, 예선 활용 등 접근 절차 관리가 필요하다(추정).", "eLes": "In river ports, control speed/current, keep safe distance from moored vessels and manage approach procedures (e.g., tug use) (presumed).", "url": "https://shipwrecklog.com/log/2026/07/mugello/"}, {"code": "ACC", "title": "Cargo Ship Collision Briefly Disrupts Operations at Cameroon's Busiest Commercial Port", "src": "Marine Insight", "date": "2026-07-12", "kSum": "2026년 7월 12일 03:00경 카메룬 두알라-보나베리(Douala-Bonaberi) 항 주 항로 20번 부표 인근에서 출항 중이던 벌크선 시 아너(Sea Honor)와 입항 중이던 화물선 블랙 라이노(Black Rhino)가 충돌했다. 블랙 라이노 선원 15명은 전원 구조됐고, 침수로 인해 항로 봉쇄를 막기 위해 의도적으로 좌초시켰으며 인명피해는 없었다.", "eSum": "Around 03:00 on July 12, 2026, the outbound bulk carrier Sea Honor and inbound cargo ship Black Rhino collided near buoy No. 20 in the main channel of the Port of Douala-Bonaberi, Cameroon. All 15 crew of Black Rhino were rescued; the flooding vessel was intentionally grounded to avoid blocking the channel, and there were no injuries.", "kCause": "예비조사에 따르면 블랙 라이노의 조타(steering) 제어 상실이 충돌을 유발한 것으로 추정되며, 정확한 원인은 기술조사가 진행 중이다.", "eCause": "Preliminary investigation suggests a loss of steering control aboard Black Rhino may have caused the collision; a full technical review is ongoing.", "kLes": "협수로 입출항 전 조타장치 점검과 비상조종(예: 수동 조타) 대비, 통항 분리·교신 강화가 필요하다(추정).", "eLes": "Before transiting narrow channels, verify steering gear, prepare for emergency steering, and strengthen traffic separation and communication (presumed).", "url": "https://www.marineinsight.com/cargo-ship-collision-briefly-disrupts-operations-at-cameroons-busiest-commercial-port/"}, {"code": "ACC", "title": "Fishing Vessel Hustler Sinks off Ocean Shores, Two Crew Rescued", "src": "The Astorian", "date": "2026-07-09", "kSum": "2026년 7월 9일 정오경 미국 워싱턴주 오션쇼어스(Ocean Shores) 서쪽 약 4해리 해상에서 48피트 어선 허슬러(Hustler)가 침몰했다. 선원 2명은 침몰 전 방수복을 착용하고 구명뗏목을 전개한 뒤 케이프 디스어포인트먼트 소속 미 해안경비대 구명정에 무사히 구조됐다.", "eSum": "Around noon on July 9, 2026, the 48-foot fishing vessel Hustler sank about four miles west of Ocean Shores, Washington. Its two crew donned immersion suits and deployed a life raft before she sank and were safely rescued by a U.S. Coast Guard motor lifeboat crew from Cape Disappointment.", "kCause": "침몰의 구체적 원인은 공표되지 않았으며(침수 추정), 관련 당국이 확인 중이다.", "eCause": "The specific cause of sinking was not stated (flooding presumed) and is being reviewed by the authorities.", "kLes": "소형 어선의 방수복·구명뗏목 등 비상장비 즉시 사용 준비와 조기 조난통보가 생존에 결정적임을 보여주는 사례다(추정).", "eLes": "The case shows how immediate readiness of immersion suits/life rafts and early distress alerting are decisive for survival on small fishing vessels (presumed).", "url": "https://dailyastorian.com/2026/07/12/fishing-vessel-sank-crew-rescued/"}, {"code": "ACC", "title": "MAIB: Allision of RIB Peaky Blinder with a navigation beacon (2 fatalities)", "src": "MAIB (GOV.UK)", "date": "2026-07-15", "kSum": "영국 해양사고조사국(MAIB)이 2025년 8월 14일 저녁 포츠머스 항(Portsmouth Harbour)에서 고속단정(RIB) '피키 블라인더(Peaky Blinder)'가 항로표지 등부표(navigation beacon 81)에 충돌한 사고 조사보고서(15/2026)를 공개했다. 조종하던 선주와 승객 2명이 물에 튕겨 나갔고, 승객 1명이 사망했으며 선주는 5일 뒤 시신으로 발견됐다. 나머지 1명은 경상을 입었다.", "eSum": "The UK MAIB published report 15/2026 into the allision of the RIB Peaky Blinder with navigation beacon 81 in Portsmouth Harbour on the evening of 14 August 2025. The owner (driving) and two passengers were ejected into the water; one passenger died and the owner's body was recovered five days later, while the third occupant survived with minor injuries.", "kCause": "충돌 직전 RIB이 안전하지 않은 과도한 속력으로 운항되고 있었고, 선주가 음주 상태여서 사고 가능성이 크게 높아졌다. 탑승자 누구도 구명조끼(PFD)를 착용하지 않아 입수 후 피해가 가중됐다. 레저 보트 음주·행태에 대한 규제·단속·교육 체계가 효과적으로 작동하지 않은 점도 지적됐다.", "eCause": "The RIB was being operated at an unsafe speed immediately before the allision, and the owner was under the influence of alcohol, substantially increasing the likelihood of an accident. No one wore a personal flotation device (PFD), worsening the consequences of entering the water; the regulation, enforcement and education regime for recreational boating was found ineffective.", "kLes": "MAIB는 포츠머스 항만청(King's Harbour Master)에 속력제한 준수 강화를, 교통부 장관에게는 비직업 항해자 음주 한도 규정(철도·교통안전법 2003) 시행과 하위법령 제정, 효과적 교육·인식 캠페인 국가전략 수립을 권고했다. 구명조끼 착용 필요성을 강조하는 안전 전단도 보고서와 함께 배포됐다.", "eLes": "The MAIB recommended the King's Harbour Master Portsmouth improve adherence to speed limits, and the Secretary of State for Transport commence alcohol-limit provisions for non-professional mariners (Railways and Transport Safety Act 2003), enact proportionate secondary legislation, and develop a national education and awareness strategy; a safety flyer urging PFD use was issued with the report.", "url": "https://www.gov.uk/maib-reports/allision-of-the-rigid-inflatable-boat-peaky-blinder-with-a-navigation-beacon-with-the-loss-of-2-lives"}]}, {"code": "PSC", "type": "news", "kTitle": "Section 3. 항만국통제", "eTitle": "Section 3. Port State Control", "items": [{"code": "PSC", "title": "파리 MoU(Paris MoU), 2025년 기국 성과 리스트(White/Grey/Black) 발표", "src": "Paris MoU", "date": "2026-07-01", "kSum": "파리 MoU(Paris MoU)가 제59차 위원회에서 2025년 점검 결과를 승인하고 기국 및 인정단체(RO) 성과 리스트를 채택했다. 새 White·Grey·Black 리스트는 2026년 7월 1일부터 적용되며 3년간 점검·억류 실적(최소 30회 점검 기국)을 기반으로 한다. 케이맨제도·스웨덴·노르웨이·덴마크·일본이 상위 기국이고, 코모로·탄자니아·카메룬이 최고위험 기국으로 분류됐다.", "eSum": "The Paris MoU Committee approved the 2025 inspection results at its 59th meeting and adopted new flag State and Recognized Organization (RO) performance lists. The updated White, Grey and Black lists apply from 1 July 2026, based on a three-year rolling period of inspections and detentions for flags with at least 30 inspections. Cayman Islands, Sweden, Norway, Denmark and Japan lead, while Comoros, Tanzania and Cameroon are rated very high risk.", "kImp": "선박의 기국이 어느 리스트에 있는지는 파리 MoU 지역에서의 선박위험프로파일(SRP)과 점검 빈도를 직접 좌우하므로, 기국 선택과 억류 이력 관리가 실질적 운항 부담으로 이어진다.", "eImp": "A flag's placement on these lists directly shapes a ship's risk profile and inspection frequency across the Paris MoU region, making flag choice and detention history a tangible operational burden.", "url": "https://parismou.org/2026/07/2025-performance-lists-paris-mou"}, {"code": "PSC", "title": "RiSK4SEA 6월 PSI 전망: 전 선종에서 PSC 단속 압박 급증", "src": "SAFETY4SEA / RiSK4SEA", "date": "2026-06-11", "kSum": "리스크포시(RiSK4SEA)의 6월 PSC 스트레스지수(PSI) 전망은 글로벌 PSC 단속 환경의 광범위한 악화를 보여준다. 벌크선은 점검당 결함(DPI)이 16.6%, 선체·설비 결함이 29.2% 증가했고 2,371회 점검 중 118건이 억류돼 장기평균 대비 약 69% 늘었다. 탱커도 KPI 스트레스 18.7%, 억류율 약 50% 상승했으며 벌크·탱커·컨테이너·일반화물선이 모두 'PSI-9 위험구간'에 진입했다.", "eSum": "RiSK4SEA's June PSC Stress Index (PSI) outlook signals broad deterioration in the global PSC enforcement climate. Bulkers saw deficiency-per-inspection rise 16.6% and ship structure/equipment deficiencies rise 29.2%, with 118 detentions from 2,371 inspections, up nearly 69% versus the long-term baseline. Tankers recorded KPI stress up 18.7% and detentions up roughly 50%, while bulkers, tankers, containers and general cargo all entered the PSI-9 critical risk zone.", "kImp": "전 주요 선종이 동시에 최고위험 구간에 든 것은 이례적으로, 선사는 통상적 점검에서도 결함·억류 리스크가 크게 높아졌음을 전제로 대비해야 한다.", "eImp": "All major segments entering the critical zone simultaneously is unusual, meaning operators must prepare for materially higher deficiency and detention risk even in routine inspections.", "url": "https://safety4sea.com/cm-risk4sea-psi-outlook-of-june-2026-signals-broad-deterioration-in-global-psc-enforcement-climate/"}, {"code": "PSC", "title": "바하마(Bahamas), 강한 PSC 실적으로 미국 QUALSHIP 21 자격 회복", "src": "SAFETY4SEA", "date": "2026-06-04", "kSum": "바하마(Bahamas)가 강한 항만국통제(PSC) 실적을 바탕으로 미국 해안경비대(USCG)의 QUALSHIP 21 프로그램 자격을 2026~27년(2026.7.1~2027.6.30)에 대해 회복했다. USCG 2025 PSC 연차보고서 기준 바하마적선은 591회 점검 중 억류 1건, 3년 억류율 0.55%를 기록했다. QUALSHIP 21은 높은 안전·보안·환경 준수를 보인 우수 기국·선박을 인정하는 제도다.", "eSum": "The Bahamas has regained eligibility for the USCG QUALSHIP 21 programme for 2026-27 (1 July 2026 to 30 June 2027) on the back of strong Port State Control performance. Per the USCG 2025 PSC Annual Report, Bahamas-flagged ships recorded 591 examinations with only one detention and a three-year detention ratio of 0.55%. QUALSHIP 21 recognises quality flags and ships demonstrating high compliance with safety, security and environmental standards.", "kImp": "QUALSHIP 21 자격은 미국 입항 시 점검 부담 경감 등 실질적 혜택을 주므로, 기국의 억류율 관리가 상업적 경쟁력으로 직결됨을 보여준다.", "eImp": "QUALSHIP 21 status brings tangible benefits such as reduced examination burden in US ports, illustrating how a flag's detention record translates into commercial competitiveness.", "url": "https://safety4sea.com/the-bahamas-regains-qualship-21-eligibility-following-strong-psc-performance/"}, {"code": "PSC", "title": "AMSA 2026-27 국가준수계획: 외국적선 PSC 2,400건 목표·화물고박 중점", "src": "AMSA", "date": "2026-07-09", "kSum": "호주해사안전청(AMSA)이 2026년 7월 1일부터 2027년 6월 30일까지 적용되는 2026-27 국가준수계획(National Compliance Plan)을 발표했다. 외국적선 대상 최소 2,400건, 국내상업선 2,300건의 점검을 목표로 하며 항해안전, 오염방지, 화물고박·적재를 중점 영역으로 삼는다. 해사노동협약(MLC)에 따른 선원 안전·복지와, 처음으로 OHS(MI)법에 따른 15건의 점검도 포함된다.", "eSum": "AMSA published its National Compliance Plan 2026-27, covering 1 July 2026 to 30 June 2027. It targets a minimum of 2,400 PSC inspections on foreign-flagged vessels and 2,300 on domestic commercial vessels, focusing on navigational safety, pollution prevention, and cargo securing and stowage. It also covers seafarer safety and welfare under the MLC and, for the first time, 15 inspections under the OHS(MI) Act.", "kImp": "호주 기항선은 화물고박 중점이 파리·도쿄 MoU의 2026 CIC와 겹치므로, 고박 관련 결함 노출이 특히 높아질 전망이다.", "eImp": "Ships calling at Australian ports face heightened exposure on cargo securing, as AMSA's focus overlaps with the Paris/Tokyo MoU 2026 CIC on the same topic.", "url": "https://www.amsa.gov.au/about/corporate-publications/national-compliance-plan-2026-27"}, {"code": "PSC", "title": "도쿄 MoU(Tokyo MoU) 2025 연차보고서: 점검 35,546건·억류율 3.53%", "src": "Tokyo MoU", "date": "2026-05-01", "kSum": "도쿄 MoU(Tokyo MoU)가 2025 연차보고서를 발표했다. 2025년 35,546회 점검(선박 19,980척)을 수행했고 73개 기국 소속 1,255척이 중대결함으로 억류돼 억류율 3.53%를 기록했다. 2023~2025 성과리스트는 66개 기국으로 구성되며 저성과 15개, 중간 19개, 고성과 32개다.", "eSum": "The Tokyo MoU published its Annual Report for 2025. It carried out 35,546 inspections involving 19,980 individual ships, and detained 1,255 ships under 73 flags for serious deficiencies, a detention rate of 3.53%. The 2023-2025 performance list comprises 66 flags, with 15 low, 19 medium and 32 high performers.", "kImp": "아시아·태평양 최대 PSC 체제의 억류율과 기국 성과 순위는 한국 선사·기항선의 지역 내 점검 표적화에 직접 영향을 준다.", "eImp": "As the Asia-Pacific's largest PSC regime, its detention rate and flag rankings directly influence how Korean operators and calling ships are targeted for inspection in the region.", "url": "https://www.tokyo-mou.org/annual-report/2026/05/01/annual-report-2025/"}, {"code": "PSC", "title": "미국 해안경비대(USCG), 외국적 탱커 대상 '성과기반 COC 검사일정' 도입", "src": "USCG Maritime Commons", "date": "2026-05-20", "kSum": "미국 해안경비대(USCG) 상선준수국(CG-CVC)이 외국적 탱커를 대상으로 '성과기반 적합증서(COC) 검사일정'을 시행하는 개정 업무지침 CVC-WI-021(3)을 공표했다. 2026 국방수권법(NDAA)에 근거해 연간 중간검사를 기존의 시간기반에서 데이터기반 모델로 전환하며, 실적이 우수한 선박은 현장검사 대신 인정서한으로 연간 요건을 충족할 수 있다. 다만 최근 3년 내 USCG 억류, 소유자·운항자 위반, 안전 관련 해양사고가 있으면 자동 제외되고, 2년 주기 종합검사는 그대로 유지된다.", "eSum": "The USCG Office of Commercial Vessel Compliance (CG-CVC) published revised work instruction CVC-WI-021(3), implementing a Performance-Driven Certificate of Compliance (COC) Examination Schedule for foreign tank vessels. Authorized by the 2026 NDAA, it shifts the annual mid-period inspection from a time-based to a data-driven model, letting high-performing vessels meet the annual requirement via a credit letter instead of a physical exam. Vessels are auto-disqualified if detained by the USCG, cited for owner/operator violations, or involved in a safety-related casualty in the last three years, while the biennial comprehensive exam is unchanged.", "kImp": "우수 실적 탱커의 검사 부담을 줄이는 인센티브 구조로, 3년 억류·사고 이력 관리가 미국 항만 검사 빈도와 직결됨을 재확인한다.", "eImp": "The incentive structure rewards well-performing tankers with reduced examination burden, reinforcing that a clean three-year detention and casualty record directly lowers inspection frequency in US ports.", "url": "https://www.news.uscg.mil/maritime-commons/Article/4497186/coast-guard-announces-performance-driven-certificate-of-compliance-examination/"}, {"code": "PSC", "title": "RiSK4SEA: Top PSC Performers List - July edition now available", "src": "SAFETY4SEA (RiSK4SEA)", "date": "2026-07-16", "kSum": "PSC 인텔리전스 제공업체 리스크4씨(RiSK4SEA)가 2026년 7월판 'Top PSC Performers List'를 공개했다. 벌크·일반화물·탱커·LNG·LPG·컨테이너 등 원양선대 16개 세그먼트에서 우수 관리회사를 평가했으며, 2023년 7월 1일부터 2026년 6월 30일까지 36개월간 전 세계 20만 3,000건 이상의 PSC 점검 데이터를 활용했다. 억류 없이 최다 점검을 통과한 관리회사 50곳을 뽑는 'PSC Resilient 50' 순위도 포함된다.", "eSum": "PSC intelligence provider RiSK4SEA released the July 2026 edition of its Top PSC Performers List, assessing ship managers across 16 ocean-going fleet segments (dry bulk, general cargo, tanker, LNG, LPG, container) using more than 203,000 PSC inspections over the 36 months from 1 July 2023 to 30 June 2026. It includes a 'PSC Resilient 50' ranking of managers with the most inspections without a detention.", "kImp": "관리회사별 PSC 성과를 데이터 기반으로 벤치마킹할 수 있게 해, 선주·용선주의 관리회사 선정과 자체 컴플라이언스 개선에 활용된다. 갱신된 리스트는 2026년 7월 1일부터 2027년 7월 6일까지 유효하다.", "eImp": "Provides data-driven benchmarking of ship managers' PSC performance, useful for owners' and charterers' manager selection and compliance improvement; the updated lists apply from 1 July 2026 to 6 July 2027.", "url": "https://safety4sea.com/cm-risk4sea-top-psc-performers-list-july-edition-now-available/"}]}, {"code": "PCTC", "type": "news", "kTitle": "Section 4. 자동차운반선", "eTitle": "Section 4. PCTC / Car Carriers", "items": [{"code": "PCTC", "title": "COSCO Shipping takes delivery of final LNG-fuelled car carrier in series", "src": "Baird Maritime", "date": "2026-06-22", "kSum": "코스코 시핑(COSCO Shipping)이 샤먼조선(Xiamen Shipbuilding Industry)에서 건조한 신조 순수차량운반선(PCTC) '캉첸커우(Kangqiankou)'를 인도받았다. 시리즈 마지막 선박으로 길이 199.99m, 13개 갑판에 7,500CEU를 적재하며 LNG 이중연료 추진으로 25,000해리를 항해할 수 있다. 첫 상업항해로 신차 4,800대를 싣고 호주 동안으로 향한다.", "eSum": "COSCO Shipping has taken delivery of Kangqiankou, the final PCTC in its series built by Xiamen Shipbuilding Industry. The 199.99m vessel carries 7,500 CEU across 13 decks with LNG dual-fuel propulsion and a 25,000nm range, and departs on its maiden commercial voyage carrying 4,800 new vehicles for Australia's east coast.", "kImp": "중국 선사의 LNG 이중연료 PCTC 시리즈 완결은 친환경 차량운반선 선대 확충과 중국-호주 자동차 물류 확대를 보여준다.", "eImp": "The completion of a Chinese owner's LNG dual-fuel PCTC series signals continued growth of eco-friendly car-carrier fleets and expanding China-Australia vehicle logistics.", "url": "https://www.bairdmaritime.com/shipping/dry-cargo/pcc-pctc/cosco-shipping-takes-delivery-of-final-lng-fuelled-car-carrier-in-series"}, {"code": "PCTC", "title": "Grimaldi takes delivery of ammonia-ready car carrier Grande Oriente", "src": "Container News", "date": "2026-07-02", "kSum": "그리말디 그룹(Grimaldi Group)이 중국 차이나 머천츠 헤비 인더스트리 장쑤(China Merchants Heavy Industries Jiangsu)에서 건조한 12번째 암모니아 대응(ammonia-ready) PCTC '그란데 오리엔테(Grande Oriente)'를 인도받았다. 길이 220m·9,000CEU급으로 리나(RINA)의 암모니아 레디 표기를 받았고 5MWh 배터리, 태양광 패널, 육상전력 등을 갖춰 이전 세대 대비 연료소비를 50% 절감한다. 타이창에서 영국 포트베리로 향하는 아시아-유럽 항로에 투입된다.", "eSum": "Grimaldi Group has taken delivery of Grande Oriente, its 12th ammonia-ready PCTC, built by China Merchants Heavy Industries Jiangsu. The 220m, 9,000 CEU vessel holds RINA's Ammonia Ready notation and features a 5MWh battery, solar panels and shore power, cutting fuel use by 50% versus previous generations; it enters the Asia-Europe trade sailing from Taicang to Portbury, UK.", "kImp": "암모니아 전환 대비 대형 PCTC의 잇단 인도는 차량운반선 부문의 탈탄소 전환 가속을 상징한다.", "eImp": "The steady delivery of large ammonia-ready PCTCs underscores the accelerating decarbonization of the car-carrier segment.", "url": "https://container-news.com/grimaldi-takes-delivery-of-ammonia-ready-car-carrier-grande-oriente/"}, {"code": "PCTC", "title": "Grimaldi presents ammonia-ready car carrier Grande Istanbul", "src": "Container News", "date": "2026-07-06", "kSum": "그리말디 그룹(Grimaldi Group)이 튀르키예 코자엘리의 오토포트(Autoport)에서 최신 암모니아 대응 PCTC '그란데 이스탄불(Grande Istanbul)'을 선보였다. 최대 9,241CEU를 적재하며 이전 세대 대비 화물단위당 CO2 배출을 최대 50% 줄인다. 북유럽과 지중해를 잇는 유로메드(EuroMed) 서비스에 투입돼 튀르키예 주요 항만에 기항한다.", "eSum": "Grimaldi Group presented Grande Istanbul, its latest ammonia-ready PCTC, at Autoport in Kocaeli, Turkiye. With capacity of up to 9,241 CEU, it cuts CO2 per unit of cargo by up to 50% versus previous-generation car carriers and is deployed on Grimaldi's EuroMed service linking Northern Europe and the Mediterranean, calling several Turkish ports.", "kImp": "그리말디의 17척 차세대 암모니아 대응 PCTC 프로그램은 지중해-유럽 차량 물류의 친환경 경쟁력을 강화한다.", "eImp": "Grimaldi's 17-ship next-generation ammonia-ready PCTC program strengthens green competitiveness in Mediterranean-Europe vehicle logistics.", "url": "https://container-news.com/grimaldi-presents-ammonia-ready-car-carrier-grande-istanbul/"}, {"code": "PCTC", "title": "MOL expands bio-LNG supply for car carriers in Europe", "src": "Container News", "date": "2026-06-22", "kSum": "미쓰이 O.S.K. 라인스(MOL)가 유럽에서 LNG 추진 차량운반선을 위한 바이오 LNG 공급을 확대하는 신규 계약을 체결했다. 북서유럽은 타이탄(Titan)이 계속 공급하고 지중해는 스페인 말라가·바르셀로나 등에서 악스포(Axpo)가 공급한다. 해당 바이오 LNG는 전주기 탄소집약도가 -15g-CO2/MJ 이하이며 ISCC-EU 인증을 받았다.", "eSum": "Mitsui O.S.K. Lines (MOL) signed new agreements to expand bio-LNG supply for its LNG-powered car carriers in Europe. Titan continues supply in Northwest Europe while Axpo covers the Mediterranean, including Malaga and Barcelona; the bio-LNG has a lifecycle carbon intensity of -15 g-CO2/MJ or lower and is ISCC-EU certified.", "kImp": "바이오 LNG 벙커링망 확대는 LNG 차량운반선의 실질적 탈탄소 운항을 뒷받침한다.", "eImp": "Expanding the bio-LNG bunkering network supports genuine decarbonized operation of LNG car carriers.", "url": "https://container-news.com/mol-expands-bio-lng-supply-for-car-carriers-in-europe/"}, {"code": "PCTC", "title": "Polaris adds tonnage from Global Car Carriers", "src": "Splash247", "date": "2026-07-07", "kSum": "폴라리스 오토라이너스(Polaris Autoliners)가 글로벌 카 캐리어스(Global Car Carriers)로부터 2,000CEU급 피더 차량운반선 2척(바이킹 오슬로·바이킹 오데사)을 인수해 폴라리스 오슬로·폴라리스 스타로 개명했다. 두 선박은 2009·2010년 건조된 140m급으로 매매가는 약 4,400만 달러로 알려졌다. 이번 인수로 폴라리스의 지배 선대는 10척(자가 5·용선 5)으로 늘었다.", "eSum": "Polaris Autoliners acquired two 2,000 CEU feeder car carriers (Viking Oslo and Viking Odessa) from Global Car Carriers, renaming them Polaris Oslo and Polaris Star. The 140m vessels built in 2009-2010 reportedly changed hands for about $44m, lifting Polaris's controlled fleet to 10 ships (five owned, five chartered-in).", "kImp": "피더급 차량운반선 매매 활성화는 지역·근해 자동차 물류 수요와 중소 선사의 선대 확장을 보여준다.", "eImp": "Active feeder car-carrier S&P activity reflects regional/shortsea vehicle-logistics demand and fleet growth among mid-sized operators.", "url": "https://splash247.com/polaris-adds-tonnage-from-global-car-carriers/"}, {"code": "PCTC", "title": "Dry Cargo Vessel News Roundup | July 1 - China-built car carriers, UK owner's new shortsea ship and more", "src": "Baird Maritime", "date": "2026-07-01", "kSum": "베어드 마리타임(Baird Maritime)의 정기 드라이카고 선박 뉴스 종합으로, 중국에서 건조된 차량운반선들과 영국 선주의 신규 근해(shortsea) 선박 등 최근 인도·발주 소식을 다뤘다. 차량운반선 부문의 신조 인도 흐름이 주요 내용으로 포함됐다.", "eSum": "Baird Maritime's periodic dry cargo vessel news roundup covers recent deliveries and orders, including China-built car carriers and a UK owner's new shortsea ship. Car-carrier newbuild deliveries feature prominently.", "kImp": "주간 종합 기사는 차량운반선 신조 인도 흐름과 중국 조선소 비중을 한눈에 보여준다.", "eImp": "The weekly roundup captures the pace of car-carrier newbuild deliveries and the continuing prominence of Chinese shipyards.", "url": "https://www.bairdmaritime.com/shipping/dry-cargo/dry-cargo-vessel-news-roundup-july-1-china-built-car-carriers-uk-owners-new-shortsea-ship-and-more"}, {"code": "PCTC", "title": "Dry Cargo Vessel News Roundup | June 24 - Focus on Asian yards: deliveries from China and Vietnam plus Swiss car carrier orders", "src": "Baird Maritime", "date": "2026-06-24", "kSum": "아시아 조선소에 초점을 맞춘 베어드 마리타임(Baird Maritime) 드라이카고 선박 뉴스 종합으로, 중국·베트남 조선소의 인도 소식과 스위스 선사 살라움 라인스(Sallaum Lines)의 차량운반선 발주를 다뤘다. 살라움은 샤먼조선(Xiamen Shipbuilding)에 8,600CEU급 이중연료 PCTC를 발주했다.", "eSum": "This Baird Maritime dry cargo roundup focuses on Asian yards, covering deliveries from China and Vietnam plus Swiss carrier Sallaum Lines' car-carrier order. Sallaum ordered 8,600 CEU-class dual-fuel PCTCs from Xiamen Shipbuilding Industry.", "kImp": "유럽 선사의 중국 조선소 발주 지속은 PCTC 신조 수요와 중국 조선 우위를 재확인한다.", "eImp": "Continued Chinese-yard ordering by a European carrier reaffirms PCTC newbuild demand and China's shipbuilding dominance.", "url": "https://www.bairdmaritime.com/shipping/dry-cargo/dry-cargo-vessel-news-roundup-june-24-focus-on-asian-yards-deliveries-from-china-and-vietnam-plus-swiss-car-carrier-orders"}, {"code": "PCTC", "title": "Mitsubishi adds Texas' Port Freeport to its expanding US distribution network", "src": "Automotive Logistics", "date": "2026-07-08", "kSum": "미쓰비시 자동차 북미법인(Mitsubishi Motors North America)이 텍사스 포트 프리포트(Port Freeport) 및 항만운영사 앰포츠(Amports)와 협약을 맺고 텍사스 걸프 연안을 통한 완성차 물동량을 추가했다. 4월 28일 운영을 시작해 첫 달 500여 대가 도착했고 7월 1일 공식 출범 행사를 가졌다. 걸프 연안·중서부 딜러 배송을 지원한다.", "eSum": "Mitsubishi Motors North America signed an agreement with Texas' Port Freeport and operator Amports to route vehicle volume through the Texas Gulf Coast. Operations began on 28 April with 500-plus vehicles arriving in the first month, formally launched with a 1 July 2026 ribbon-cutting, supporting deliveries to Gulf Coast and Midwest dealers.", "kImp": "신규 항만 게이트웨이 확보는 미국 내 완성차 해상물류 경로 다변화와 배송 속도 개선을 노린 움직임이다.", "eImp": "Adding a new port gateway reflects diversification of US finished-vehicle sea-logistics routes and a push for faster delivery.", "url": "https://www.automotivelogistics.media/vehicle-logistics/mitsubishi-adds-texas-port-freeport-to-its-expanding-us-distribution-networknbsp/2696261"}, {"code": "PCTC", "title": "Sabine Isenbort leads Ford Europe's vehicle logistics", "src": "Automotive Logistics", "date": "2026-07-17", "kSum": "포드(Ford)가 자비네 이젠보르트(Sabine Isenbort)를 유럽 차량물류·통관 담당 이사로 승진 임명했다. 그는 유럽 전역의 완성차 흐름 최적화와 통관 준수를 총괄하게 된다. 2003년 견습으로 입사한 뒤 20여 년간 물류 요직을 거쳤다.", "eSum": "Ford has promoted Sabine Isenbort to director of vehicle logistics and customs for Europe, where she will oversee optimisation of finished-vehicle flows and customs compliance across the region. She joined Ford as a trainee in 2003 and has held logistics leadership roles for over two decades.", "kImp": "완성차 물류 리더십 교체는 유럽 자동차 공급망의 통관·물류 효율화 흐름을 반영한다.", "eImp": "The vehicle-logistics leadership change reflects a drive for customs and logistics efficiency in Europe's automotive supply chain.", "url": "https://www.automotivelogistics.media/news/sabine-isenbort-leads-ford-europes-vehicle-logistics/2701277"}]}, {"code": "WW", "type": "news", "kTitle": "Section 5. 발레니우스 빌헬름센", "eTitle": "Section 5. Wallenius Wilhelmsen", "items": [{"code": "WW", "title": "Wendt promoted as Wallenius Wilhelmsen strengthens breakbulk focus", "src": "Heavy Lift & Project Forwarding International", "date": "2026-06-04", "kSum": "발레니우스 빌헬름센(Wallenius Wilhelmsen)이 카르스텐 벤트(Carsten Wendt)를 유럽·중동·아프리카(EMEA) 산업영업 부사장으로 승진시키며 브레이크벌크 부문에 대한 집중을 강화했다. 이를 위해 베드란 무라트베고비치(Vedran Muratbegovic) 글로벌 산업영업 수석부사장이 이끄는 산업 글로벌 세일즈 조직을 신설했다. 벤트는 유럽발 북미향 하이앤헤비/브레이크벌크 수요가 특히 AI·전력망 확대에 따른 변압기 물동량에 힘입어 견조하다고 언급했다.", "eSum": "Wallenius Wilhelmsen promoted Carsten Wendt to vice president, industrial sales for EMEA, as it strengthened its breakbulk focus by forming a new industrial global sales department headed by Vedran Muratbegovic, SVP global industrial sales. Wendt noted solid H&H/breakbulk demand from Europe to North America, driven notably by transformers for AI and grid networks.", "kImp": "전담 산업영업 조직 신설과 임원 승진은 발레니우스 빌헬름센이 변동성 큰 완성차 시장을 넘어 고마진 브레이크벌크·프로젝트 화물로 사업 다각화를 추진하고 있음을 보여준다.", "eImp": "A dedicated industrial sales unit and the promotion show Wallenius Wilhelmsen diversifying beyond the volatile finished-vehicle market toward higher-margin breakbulk and project cargo.", "url": "https://www.heavyliftpfi.com/news/2026/06/04/wendt-promoted-as-wallenius-wilhelmsen-strengthens-breakbulk-focus/"}, {"code": "WW", "title": "Wallenius Wilhelmsen reports steady 2025, high and heavy volumes lag", "src": "Heavy Lift & Project Forwarding International", "date": "2026-03-23", "kSum": "발레니우스 빌헬름센(Wallenius Wilhelmsen)이 2025년 재무·상업·운영 전반에서 '안정적'이고 '견조한' 실적을 기록했다고 발표했다. 다만 하이앤헤비(High & Heavy) 물동량은 전년 대비 감소했다. 완성차 물류 시황이 뒷받침됐음에도 중량·프로젝트 화물 부문의 약세가 이어졌다.", "eSum": "Wallenius Wilhelmsen reported a 'steady' and 'solid' financial, commercial and operational performance for 2025, though its high and heavy volumes were down year-on-year. Finished-vehicle logistics remained supportive while the heavier project-cargo segment lagged.", "kImp": "연간 실적의 안정성 대비 하이앤헤비 물동량 부진은 발레니우스 빌헬름센의 매출 구성에서 완성차 의존도가 여전히 높음을 보여주며, 중량화물 수요 회복이 향후 실적 개선의 관건임을 시사한다.", "eImp": "Steady annual results alongside lagging high and heavy volumes underline Wallenius Wilhelmsen's continued reliance on finished vehicles, making a recovery in heavy-cargo demand key to future earnings.", "url": "https://www.heavyliftpfi.com/shipping/2026/03/23/wallenius-wilhelmsen-reports-steady-2025-high-and-heavy-volumes-lag/"}, {"code": "WW", "title": "Equinor to supply bio-methanol to Wallenius Wilhelmsen's vessels", "src": "Offshore Energy", "date": "2026-03-11", "kSum": "발레니우스 빌헬름센(Wallenius Wilhelmsen)이 노르웨이 국영 에너지 기업 에퀴노르(Equinor)와 신조 메탄올 이중연료선에 공급할 바이오메탄올 2년 공급 계약을 체결했다. ISCC EU 인증을 받은 매스밸런스 방식의 바이오메탄올은 노르웨이에서 생산돼 벨기에 제브뤼헤·안트베르펜 항에서 공급되며, CO2 배출을 약 95% 저감할 것으로 기대된다. 공급은 2026년 말 시작된다.", "eSum": "Wallenius Wilhelmsen signed a two-year agreement with Norway's state-owned Equinor to supply bio-methanol for its upcoming dual-fuel methanol vessels. The ISCC EU-certified, mass-balanced bio-methanol will be produced in Norway and delivered at the ports of Zeebrugge and Antwerp, cutting CO2 emissions by about 95%, with supplies beginning in late 2026.", "kImp": "저탄소 연료 조달 계약은 발레니우스 빌헬름센의 2027년 넷제로 엔드투엔드 파일럿 서비스 목표를 뒷받침하며, 메탄올 이중연료선 발주에 실제 공급망을 연결하는 핵심 단계다.", "eImp": "Securing low-carbon fuel supply underpins Wallenius Wilhelmsen's target of a net-zero end-to-end pilot service by 2027 and links its methanol dual-fuel newbuild program to a real supply chain.", "url": "https://www.offshore-energy.biz/equinor-to-supply-bio-methanol-to-wallenius-wilhelmsens-vessels/"}, {"code": "WW", "title": "Wallenius Wilhelmsen secures two-year bio-methanol bunker fuel supply from Equinor", "src": "Manifold Times", "date": "2026-03-12", "kSum": "에퀴노르(Equinor)가 발레니우스 빌헬름센(Wallenius Wilhelmsen)과 2년 바이오메탄올 공급 계약을 체결했다고 밝혔다. 바이오메탄올은 에퀴노르의 노르웨이 첼베르그오덴(Tjeldbergodden) 설비에서 생산된 메탄올과 바이오가스 인증서를 결합한 것으로, 제브뤼헤·안트베르펜 항에서 벙커링되며 공급은 2026년 말 개시된다. 크사비에 르루아(Xavier Leroi) 해운서비스 COO는 저탄소 연료 확보가 해상 운영 탈탄소화의 중요한 이정표라고 강조했다.", "eSum": "Equinor said it has entered a two-year bio-methanol supply agreement with Wallenius Wilhelmsen. The fuel, produced from methanol at Equinor's Tjeldbergodden facility combined with biogas certificates, will be bunkered at Zeebrugge and Antwerp from late 2026. COO Shipping Services Xavier Leroi called securing low-carbon fuel an important decarbonization milestone.", "kImp": "에퀴노르가 머스크·NCL에 이어 발레니우스 빌헬름센과도 바이오메탄올 공급을 확대한 것은 메탄올 벙커링 시장의 실제 수요 형성과 대체연료 상업화가 진전되고 있음을 보여준다.", "eImp": "Equinor adding Wallenius Wilhelmsen to its bio-methanol customers after Maersk and NCL shows real demand forming in the methanol bunkering market and progress in commercializing alternative fuels.", "url": "https://www.manifoldtimes.com/news/wallenius-wilhelmsen-secures-two-year-bio-methanol-bunker-fuel-supply-from-equinor/"}, {"code": "WW", "title": "With wind in her sail: Tirranna's wing sail installation completed", "src": "Wallenius Wilhelmsen", "date": "2026-07-02", "kSum": "발레니우스 빌헬름센(Wallenius Wilhelmsen)이 자동차운반선 티란나(Tirranna)에 윙세일(Oceanbird Wing560) 설치를 완료하며 상업 운항 중 풍력보조추진 실증의 새 단계에 진입했다. 설치는 6월 22~24일 로테르담 다멘(Damen) 조선소에서 이뤄졌고 해상 인수시험(SAT)은 7월 1일 완료됐으며, 약 10%의 연료 효율 개선을 목표로 한다. 이 실증은 EU 자금 지원을 받는 11개 파트너의 오르셀 호라이즌(Orcelle Horizon) 프로젝트의 일환이다.", "eSum": "Wallenius Wilhelmsen completed the installation of a wing sail (Oceanbird Wing560) on the car carrier Tirranna, entering a new phase of testing wind-assisted propulsion in commercial operation. The installation took place on 22-24 June at Damen Shipyard in Rotterdam, with the sea acceptance test completed on 1 July, targeting roughly 10% fuel efficiency gains. It marks a milestone in the EU-funded Orcelle Horizon project with eleven partners.", "kImp": "실제 운항선을 활용한 풍력보조추진 실증은 발레니우스 빌헬름센의 다중 기술 병행 탈탄소 전략을 보여주며, 향후 다중 윙세일을 탑재할 신조선 오르셀 윈드(Orcelle Wind) 설계에 필요한 실측 데이터를 제공한다.", "eImp": "Full-scale wind-assist testing on an operating vessel showcases Wallenius Wilhelmsen's parallel-technology decarbonization strategy and supplies real-world data for the future multi-wing Orcelle Wind newbuild.", "url": "https://www.walleniuswilhelmsen.com/news/with-wind-in-her-sail-tirrannas-wing-sail-installation-completed"}, {"code": "WW", "title": "Wallenius Wilhelmsen takes delivery of first Shaper Class vessel Arctic Tern", "src": "The Maritime Executive", "date": "2026-07-09", "kSum": "발레니우스 빌헬름센(Wallenius Wilhelmsen)이 신형 셰이퍼 클래스(Shaper Class)의 첫 선박 아틱 턴(Arctic Tern, 15,750 DWT)을 인도받았다. 중국 차이나머천츠 진링(China Merchants Jinling) 조선소(난징)에서 건조된 이 메탄올 이중연료선은 최초 발주된 6척의 9,300 CEU 시리즈 중 첫 번째로, 발주는 8척의 11,700 CEU 확대 사양을 포함하도록 수차례 변경됐다. 선박은 발레니우스 빌헬름센(80%)과 현대자동차그룹(Hyundai Motor Group, 20%)의 합작사 유코(EUKOR)를 통해 아시아-유럽 항로에 투입된다.", "eSum": "Wallenius Wilhelmsen took delivery of Arctic Tern (15,750 dwt), the first vessel in its new Shaper Class. Built at China Merchants Jinling Shipyard in Nanjing, the methanol dual-fuel ship is the first of six 9,300 CEU units initially ordered, an order revised several times to include eight vessels upsized to 11,700 CEU. It will operate on the Asia-Europe route via EUKOR, the joint venture between Wallenius Wilhelmsen (80%) and Hyundai Motor Group (20%).", "kImp": "셰이퍼 클래스 1번선 인도는 발레니우스 빌헬름센과 자동차운반선 업계 전반에 상징적 이정표로, 2027년 넷제로 엔드투엔드 서비스 목표 실현을 위한 핵심 구성요소이자 메탄올 연료 전환의 가속을 의미한다.", "eImp": "Delivery of the first Shaper Class vessel is a defining milestone for Wallenius Wilhelmsen and the car-carrier sector, forming a critical building block for its 2027 net-zero end-to-end goal and accelerating the shift to methanol fuel.", "url": "https://maritime-executive.com/article/wallenius-wilhelmsen-takes-delivery-of-large-methanol-fueled-car-carrier"}, {"code": "WW", "title": "Methanol-Ready Arctic Tern PCTC Joins Wallenius Wilhelmsen Fleet", "src": "MarineLink", "date": "2026-07-09", "kSum": "발레니우스 빌헬름센(Wallenius Wilhelmsen)이 신형 셰이퍼 클래스(Shaper Class)의 첫 메탄올 대응 이중연료선 아틱 턴(Arctic Tern)을 인도받아 유코(EUKOR)를 통해 아시아-유럽 항로에 즉시 투입한다. 이 선박부터 지구를 오가는 장거리 이동 조류의 이름을 따는 명명 전통이 시작됐으며, 아틱 턴은 세계에서 가장 긴 이동을 하는 북극제비갈매기에서 유래했다. 발레니우스 마린(Wallenius Marine)이 조선소 현장 관리를, 빌헬름센 십 매니지먼트(Wilhelmsen Ship Management)가 상업 운항 및 선박 관리를 맡는다.", "eSum": "Wallenius Wilhelmsen took delivery of Arctic Tern, the first dual-fuel methanol-ready vessel in its new Shaper Class, entering Asia-Europe service almost immediately via EUKOR. The delivery begins a naming tradition using birds known for long global journeys, with Wallenius Marine handling site management and Wilhelmsen Ship Management responsible for commercial operations and ship management.", "kImp": "빌헬름센 십 매니지먼트가 최첨단 메탄올 이중연료선의 기술관리를 맡는다는 점은 그룹 내 선박관리 역량이 차세대 대체연료선 운영의 핵심 축임을 부각한다.", "eImp": "Wilhelmsen Ship Management taking on technical management of the cutting-edge methanol dual-fuel vessel highlights in-group ship management as a key pillar for operating next-generation alternative-fuel ships.", "url": "https://www.marinelink.com/news/methanolready-arctic-tern-pctc-joins-541076"}, {"code": "WW", "title": "Wallenius Wilhelmsen takes delivery of methanol dual-fuel car carrier", "src": "Baird Maritime", "date": "2026-07-10", "kSum": "발레니우스 빌헬름센(Wallenius Wilhelmsen)이 차이나머천츠 진링(China Merchants Jinling) 조선소에서 건조한 신형 PCTC 아틱 턴(Arctic Tern)을 인도받았다. 마셜제도 선적의 이 선박은 전장 228m, 폭 38m, 재화중량 15,750, 적재능력 9,300 CEU다. 동일 시리즈로 9,300 CEU 5척과 11,700 CEU 8척 등 13척이 추가 건조되며, 확대 사양 선박은 2027년 말부터 인도된다.", "eSum": "Wallenius Wilhelmsen took delivery of Arctic Tern, a new PCTC built by China Merchants Jinling Shipyard. The Marshall Islands-flagged vessel measures 228 m LOA, 38 m beam, 15,750 dwt and 9,300 CEU capacity. Thirteen more ships in the series will be built, including five 9,300 CEU and eight 11,700 CEU units, with the upsized vessels to be delivered from late 2027.", "kImp": "총 14척 규모의 셰이퍼 클래스 발주는 발레니우스 빌헬름센이 세계 최대 규모의 메탄올 이중연료 자동차운반선 선대를 구축하고 있음을 보여주며, 선복 확대와 탈탄소를 동시에 추진하는 전략을 뒷받침한다.", "eImp": "The 14-ship Shaper Class program shows Wallenius Wilhelmsen building one of the world's largest methanol dual-fuel car-carrier fleets, advancing capacity growth and decarbonization in tandem.", "url": "https://www.bairdmaritime.com/shipping/dry-cargo/pcc-pctc/wallenius-wilhelmsen-takes-delivery-of-methanol-dual-fuel-car-carrier"}, {"code": "WW", "title": "Wallenius Wilhelmsen's New Vessel Set for First Methanol Bunkering", "src": "Ship & Bunker", "date": "2026-07-10", "kSum": "발레니우스 빌헬름센(Wallenius Wilhelmsen)이 신형 셰이퍼 클래스(Shaper Class)의 첫 메탄올 연료선 아틱 턴(Arctic Tern)을 인도받았으며, 취항 직후 첫 메탄올 벙커링을 완료할 예정이다. 이 이중연료 PCTC는 현대자동차그룹(Hyundai Motor Group)과의 합작사 유코(EUKOR)를 통해 아시아-유럽 항로에 투입된다. 회사는 첫 메탄올 벙커링 장소는 공개하지 않았다.", "eSum": "Wallenius Wilhelmsen took delivery of Arctic Tern, the first methanol-fuelled ship in its new Shaper Class, which is expected to complete its first methanol bunkering shortly after entering service. The dual-fuel PCTC will be deployed on the Asia-Europe route via EUKOR, the joint venture with Hyundai Motor Group, though the location of the first bunkering was not disclosed.", "kImp": "첫 메탄올 벙커링 예고는 대체연료 공급 인프라와 선박 운영이 실제로 맞물리기 시작했음을 보여주며, 메탄올을 실용적 대체연료로 활용하려는 발레니우스 빌헬름센의 탈탄소 여정에서 중요한 단계다.", "eImp": "The planned first methanol bunkering shows alternative-fuel supply infrastructure and vessel operations beginning to align in practice, a key step in Wallenius Wilhelmsen's decarbonization journey toward methanol as a practical fuel.", "url": "https://shipandbunker.com/news/world/362719-wallenius-wilhelmsens-new-vessel-set-for-first-methanol-bunkering"}, {"code": "WW", "title": "Arctic Tern joins the Wallenius Wilhelmsen fleet", "src": "Heavy Lift & Project Forwarding International", "date": "2026-07-09", "kSum": "발레니우스 빌헬름센(Wallenius Wilhelmsen)이 셰이퍼 클래스(Shaper Class) 시리즈의 첫 선박 아틱 턴(Arctic Tern)을 인도받았다. 이 이중연료 메탄올 대응 선박은 현대자동차그룹(Hyundai Motor Group)과 발레니우스 빌헬름센의 합작 선사 유코(EUKOR)가 운항한다. 신형 선박은 하이앤헤비 화물 능력과 에너지 효율을 강화한 사양을 갖췄다.", "eSum": "Wallenius Wilhelmsen took delivery of Arctic Tern, the first vessel in its Shaper-class series. The dual-fuel, methanol-ready ship will be deployed by EUKOR, the jointly owned shipping line of Hyundai Motor Group and Wallenius Wilhelmsen. The newbuild features enhanced high and heavy capacity and improved energy efficiency.", "kImp": "셰이퍼 클래스 선박이 하이앤헤비 화물 대응력을 강화한 점은 발레니우스 빌헬름센이 완성차뿐 아니라 브레이크벌크·중량화물 시장까지 아우르는 통합 선대를 지향함을 보여준다.", "eImp": "The Shaper Class ships' enhanced high and heavy capability shows Wallenius Wilhelmsen aiming for an integrated fleet spanning finished vehicles as well as breakbulk and heavy cargo.", "url": "https://www.heavyliftpfi.com/news/2026/07/09/arctic-tern-joins-the-wallenius-wilhelmsen-fleet/"}, {"code": "WW", "title": "Wallenius Wilhelmsen begins operations at Gothenburg RoRo terminal (GIART)", "src": "Heavy Lift & Project Forwarding International", "date": "2026-02-02", "kSum": "발레니우스 빌헬름센(Wallenius Wilhelmsen)이 스웨덴 예테보리 국제 자동차·로로 터미널(GIART)에서 12년 컨세션 계약에 따라 공식 운영을 시작했다. 기존 운영사 로젠트(Logent)로부터 인수했으며, 별도 법인을 설립하고 인프라 현대화에 600만 유로를 투자한다.", "eSum": "Wallenius Wilhelmsen officially commenced operations at the Gothenburg International Auto & RoRo Terminal (GIART) under a 12-year concession, taking over from Logent and investing EUR6m to modernise the facility.", "kImp": "예테보리는 스웨덴 최대 자동차 항만으로, 이번 인수로 발레니우스 빌헬름센은 유럽 로로 터미널 네트워크를 북유럽까지 확장하고 자체 물류 허브 경쟁력을 강화한다.", "eImp": "Gothenburg is Sweden's largest vehicle port; the deal extends Wallenius Wilhelmsen's European ro-ro terminal network into the Nordics and strengthens its integrated logistics hub.", "url": "https://www.heavyliftpfi.com/ports-and-terminals/2026/02/02/wallenius-wilhelmsen-begins-operations-at-gothenburg-roro-terminal/"}, {"code": "WW", "title": "Port of Galveston opens new cargo berth with Wallenius Wilhelmsen's Toledo as first caller", "src": "Baird Maritime", "date": "2026-07-08", "kSum": "미국 텍사스 갤버스턴항(Port of Galveston)이 신규 화물 부두를 개장했으며, 발레니우스 빌헬름센(Wallenius Wilhelmsen)의 자동차운반선 톨레도(Toledo)호가 첫 입항 선박이 됐다. 갤버스턴은 발레니우스 빌헬름센의 미국 내 주요 운영 거점 중 하나다.", "eSum": "The Port of Galveston, Texas opened a new cargo berth, with Wallenius Wilhelmsen's car carrier Toledo becoming the first vessel to call. Galveston is one of the group's key US operating locations.", "kImp": "신규 부두는 발레니우스 빌헬름센의 로로·브레이크벌크 화물 처리 능력을 확대하고, 미주 지역 터미널·물류 네트워크 경쟁력을 높인다.", "eImp": "The new berth expands handling capacity for Wallenius Wilhelmsen's ro-ro and breakbulk cargo, reinforcing its Americas terminal and logistics network.", "url": "https://www.bairdmaritime.com/shipping/ports/port-of-galveston-opens-new-cargo-berth-with-first-vessel-arrival"}]}, {"code": "EE", "type": "news", "kTitle": "Section 6. 에너지 효율·탈탄소", "eTitle": "Section 6. Energy Efficiency", "items": [{"code": "EE", "title": "Energy-Efficiency Measures First says DNV Maritime CEO", "src": "MarineLink", "date": "2026-07-06", "kSum": "DNV 해사부문 CEO 크리스티나 사엔스 데 산타 마리아(Cristina Saenz de Santa Maria)는 대체연료가 성숙하기까지 시간이 걸리는 만큼 기존 선대의 에너지효율 조치가 단기 탈탄소의 핵심 지렛대라고 강조했다. DNV의 '2050 해사 전망'에 따르면 에너지효율 조치만으로 2030년까지 연료 소비를 최대 16% 줄일 수 있다.", "eSum": "DNV Maritime CEO Cristina Saenz de Santa Maria argues energy-efficiency measures are the key short-term decarbonisation lever for the existing fleet while alternative fuels mature. DNV's Maritime Forecast to 2050 finds such measures can cut fuel use by up to 16% by 2030.", "kImp": "연료 가격 급등으로 축발전기 등 효율 개조의 투자회수 기간이 크게 단축되고 있어, 단편적 대응보다 전략적 로드맵과 제3자 검증의 가치가 커지고 있다.", "eImp": "Rising fuel prices are sharply shortening payback on efficiency retrofits, making a strategic, independently verified roadmap—rather than piecemeal compliance—increasingly valuable.", "url": "https://www.marinelink.com/news/energyefficiency-measures-first-says-dnv-540925"}, {"code": "EE", "title": "KR, HD Hyundai Complete Korea's First Ammonia Vessel Trial", "src": "MarineLink", "date": "2026-07-14", "kSum": "한국선급(KR)과 HD현대중공업(HHI)이 한국 최초의 암모니아 이중연료선 시운전을 완료했다. 이는 국내 암모니아 추진 선박의 상용화를 향한 중요한 이정표로 평가된다.", "eSum": "Korean Register (KR) and HD Hyundai Heavy Industries (HHI) have completed the sea trial of South Korea's first ammonia dual-fuel vessel, a milestone toward commercial ammonia-powered shipping.", "kImp": "무탄소 연료 후보인 암모니아의 실증 진전은 한국 조선·선급의 역량을 보여주며, 안전 기준과 공급망 정비가 뒷받침되어야 상용화가 가속될 수 있다.", "eImp": "Progress on ammonia—a zero-carbon fuel candidate—showcases Korean yard and class capability, though safety standards and supply chains must follow for commercial scale-up.", "url": "https://www.marinelink.com/news/kr-hd-hyundai-complete-koreas-first-541195"}, {"code": "EE", "title": "Uni-Tankers implements Sofar Ocean platform for voyage optimisation", "src": "Smart Maritime Network", "date": "2026-07-02", "kSum": "덴마크 탱커 선사 유니탱커스(Uni-Tankers)가 소파 오션(Sofar Ocean)의 웨이파인더(Wayfinder) 항해 최적화 플랫폼을 전 선대 44척에 도입한다. 실시간 기상 정보와 선박별 디지털 트윈을 활용해 항로·속도 결정을 지원한다.", "eSum": "Danish tanker owner Uni-Tankers is deploying Sofar Ocean's Wayfinder voyage-optimisation platform across its 44-ship fleet, using real-time weather data and vessel-specific digital twins to guide route and speed decisions.", "kImp": "소파 오션은 플랫폼 사용 선사가 항해당 평균 6.9%의 연료를 절감했다고 밝혀, 저비용 운항 최적화가 즉각적인 효율·배출 저감 수단임을 보여준다.", "eImp": "Sofar Ocean reports average per-voyage fuel savings of 6.9%, underscoring low-cost voyage optimisation as an immediate efficiency and emissions lever.", "url": "https://smartmaritimenetwork.com/2026/07/02/uni-tankers-implements-sofar-ocean-platform-for-voyage-optimisation/"}, {"code": "EE", "title": "OOCL conducts first methanol bunkering of its new dual-fuel container ship", "src": "SAFETY4SEA", "date": "2026-07-06", "kSum": "OOCL이 신조 메탄올 이중연료 컨테이너선에 대해 첫 메탄올 벙커링을 실시했다. 이는 대형 컨테이너 선사의 메탄올 연료 상용 운항 준비가 진전되고 있음을 보여준다.", "eSum": "OOCL has conducted the first methanol bunkering of its new dual-fuel container ship, marking progress in commercial methanol-fuelled operations for a major box carrier.", "kImp": "메탄올 벙커링 실증은 저탄소 연료 공급망의 성숙을 알리는 신호이나, 그린 메탄올 물량 확보가 여전히 핵심 관건으로 남아 있다.", "eImp": "The bunkering demonstrates maturing low-carbon fuel supply chains, though securing green methanol volumes remains the key constraint.", "url": "https://safety4sea.com/oocl-conducts-fist-methanol-bunkering-of-its-new-dual-fuel-container-ship/"}, {"code": "EE", "title": "CMA CGM Notre Dame takes on first European bio-LNG in Rotterdam", "src": "Seatrade Maritime News", "date": "2026-07-10", "kSum": "CMA CGM의 'CMA CGM Notre Dame'호가 로테르담에서 유럽 최초로 바이오-LNG를 공급받았다. 이는 LNG 이중연료선의 온실가스 집약도를 낮추기 위한 실질적 조치다.", "eSum": "CMA CGM's Notre Dame has taken on the first European bio-LNG bunkering in Rotterdam, a practical step to cut the greenhouse-gas intensity of LNG dual-fuel vessels.", "kImp": "바이오-LNG는 기존 LNG 인프라를 그대로 활용해 FuelEU·EU ETS 부담을 완화할 수 있는 드롭인 연료로, 컨테이너 선사의 단기 탈탄소 경로로 부상하고 있다.", "eImp": "Bio-LNG is a drop-in fuel leveraging existing LNG infrastructure to ease FuelEU and EU ETS burdens, emerging as a near-term decarbonisation path for box carriers.", "url": "https://www.seatrade-maritime.com/containers/cma-cgm-notre-dame-takes-on-first-european-bio-lng-in-rotterdam"}, {"code": "EE", "title": "GTT's New LR-Approved NO96 Criteria Expand LNG Carrier Design Flexibility", "src": "Offshore Energy", "date": "2026-07-16", "kSum": "지티티(GTT, Gaztransport & Technigaz)가 로이드선급(Lloyd's Register, LR)으로부터 NO96 화물창 시스템의 새로운 신장(elongation) 기준에 대한 기본승인(AiP)을 획득했다. 개정 기준은 멤브레인·단열재 하부의 허용 선체 변형에 관한 것으로, 확립된 안전 마진을 유지하면서 선체 구조 설계의 유연성을 높인다. 경량화 등 구조 최적화를 통해 LNG선의 효율 개선 여지를 넓힌다.", "eSum": "GTT secured an Approval in Principle (AiP) from Lloyd's Register (LR) for new elongation criteria for its NO96 cargo containment system. The revised criteria govern allowable hull deformation beneath the membrane and insulation, giving designers greater structural flexibility while preserving established safety margins. Structural optimisation, including lightship weight benefits, widens efficiency potential for LNG carriers.", "kImp": "화물창·선체 구조 최적화는 LNG선의 경량화와 연비 개선으로 이어져 에너지효율설계지수(EEDI/EEXI)·탄소집약도지수(CII) 대응에 기여한다. 선급 승인을 통한 조기 기술 검증은 신조 설계 단계에서 효율성과 규제 준수를 동시에 확보하는 경로를 제시한다.", "eImp": "Containment/hull structural optimisation supports lighter LNG carriers and better fuel economy, aiding EEDI/EEXI and CII compliance. Early class validation offers a pathway to secure both efficiency and regulatory compliance at the newbuild design stage.", "url": "https://www.offshore-energy.biz/gtts-new-lr-approved-no96-criteria-expand-lng-carrier-design-flexibility/"}]}, {"code": "DIG", "type": "news", "kTitle": "Section 7. 디지털라이제이션", "eTitle": "Section 7. Digitalization", "items": [{"code": "DIG", "title": "HMM, 자율운항 시스템 배치 확대… 33척 설치 완료", "src": "Smart Maritime Network", "date": "2026-07-16", "kSum": "국내 선사 HMM(에이치엠엠)이 아비커스(Avikus)의 자율운항 시스템 하이나스 컨트롤(HiNAS Control)을 목표 44척 중 33척(75%)에 설치 완료했으며 연내 프로젝트 마무리를 목표로 하고 있다. 이 시스템은 IMO 2단계 자율운항 기준을 충족하며 14km 반경 내 충돌 위험을 탐지하고 최적 항로·속도를 제안한다. HMM은 2030년까지 직접 보유 컨테이너선·벌크선 123척 전체로 확대할 계획이다.", "eSum": "South Korea's HMM has completed installation of Avikus's HiNAS Control autonomous navigation system on 33 of a targeted 44 vessels (75%), aiming to finish the project this year. The system meets IMO Stage 2 autonomy standards, detects collision risks within 14 km and suggests optimal routing and speed. HMM plans to extend the technology to its entire fleet of 123 directly owned container ships and bulk carriers by 2030.", "kImp": "국내 대형 선사가 상선단에 자율운항 기술을 실제 대규모로 확산시키는 사례로, 약 4%의 연료비 절감(연 약 420억 원 추정) 효과가 제시되어 자율운항의 경제성이 구체화되고 있다.", "eImp": "A rare large-scale, real-world rollout of autonomous navigation across a major commercial fleet, with an estimated ~4% fuel cost saving making the economics of autonomy increasingly concrete.", "url": "https://smartmaritimenetwork.com/2026/07/16/hmm-ramps-up-deployment-of-autonomous-navigation-tech/"}, {"code": "DIG", "title": "이리듐, GNSS 재밍·스푸핑 대응 PNT 칩 출시", "src": "Smart Maritime Network", "date": "2026-07-14", "kSum": "이리듐(Iridium)이 위성 의존 장비를 재밍·스푸핑으로부터 보호하는 신형 측위·항법·시각(PNT) 칩을 상용 출시했다. 8×8mm, 0.2g 미만의 초소형 ASIC로 이리듐 위성망을 통해 암호학적으로 안전한 시각·위치 데이터를 제공하며, 2025년 10월 공개 이후 해운·무인기·항공 등 150개 이상 기관이 관심을 표했다. 솔레이스 커뮤니케이션스(Solace Communications)가 첫 통합 파트너로 자사 벡터(Vector) 장비에 적용한다.", "eSum": "Iridium has commercially launched a new positioning, navigation and timing (PNT) chip to protect satellite-dependent hardware from jamming and spoofing. The 8x8mm ASIC weighing under 0.2g delivers cryptographically secure timing and location data via the Iridium network, drawing interest from more than 150 organisations across maritime, unmanned vehicle and aviation sectors since its October 2025 preview. Solace Communications is among the first partners, integrating it into its Vector resilient PNT hardware.", "kImp": "GNSS 재밍·스푸핑이 급증하는 상황에서 위성 기반 대체 PNT를 소형·저전력 하드웨어에 내장할 수 있게 되어 항법 신뢰성 확보와 e-내비게이션 보안 강화에 직접적으로 기여한다.", "eImp": "With GNSS jamming and spoofing rising sharply, embedding satellite-based resilient PNT into small, low-power hardware directly strengthens navigation trust and e-navigation security.", "url": "https://smartmaritimenetwork.com/2026/07/14/iridium-launches-pnt-chip-to-counter-gnss-jamming/"}, {"code": "DIG", "title": "아티카 그룹, ABB 원박스로 선단 실시간 모니터링 도입", "src": "Smart Maritime Network", "date": "2026-07-16", "kSum": "그리스 페리 운항사 아티카 그룹(Attica Group)이 ABB와 손잡고 선단 전체에 통합 실시간 모니터링 시스템을 도입했다. ABB 어빌리티 원박스(ABB Ability OneBox) 기술 기반으로 운항·전력·연료 소비 데이터를 단일 대시보드로 통합하며, 슈퍼패스트 I·II 파일럿을 거쳐 현재 33척 중 17척에서 가동 중이다. 목표는 항해별 연료 최적화와 운항 이슈의 선제적 대응이다.", "eSum": "Greek ferry operator Attica Group has partnered with ABB to deploy an integrated real-time monitoring system across its fleet. Based on ABB Ability OneBox marine signals technology, it consolidates operational, electrical and fuel consumption data into a single dashboard and is now live on 17 of the operator's 33 vessels after a pilot on Superfast I and II. The goal is per-voyage fuel optimisation and proactive handling of operational issues.", "kImp": "IoT 센서 데이터를 단일 대시보드로 통합해 실시간 성능 가시성을 확보하는 사례로, 연료 효율과 운항 최적화를 위한 선단 단위 디지털 모니터링 확산 흐름을 보여준다.", "eImp": "A concrete case of consolidating IoT sensor data into one dashboard for real-time performance visibility, illustrating the spread of fleet-wide digital monitoring for fuel efficiency and operational optimisation.", "url": "https://smartmaritimenetwork.com/2026/07/16/attica-group-deploys-real-time-monitoring-fleetwide/"}, {"code": "DIG", "title": "매직포트, 항만 기항 디지털화 위해 300만 달러 유치", "src": "Splash247", "date": "2026-07-10", "kSum": "해운 소프트웨어 스타트업 매직포트(MagicPort)가 항만 기항 관리용 AI 플랫폼 확장을 위해 프리시드 라운드에서 300만 달러를 유치했다. 이 플랫폼은 선주·선박대리점 등 이해관계자가 단일 디지털 환경에서 기항을 조율하도록 지원하며, 이미 80여 개국 300개 이상 기업이 사용 중이다. 항만 기항은 여전히 이메일·스프레드시트에 의존하는 해운업의 최저 디지털화 영역 중 하나다.", "eSum": "Maritime software startup MagicPort has raised $3m in a pre-seed round to expand its AI platform for port call management. The platform helps shipowners, ship agents and other stakeholders coordinate port calls in a single digital environment and is already used by more than 300 companies across over 80 countries. Port calls remain one of shipping's least digitalised processes, still reliant on emails and spreadsheets.", "kImp": "기항 최적화는 지연 감소·자산 활용·행정비용 절감에 직결되며, 투자 유치는 해운 디지털화가 가장 파편화된 영역까지 확대되고 있음을 보여준다.", "eImp": "Port call optimisation directly cuts delays, improves asset utilisation and reduces admin costs; the funding shows maritime digitalisation reaching even its most fragmented processes.", "url": "https://splash247.com/magicport-lands-3m-to-accelerate-port-call-digitalisation/"}, {"code": "DIG", "title": "美 해안경비대: 해양 사이버 사고 17% 증가", "src": "SAFETY4SEA", "date": "2026-07-08", "kSum": "미국 해안경비대 사이버사령부(USCG Cyber Command)의 다섯 번째 연례 해양환경 사이버 동향 보고서가 발표되어, 해양 부문 사이버 사고가 17% 증가한 것으로 나타났다. 피싱, AI 악용, 운영기술(OT) 리스크가 위협 지형을 재편하고 있다. 스마트십 확산으로 실시간 모니터링·예지정비·원격운영 데이터가 급증하면서 공격 표면도 함께 확대되고 있다.", "eSum": "The fifth annual Cyber Trends and Insights in the Marine Environment report from USCG Cyber Command shows maritime cyber incidents rose 17%. Phishing, AI misuse and operational technology (OT) risks are reshaping the threat landscape. As smart ships proliferate, surging data for real-time monitoring, predictive maintenance and remote operations is simultaneously expanding the attack surface.", "kImp": "초연결 해운에서 사이버 위험이 IT를 넘어 안전·규제·경영 리스크로 부상하고 있음을 공식 데이터로 확인시켜, 선사의 사이버 회복력 투자 필요성을 부각한다.", "eImp": "Official data confirming cyber risk in hyper-connected shipping is moving beyond IT into safety, regulatory and business risk, underscoring the need for owners to invest in cyber resilience.", "url": "https://safety4sea.com/uscg-maritime-cyber-incidents-rise-17-as-phishing-ai-and-ot-risks-reshape-the-threat-landscape/"}, {"code": "DIG", "title": "안젤리쿠시스 그룹, 140척 이상에 스타링크 연결 확대", "src": "SAFETY4SEA", "date": "2026-07-08", "kSum": "그리스 선사 안젤리쿠시스 그룹(Angelicoussis Group)이 140척 이상 선박에 스타링크(Starlink) 저궤도(LEO) 위성망을 장착해 글로벌 선단 연결성을 강화했다. 고속·저지연 서비스로 실시간 데이터·영상·텔레메트리 교환이 가능해졌다. '집과 같은' 선상 인터넷은 젊은 선원 유치·유지에도 뚜렷한 강점이 되고 있다.", "eSum": "Greek owner Angelicoussis Group has equipped more than 140 vessels with Starlink's low-Earth orbit (LEO) satellite network, strengthening connectivity across its global fleet. The high-speed, low-latency service enables real-time exchange of data, video and telemetry. 'Home-like' internet at sea is also proving a clear advantage in attracting and retaining younger seafarers.", "kImp": "대형 선단의 LEO 위성 전면 도입은 실시간 데이터 기반 운영과 원격 지원, 선원 복지를 동시에 끌어올리며 해운 디지털화의 기반 인프라 전환을 가속한다.", "eImp": "A large fleet's wholesale adoption of LEO connectivity simultaneously boosts data-driven operations, remote support and crew welfare, accelerating the shift in shipping's foundational digital infrastructure.", "url": "https://safety4sea.com/angelicoussis-group-expands-fleet-connectivity-on-more-than-140-vessels/"}, {"code": "DIG", "title": "인도선급, 선급규칙 디지털 플랫폼 'NEURON' 출시", "src": "Container News", "date": "2026-07-16", "kSum": "인도선급(Indian Register of Shipping, IRS)이 기술규칙·지침·선급 간행물에 대한 빠른 접근을 제공하는 디지털 플랫폼 뉴런(NEURON)을 출시했다. IRClass 규칙, 선급 노트, 지침 등을 단일 검색 인터페이스로 통합해 여러 문서를 오갈 필요를 줄였다. 선주·조선소·설계사·검사원·규제기관 등 폭넓은 이용자를 대상으로 하며 IRS 디지털 전환 전략의 일환이다.", "eSum": "The Indian Register of Shipping (IRS) has launched NEURON, a digital platform providing faster access to its technical rules, guidance and classification publications. It gives users a single searchable interface for IRClass Rules, Classification Notes and guidelines, cutting the need to navigate multiple documents. Aimed at shipowners, shipyards, designers, surveyors and regulators, it forms part of the IRS's broader digital transformation strategy.", "kImp": "선급들이 전통적 검사 업무를 넘어 온라인 플랫폼·디지털 검사 도구·데이터 기반 서비스에 투자를 확대하고 있음을 보여주는 사례로, 규제·기술 정보 접근성 향상에 기여한다.", "eImp": "An example of classification societies investing beyond traditional survey work into online platforms, digital survey tools and data-driven services, improving access to regulatory and technical information.", "url": "https://container-news.com/indian-register-of-shipping-launches-neuron-digital-platform/"}]}, {"code": "TECH", "type": "news", "kTitle": "Section 8. 선박관리 기술", "eTitle": "Section 8. Ship Manager Technical", "items": [{"code": "TECH", "title": "Kongsberg Maritime to acquire Berg Propulsion, expanding CPP/thruster and hybrid propulsion portfolio", "src": "MarineLink", "date": "2026-07-13", "kSum": "콩스버그 마리타임(Kongsberg Maritime)이 스웨덴 추진 전문업체 베르그 프로펄션(Berg Propulsion) 인수에 합의했다. 베르그는 약 4,000척의 설치 실적과 가변피치프로펠러(CPP)·스러스터·하이브리드 추진 시스템을 보유하며, 인수 후에도 별도 브랜드·사업부로 운영된다. 이번 인수로 일반화물선·석유제품운반선 등 물량 시장까지 추진 포트폴리오와 애프터마켓 지원이 확대된다.", "eSum": "Kongsberg Maritime has agreed to acquire Sweden's Berg Propulsion, a maker of integrated propulsion and electrical systems with an installed base of around 4,000 vessels. Berg will continue as a separate brand and standalone business unit within Kongsberg's Propulsion & Handling division. The combined portfolio covers controllable pitch propellers, thrusters, and hybrid/electric propulsion, with expanded global aftermarket support.", "kImp": "기술감독 관점에서 CPP·스러스터·하이브리드 추진 계통의 OEM 공급·부품·서비스 네트워크가 통합되면 스페어 조달과 라이프사이클 지원 접점이 넓어진다. 향후 신조·개조 시 추진 계통 벤더 선정과 애프터서비스 대응에 영향을 줄 수 있어 주시 필요.", "eImp": "For a technical superintendent, consolidation of CPP/thruster/hybrid OEM supply and service networks broadens spare-parts sourcing and lifecycle support touchpoints, and may affect propulsion vendor selection and aftermarket coverage for newbuilds and retrofits.", "url": "https://www.marinelink.com/news/kongsberg-maritime-acquire-berg-541159"}, {"code": "TECH", "title": "Wartsila signs five-year FSRU lifecycle agreement with Pardus Energy for Turquoise P", "src": "Offshore Energy", "date": "2026-07-15", "kSum": "바르질라(Wartsila)가 파르두스 에너지(Pardus Energy)와 튀르키예 알리아가 소재 FSRU 튀르쿠아즈 P(Turquoise P)에 대한 5년 라이프사이클 계약을 체결했다. 계약에는 전담 계약관리, 정비 계획, OEM 순정 부품 공급이 포함되며 36K·48K 대정비(오버홀) 대비를 지원한다. 계약은 2026년 4월부터 발효됐고 수주는 2026년 2분기에 계상됐다.", "eSum": "Wartsila has signed a five-year lifecycle agreement with Ireland-based Pardus Energy to support the FSRU Turquoise P at an LNG terminal in Aliaga, Turkiye. The deal provides dedicated contract management, maintenance planning, and OEM spare parts, and prepares for major planned 36K and 48K overhauls. It gives the operator cost predictability and timely access to OEM parts to reduce unplanned downtime.", "kImp": "장기 라이프사이클·부품 계약 모델은 계획정비 예측성과 순정 부품 가용성을 높여 비계획 정지 리스크를 낮춘다. 기술감독은 유사 OEM 장기계약이 대정비 주기 관리와 총소유비용(TCO)에 주는 실무적 이점을 벤치마크할 수 있다.", "eImp": "Long-term OEM lifecycle and spare-parts agreements improve planned-maintenance predictability and OEM parts availability, cutting unplanned downtime. Superintendents can benchmark this model for overhaul-cycle management and total cost of ownership.", "url": "https://www.offshore-energy.biz/wartsila-scores-multi-year-lifecycle-assignment-for-turkiye-based-fsru/"}, {"code": "TECH", "title": "WE Tech Solutions and Everllence to develop PTO/VFD retrofit packages for dry dockings", "src": "Container News", "date": "2026-07-15", "kSum": "WE 테크 솔루션스(WE Tech Solutions)와 에버런스(Everllence, 구 MAN Energy Solutions)가 해운 전기화·탈탄소 솔루션 개발을 위한 MOU를 포시도니아(Posidonia) 2026에서 체결했다. 첫 공동사업으로 2·4행정 선박용 축발전기(PTO)·가변주파수드라이브(VFD) 개조 패키지를 드라이도킹 중 적용하도록 개발하며, 최대 33척 파일럿도 논의 중이다. 이 개조는 보조엔진 사용을 줄여 연료소비·배출을 낮춘다.", "eSum": "WE Tech Solutions and Everllence signed an MoU to develop electrification and decarbonisation solutions, expanding the PrimeServ Omnicare portfolio. Their first initiative is Power Take-Off (PTO) and Variable Frequency Drive (VFD) retrofit packages for two- and four-stroke vessels during dry dockings, with a pilot of up to 33 vessels under discussion. The retrofit reduces auxiliary engine use, lowering fuel consumption and emissions regardless of engine maker.", "kImp": "드라이도킹 중 적용 가능한 PTO/VFD 개조는 보조엔진 가동 축소를 통한 연비·배출 개선의 실무적 옵션이다. 특히 리퍼 부하가 큰 컨테이너선·LNG선의 전력관리 최적화 및 개조 계획 수립에 참고할 만하다.", "eImp": "PTO/VFD retrofits applied during dry docking offer a practical route to cut auxiliary-engine running for fuel and emissions savings. Relevant for planning power-management upgrades on high-electrical-demand vessels such as reefer-heavy container ships and LNG carriers.", "url": "https://container-news.com/we-tech-solutions-and-everllence-partner-on-maritime-decarbonisation/"}, {"code": "TECH", "title": "Everllence wins first ME-GI order on Mk10.7 platform for four methane dual-fuel car carriers", "src": "Seatrade Maritime News", "date": "2026-06-16", "kSum": "노르웨이 글로벌 카 캐리어스(Global Car Carriers, GCC)가 중국 건조 예정인 8,600ceu 자동차운반선 4척용 이중연료 메탄엔진을 에버런스(Everllence)에 발주했다. Mk10.76S60ME-GI 엔진은 CSSC 엔진(칭다오)에서 제작되며, ME-GI 플랫폼의 Mk10.7 최초 상업 적용이다. 디젤사이클 연소로 메탄 슬립을 최소화하고 연료유·메탄 운전 모두에서 성능을 확보한다.", "eSum": "Norway's Global Car Carriers has ordered dual-fuel methane engines from Everllence for four 8,600-ceu vehicle carriers to be built in China. The Mk10.76S60ME-GI engines, built at CSSC Engine in Qingdao, mark the first commercial application of the ME-GI engine on the Mk10.7 platform. The Diesel-cycle design offers near-zero methane slip and reliable performance on both fuel oil and methane.", "kImp": "ME-GI 계열은 1,260기 이상 발주된 검증된 이중연료 플랫폼으로, 메탄 슬립 최소화와 운전 유연성이 기술감독의 연료전략·정비계획에 유리하다. 신규 Mk10.7 적용은 향후 신조·개조 엔진 선정 시 참고 지표가 된다.", "eImp": "The ME-GI family is a proven dual-fuel platform (1,260+ orders) whose low methane slip and operational flexibility support fuel strategy and maintenance planning. The new Mk10.7 application is a useful reference for engine selection in future newbuilds and conversions.", "url": "https://www.seatrade-maritime.com/shipyards/everllence-wins-its-first-order-for-new-dual-fuel-methane-engine"}, {"code": "TECH", "title": "Seaspan and Hapag-Lloyd complete first of five methanol dual-fuel engine retrofits", "src": "Offshore Energy", "date": "2026-06-05", "kSum": "시스팬(Seaspan)과 하파그로이드(Hapag-Lloyd)가 메탄올 개조 프로그램의 첫 선박 개조를 완료하고 시스팬 양쯔(Seaspan Yangtze)를 인도했다. 나머지 4척(아마존·갠지스·템스·잠베지)도 순차 개조되며, 척당 연간 CO2e 약 3만~5만 톤 저감이 기대된다. 개조는 시스팬 SAVER 프로그램과 클린블루(CleanBlue) 이니셔티브 하에 수행된다.", "eSum": "Seaspan Corporation and Hapag-Lloyd have completed the first of five vessel conversions under their methanol retrofit program, delivering Seaspan Yangtze. The remaining four sister vessels will follow, each expected to cut CO2e emissions by roughly 30,000-50,000 tonnes per year on low-carbon methanol while extending vessel life. The work is delivered under Seaspan's SAVER program and the CleanBlue initiative.", "kImp": "기존선 메탄올 이중연료 개조는 자산수명 연장과 연료 유연성 확보의 실증 사례로, 기술감독의 개조 타당성·공정관리 벤치마크가 된다. 자매선 순차 개조 방식은 다운타임·비용 관리 측면에서 참고할 만하다.", "eImp": "A methanol dual-fuel retrofit on existing tonnage demonstrates asset-life extension and fuel flexibility, serving as a benchmark for retrofit feasibility and project management. The sister-ship sequential approach is instructive for managing downtime and cost.", "url": "https://www.offshore-energy.biz/first-of-five-methanol-retrofits-completed-under-seaspan-and-hapag-lloyds-collab/"}, {"code": "TECH", "title": "HD Hyundai-led Korean partners to develop robotic Total Hull Care Solution", "src": "MarineLink", "date": "2026-06-17", "kSum": "HD현대중공업(HD Hyundai Heavy Industries)과 5개 계열사가 KCC·TAS글로벌(TAS Global)과 함께 로봇·데이터 기반 통합 선체관리 솔루션 '토탈 헐 케어(Total Hull Care Solution)' 공동개발 MOU를 체결했다. 선체 진단부터 청소·도막손상 점검·효과검증까지 단일 공정으로 수행하며 실시간 선체상태 관리가 핵심이다. 자율 수중로봇 진단, 방오도료 표준, 연비최적화 기술을 함께 개발한다.", "eSum": "HD Hyundai Heavy Industries and five affiliates, with KCC and TAS Global, signed an MoU to develop a robot- and data-based 'Total Hull Care Solution.' It performs hull diagnosis, cleaning, coating-damage inspection and effectiveness verification in a single operation with real-time hull condition management. The partners will develop autonomous underwater robot diagnostics, robotic cleaning and antifouling paint standards, and fuel-efficiency optimisation linked to hull-condition and operational data.", "kImp": "생물부착 관리가 연비·CII에 직접 영향을 주는 만큼, 진단-청소-검증을 통합한 예측형 선체관리는 기술감독의 도료·청소 전략 고도화에 유용하다. 실시간 모니터링·자동 검증 표준화는 향후 유지보수·선체성능 관리 체계에 반영될 수 있다.", "eImp": "With biofouling directly affecting fuel consumption and CII, an integrated predictive hull-management approach (diagnose-clean-verify) helps refine coating and cleaning strategy. Real-time monitoring and standardised verification may shape future maintenance and hull-performance regimes.", "url": "https://www.marinelink.com/news/korean-partners-develop-robotic-total-540428"}, {"code": "TECH", "title": "BW Epic Kosan expands GIT graphene hull coatings after ~6% out-of-dock fuel savings", "src": "MarineLink", "date": "2026-06-04", "kSum": "BW 에픽 코산(BW Epic Kosan, BWEK)이 GIT 코팅스(GIT Coatings)의 바이오사이드-프리 그래핀 기반 선체도료를 LPG선단으로 확대 적용하고 있다(현재 5척 적용, 1척 도킹 중). 한 척은 1년 이상 운항에서 도크 대비 약 6% 출력 개선과 평균 선체거칠기 60-70μm를 기록했다. 온보드 로봇청소와 프로액티브 선체관리 자문을 결합했으며, 신형 XGIT-FORCE 도료도 도입했다.", "eSum": "BW Epic Kosan is scaling up GIT Coatings' biocide-free graphene-based hull coating across its LPG fleet, with five carriers coated (one more in dry dock). One case-study vessel achieved roughly 6% out-of-dock power gain and average hull roughness of 60-70μm over 12+ months, combining hard foul-release coating with onboard robotic cleaning and proactive advisory support. BWEK has also adopted GIT's XGIT-FORCE coating for improved static antifouling and mechanical durability.", "kImp": "폼-릴리스 도료+로봇청소+프로액티브 관리의 조합은 반응형 청소 대비 연비·배출·CII 개선의 실증 데이터를 제공한다. 기술감독은 도료 사양·청소 주기·선체거칠기 목표 설정과 로이드선급(LR) 강화형식승인 등 검증기준을 참고할 수 있다.", "eImp": "The combination of foul-release coating, robotic cleaning and proactive management provides documented gains in fuel, emissions and CII over reactive cleaning. Superintendents can reference coating specs, cleaning intervals, hull-roughness targets and validation such as Lloyd's Register Enhanced Type Approval.", "url": "https://www.marinelink.com/news/bwek-expands-git-coatings-outofdock-fuel-539982"}, {"code": "TECH", "title": "WinGD completes second FAT for ammonia-fuelled two-stroke engine in China", "src": "Offshore Energy", "date": "2026-05-21", "kSum": "윈지디(WinGD)가 암모니아 이중연료 2행정 엔진 X52DF-A-1.0의 공장인수시험(FAT)을 추가로 완료했다. 위차이 마린 파워(YCMP)가 제작하고 중국선급(CCS) 입회 하 4월에 시험이 진행됐으며, 안정적 성능과 낮은 NOx·N2O 배출을 확인했다. 이 엔진은 CSSC 황푸원충(Huangpu Wenchong) 건조 25,000m3 LPG/암모니아 운반선에 탑재된다.", "eSum": "WinGD has completed another factory acceptance test for its X52DF-A-1.0 ammonia-fuelled two-stroke engine, built by Yuchai Marine Power and witnessed by China Classification Society in April. Testing showed stable performance with NOx significantly lower than conventional fuels and minimal N2O emissions. The engine will be installed on the first of four 25,000m3 LPG/ammonia carriers under construction at CSSC Huangpu Wenchong.", "kImp": "암모니아 2행정 엔진의 반복 FAT 통과는 상용화·건조 단계 진입을 뒷받침하며, 기술감독은 암모니아 연료 대응 정비·안전·배출(N2O 포함) 관리 요건을 사전 검토할 수 있다. 엔진빌더-설계사 협업 검증 흐름은 향후 신조 사양 결정의 근거가 된다.", "eImp": "Repeated FAT success supports the path to commercial deployment and construction, letting superintendents prepare maintenance, safety and emissions (including N2O) requirements for ammonia fuel. The engine-designer/builder validation flow informs future newbuild specification decisions.", "url": "https://www.offshore-energy.biz/ammonia-fueled-two-stroke-engine-passes-second-fat/"}]}, {"code": "HR", "type": "news", "kTitle": "Section 9. 해기인력·선원", "eTitle": "Section 9. Marine HR", "items": [{"code": "HR", "title": "Five seafarers killed as Russia and Ukraine trade Black Sea blows", "src": "Splash247", "date": "2026-07-14", "kSum": "우크라이나 오데사(Odesa) 지역 항만에서 광물비료를 양하하던 토고 선적 일반화물선이 러시아 드론 공격을 받아 선원 5명이 사망하고 12명이 부상했다. 4년여 전면전 기간 상선에 대한 단일 공격으로는 최악의 인명피해 중 하나다. IMO 사무총장 아르세니오 도밍게스(Arsenio Dominguez)는 흑해·아조프해 민간 상선 연쇄 공격을 규탄했다.", "eSum": "A Russian drone struck a Togo-flagged general cargoship discharging mineral fertiliser at a port in Ukraine's Odesa region, killing five seafarers and injuring 12 - one of the deadliest single strikes on commercial shipping in the war. IMO Secretary-General Arsenio Dominguez condemned the series of attacks on civilian merchant ships in the Black Sea and Sea of Azov.", "kImp": "선원이 분쟁의 직접 피해자가 되는 위험이 홍해뿐 아니라 흑해에서도 지속됨을 보여준다. 해당 항로 운항·배승 시 선원 안전이 핵심 이슈로 부각된다.", "eImp": "Shows crews continue to be direct casualties of conflict in the Black Sea, not just the Red Sea, making seafarer safety on these routes a central manning concern.", "url": "https://splash247.com/five-seafarers-killed-as-russia-and-ukraine-trade-black-sea-blows/"}, {"code": "HR", "title": "The emotional cost of keeping global trade moving", "src": "Splash247", "date": "2026-06-12", "kSum": "장기 승선에 따른 가족 분리와 관계 파탄이 해운의 구조적 리스크로 부상하고 있다는 분석이다. 한 탱커 부문 연구에서는 기혼 선원의 약 절반이 정신질환 선별검사에서 양성을 보였으며, ISWAN은 관계 문제 관련 상담이 급증했다고 밝혔다. 세이프러스 해피니스 인덱스(Seafarers Happiness Index) 창립자 스티븐 존스(Steven Jones)는 관계 파탄이 가장 논의되지 않는 복지 이슈라고 지적했다.", "eSum": "Family separation and relationship breakdown from long contracts are emerging as a structural shipping risk, with one tanker study finding nearly half of married seafarers screened positive for psychiatric disorders. ISWAN reports a sharp rise in relationship-related calls, and Seafarers Happiness Index founder Steven Jones calls relationship strain shipping's least-discussed welfare issue.", "kImp": "정신건강·리텐션·안전과 직결되는 문제로, 선원 유지율과 운항 안전에 영향을 미친다. 가족 지원 프로그램과 연결성 개선의 전략적 중요성을 부각한다.", "eImp": "Ties directly to mental health, retention and safety, highlighting the strategic value of family-support programmes and better connectivity.", "url": "https://splash247.com/the-emotional-cost-of-keeping-global-trade-moving/"}, {"code": "HR", "title": "FrontM upgrades onship app for seafarers and maritime professionals", "src": "Seatrade Maritime News", "date": "2026-06-29", "kSum": "프론트엠(FrontM)이 IMO '세계 선원의 날'에 맞춰 선원·해운종사자용 통합 앱 '온십(onship)'의 업그레이드 버전을 출시했다. 무료로 전 세계에서 이용 가능하며 업계 뉴스, 커뮤니티, 경력개발, 복지, 이벤트, 서비스 접근을 하나의 '해양 슈퍼앱'으로 통합했다. CEO 키란 벤카테시(Kiran Venkatesh)는 디지털로 분절된 해운을 하나의 공간으로 연결하는 것이 목표라고 밝혔다.", "eSum": "FrontM launched an upgraded version of its onship app for seafarers and maritime professionals, timed to IMO's Day of the Seafarer. Free and available worldwide, the 'maritime superapp' bundles industry news, professional communities, career development, wellbeing and events; CEO Kiran Venkatesh said the aim is to unify a digitally fragmented industry.", "kImp": "연결성·복지·경력개발을 통합한 디지털 플랫폼은 선원 리텐션과 웰빙 지원 수단으로 주목된다. 선원 대상 디지털 복지 서비스 경쟁이 심화되고 있음을 보여준다.", "eImp": "An integrated connectivity-welfare-career platform positioned as a retention and wellbeing tool, reflecting intensifying competition in digital seafarer services.", "url": "https://www.seatrade-maritime.com/crewing/frontm-upgrades-onship-app-for-seafarers-and-maritime-professionals"}, {"code": "HR", "title": "Beyond the screen: The psychosocial cost of always being online at sea", "src": "SAFETY4SEA", "date": "2026-06-25", "kSum": "선내 상시 연결성이 고립 완화라는 이점과 함께 번아웃·수면장애·디지털 피로 등 새로운 심리사회적 위험을 낳고 있다는 분석이다. 안트베르펜(Antwerp)·마닐라(Manila) 대학 연구에 따르면 비번 중 소셜미디어 사용시간이 가장 긴 선원은 불안 위험이 2.68배 높았고, 하루 4시간 이상 사용 시 우울 위험도 유의하게 상승했다. 2025 SEAFiT 설문에서도 통신은 선원 최우선 관심사로 나타났다.", "eSum": "Constant onboard connectivity eases isolation but creates new psychosocial risks such as burnout, sleep disruption and digital fatigue. A University of Antwerp/Manila study found seafarers with the longest off-duty social media use were 2.68 times more likely to suffer anxiety, with depression rising for those online over four hours a day; the 2025 SEAFiT survey ranked communication seafarers' top priority.", "kImp": "연결성 확대가 복지에 양면적 영향을 미침을 보여주며, 사용 지침과 정신건강 지원의 병행 필요성을 제기한다. 선내 디지털 정책 수립에 참고가 된다.", "eImp": "Shows connectivity's double-edged welfare impact and the need for usage guidance and mental-health support, informing onboard digital policy.", "url": "https://safety4sea.com/cm-beyond-the-screen-the-psychosocial-cost-of-always-being-online-at-sea/"}, {"code": "HR", "title": "2026 Crew Welfare Week: Seafarer wellbeing at the core of safer and more resilient shipping", "src": "SAFETY4SEA", "date": "2026-06-23", "kSum": "세이프티포씨(SAFETY4SEA)가 개최한 '2026 크루 웰페어 위크(Crew Welfare Week)'에서 전문가들이 선원 정신건강, 상시 연결성의 부작용, 영양, 여성 선원, STCW 개정 필요성 등 복지 전반을 논의했다. 복지가 컴플라이언스 이슈를 넘어 운영 핵심 지표(KPI)로 다뤄져야 한다는 공감대가 형성됐다. 행사 말미에는 2026 크루 웰페어 어워즈 후보 시상식이 진행됐다.", "eSum": "At SAFETY4SEA's 2026 Crew Welfare Week, experts discussed seafarer mental health, the downsides of constant connectivity, nutrition, women at sea and the need to update STCW. Panellists agreed crew wellbeing should be treated as a core operational KPI rather than a compliance topic, closing with the 2026 Crew Welfare Awards nominations.", "kImp": "선원 복지를 전략적·통합적 과제로 재정의하는 업계 흐름을 보여준다. 선박관리사의 복지 지표화와 예방 중심 접근 전환을 시사한다.", "eImp": "Reflects an industry shift to treating crew welfare as a strategic, holistic priority, pointing managers toward measurable, prevention-focused approaches.", "url": "https://safety4sea.com/2026-crew-welfare-week/"}, {"code": "HR", "title": "Gard Crew Claims Report 2026: Routine tasks account for most seafarer injuries", "src": "SAFETY4SEA", "date": "2026-06-25", "kSum": "가드(Gard)의 '2026 선원 클레임 보고서'는 대다수 사고가 일상적 선내 작업 중 발생하며 숙련 선원도 예외가 아님을 지적했다. 2025년 6,500건 이상의 P&I 클레임 중 절반가량이 인적 관련이고 그중 90% 이상이 선원과 연관됐다. 승선 첫 3개월(특히 첫 달)과 오전 08~10시가 부상 고위험 구간으로 나타났으며, 심혈관 질환이 가장 심각·고비용 클레임으로 분석됐다.", "eSum": "Gard's 2026 Crew Claims Report finds most accidents occur during routine onboard tasks and frequently involve experienced crew. Of more than 6,500 P&I claims in 2025, nearly half were people-related and over 90% involved crew; the first three months aboard (especially the first month) and 08:00-10:00 were highest-risk, with cardiovascular disease the most severe and costly claims.", "kImp": "숙련도나 비정상 상황이 아닌 '일상 작업'이 최대 부상 원인임을 데이터로 제시해 안전관리 초점 전환을 요구한다. 신규 승선 초기와 오전 시간대 관리 강화가 실무적 시사점이다.", "eImp": "Data showing routine work - not inexperience or abnormal events - drives most injuries, calling for a shift in safety focus toward early-tenure and morning-hour risk management.", "url": "https://safety4sea.com/gard-crew-claims-report-2026-routine-tasks-account-for-most-seafarer-injuries/"}, {"code": "HR", "title": "Nordseth appointed chair of Seatrade Maritime Crew Connect Global 2026", "src": "Seatrade Maritime News", "date": "2026-07-13", "kSum": "시트레이드 마리타임(Seatrade Maritime)이 대표적 크루잉 콘퍼런스 '크루 커넥트 글로벌(Crew Connect Global) 2026'의 의장으로 노르세스(Nordseth)를 선임했다. 크루 커넥트 글로벌은 선원 채용·교육·복지 등 인적자원 현안을 다루는 국제 크루잉 콘퍼런스다.", "eSum": "Seatrade Maritime appointed Nordseth as chair of Crew Connect Global 2026, a leading crewing conference. The event convenes industry stakeholders on seafarer recruitment, training and welfare issues.", "kImp": "주요 크루잉 콘퍼런스의 리더십 변화로, 선원 채용·복지 의제 설정에 영향을 줄 수 있다.", "eImp": "A leadership change at a major crewing conference that can help shape the agenda on seafarer recruitment and welfare.", "url": "https://www.seatrade-maritime.com/event-news/nordseth-appointed-chair-of-seatrade-maritime-crew-connect-global-2026"}]}, {"code": "HSEQ", "type": "news", "kTitle": "Section 10. HSEQ·손해방지", "eTitle": "Section 10. HSEQ", "items": [{"code": "HSEQ", "title": "브리타니아(Britannia) P&I: 구명정 훈련·정비 중 위험 저감을 위한 손실예방 안내", "src": "Britannia P&I", "date": "2026-07-14", "kSum": "브리타니아(Britannia) P&I 클럽이 구명정(lifeboat) 정비 및 퇴선(abandon ship) 훈련 중 발생하는 부상을 줄이기 위한 손실예방 지침을 발표했다. 익숙지 않은 장비 조작, 온로드 이탈장치(on-load release)의 의도치 않은 작동, 부적절한 정비가 주요 사고 원인으로 지목됐다. 클럽은 신규 승선자 친숙화 교육, 작업허가서(PTW) 적용, 최신 제조사 정비매뉴얼 확인, 훈련 시 무인 하강 우선 원칙을 권고한다.", "eSum": "Britannia P&I Club issued loss-prevention guidance to reduce injuries during lifeboat maintenance and abandon-ship drills. It identifies lack of familiarity with equipment, unplanned operation of on-load release mechanisms, and inadequate maintenance as the main causes of incidents. The club recommends familiarisation training for new joiners, use of Permits to Work, verifying the latest manufacturer maintenance manuals, and lowering the boat empty first during drills.", "kImp": "구명정 사고는 반복적으로 중상·사망으로 이어지므로, HSEQ 담당자는 이탈장치 안전상태 육안확인 습관화, 최신 매뉴얼 비치, 훈련 위험성평가 갱신을 SMS 절차에 명문화해야 한다.", "eImp": "Lifeboat incidents repeatedly cause serious injury or death, so HSEQ managers should embed habitual visual checks of release-gear status, availability of up-to-date manuals, and updated drill risk assessments into SMS procedures.", "url": "https://britanniapandi.com/2026/07/lifeboat-safety-reducing-risk-during-drills-and-maintenance/"}, {"code": "HSEQ", "title": "호주해사안전청(AMSA) 2026-27 준수계획: 피로·ISM·선박안전 중점", "src": "SAFETY4SEA", "date": "2026-07-09", "kSum": "호주해사안전청(AMSA)이 2026-27 국가준수계획에서 선원 피로(fatigue), 국제안전관리규약(ISM) 이행, 선박 안전을 중점 감독 영역으로 제시했다. 외국적선 대상 최소 2,400건의 항만국통제(PSC) 점검과 국내상업선 2,300건 점검이 계획됐으며 해사노동협약(MLC)상 선원 복지도 포함된다. 안전관리시스템의 실질적 이행 부실이 반복 결함의 근본원인으로 지목된다.", "eSum": "AMSA's National Compliance Plan 2026-27 highlights seafarer fatigue, ISM Code implementation, and vessel safety as focus areas. It plans a minimum of 2,400 PSC inspections on foreign-flagged vessels and 2,300 on domestic commercial vessels, and covers seafarer welfare under the MLC. Weak practical implementation of safety management systems is identified as a root cause of recurring deficiencies.", "kImp": "피로관리와 ISM 이행이 감독 초점이 된 만큼, HSEQ 담당자는 근로·휴식시간 기록의 정합성, 절차 준수 증빙, 내부심사 실효성을 사전에 점검해 억류 리스크를 낮춰야 한다.", "eImp": "With fatigue management and ISM implementation in focus, HSEQ managers should pre-check the integrity of work/rest-hour records, evidence of procedural compliance, and internal-audit effectiveness to lower detention risk.", "url": "https://safety4sea.com/amsa-targets-fatigue-ism-and-vessel-safety-in-2026-27-compliance-plan/"}, {"code": "HSEQ", "title": "MTF, 성장하는 메탄올 추진 선대용 안전관리(SMS) 지침 발표", "src": "IIMS", "date": "2026-07-13", "kSum": "해사기술포럼(MTF, Maritime Technologies Forum)이 메탄올(methanol) 연료 선박을 위한 안전관리시스템(SMS) 구축·강화 지침을 발표했다. 메탄올은 상온 액체·기존 인프라 호환 등 장점이 있으나 독성, 낮은 인화점, 거의 보이지 않는 증기·화염이라는 고유 위험을 지닌다. 지침은 ISM 코드와 메탄올 기술 전문가들이 공동 개발했으며, 2025년 메탄올 이중연료선 66척 발주 등 채택 확대를 배경으로 한다.", "eSum": "The Maritime Technologies Forum (MTF) released guidance to help companies build and strengthen Safety Management Systems (SMS) for methanol-fuelled ships. Methanol offers advantages such as remaining liquid at ambient temperature and infrastructure compatibility, but poses distinct risks including toxicity, low flashpoint, and nearly invisible vapours and flames. Developed jointly by MTF members and experts in methanol technologies and the ISM Code, it responds to rising uptake, with 66 methanol dual-fuel ships ordered in 2025.", "kImp": "탈탄소로 메탄올 선박이 급증하는 만큼, HSEQ 담당자는 메탄올 특유의 독성·저인화점·불가시 화염 위험을 SMS 위험성평가와 소방·응급대응 절차에 선제적으로 반영해야 한다.", "eImp": "As decarbonisation drives rapid growth in methanol vessels, HSEQ managers should proactively reflect methanol's toxicity, low flashpoint, and invisible-flame risks in SMS risk assessments and firefighting/emergency-response procedures.", "url": "https://www.iims.org.uk/mtf-releases-new-safety-guidance-for-the-growing-methanol-fuelled-fleet/"}, {"code": "HSEQ", "title": "스쿨드(Skuld) 안전경보: 보조기관 에로전 플러그 파손에 의한 기관실 화재", "src": "Skuld", "date": "2026-07-03", "kSum": "스쿨드(Skuld) P&I 클럽이 고압연료펌프의 에로전(용융) 플러그 파손으로 인한 기관실 화재 사례를 안전경보로 발표했다. 과열·마찰·펌프 고착·정비 불량 등으로 플러그가 파손되면 가압된 연료유가 미세 분무 형태로 분출돼 배기 매니폴드·과급기 등 고온면에 닿아 즉시 발화한다. 학습사항으로 제조사 사양(토크·잠금와이어) 준수, 정비 후 검사·확인, 배기계통 단열, 고정식 소화설비·화재탐지 정기시험이 강조됐다.", "eSum": "Skuld P&I Club issued a safety alert on engine room fires caused by failure of erosion (fusible) plugs in high-pressure fuel pumps. When a plug fails due to overheating, friction, pump seizure, or poor maintenance, pressurised fuel oil escapes as a fine atomised spray that ignites instantly on hot surfaces such as exhaust manifolds or turbochargers, producing a rapid flash fire. Lessons emphasise strict adherence to manufacturer specifications (torque, locking wire), post-maintenance inspection and sign-off, proper exhaust insulation, and regular testing of fixed firefighting and fire-detection systems.", "kImp": "연료 분무 화재는 초기 확산이 매우 빨라 치명적이므로, HSEQ 담당자는 연료계통 정비 후 확인점검, 배기계통 단열 상태, 연료분무 시나리오 소방훈련을 안전관리 절차에 명확히 반영해야 한다.", "eImp": "Fuel-spray fires spread extremely fast and can be catastrophic, so HSEQ managers should embed post-maintenance verification of fuel systems, exhaust insulation checks, and fuel-spray-scenario fire drills into safety management procedures.", "url": "https://www.skuld.com/topics/ship/safety/fire-in-the-engine-room-due-to-auxiliary-engine-erosion-plug-failure/"}, {"code": "HSEQ", "title": "Rise in Fishery Claims in South Korea Waters", "src": "Gard", "date": "2026-07-06", "kSum": "가드(Gard)는 한국 해역에서 어망 관련 항행 사고가 급증했다고 분석했다. 2025년 항행 사고는 2024년 대비 125% 증가했으며 대부분 안강망(stow net) 등 어구와의 접촉이었다. 사고는 보령·목포·서산(대산)·태안·평택 해역에 집중됐고, 벌크선(약 40%)·탱커(28%)가 다수를 차지했다. 초행 입항(unique port call)과 야간 항해가 핵심 위험요인으로 지목됐다.", "eSum": "Gard reports a sharp rise in fishing-net-related navigation incidents in South Korean waters, with 2025 incidents up 125% on 2024, mostly contact with stow nets and other gear. Cases concentrate off Boryeong, Mokpo, Seosan (Daesan), Taean and Pyeongtaek, with bulk carriers (~40%) and tankers (28%) predominating. 'Unique port calls' and hours of darkness are key risk factors.", "kImp": "수몰·미표시 어구는 레이더·육안 탐지가 어려워 프로펠러·앵커 얽힘과 수억 원대 고액 클레임으로 이어진다. 초행 입항·야간 항해 시 통항계획 강화, 견시·레이더 최적화, 주간 도선사 승선 우선 등 실무 권고가 한국 취항 선박에 직접적으로 유용하다.", "eImp": "Submerged, poorly marked gear evades radar and visual detection, leading to propeller/anchor entanglement and large claims (hundreds of millions of KRW). Practical recommendations—stronger passage planning for unique/night calls, optimised lookout/radar and prioritising daylight pilotage—are directly useful for vessels calling Korea.", "url": "https://gard.no/en/insights/fishery-claims-rise-south-korea-waters/"}, {"code": "HSEQ", "title": "AIS-Assisted Collisions: The Risks of Over-Reliance", "src": "Gard", "date": "2026-07-14", "kSum": "가드(Gard)는 선박자동식별장치(AIS) 과의존이 충돌 사고의 반복 요인이라고 경고했다. 실제 사례들에서 선교팀이 시각 견시와 체계적 레이더 플로팅을 소홀히 하고 AIS 데이터에만 의존해 최근접거리(CPA)·최근접시간(TCPA)을 판단하다 충돌이 발생했다. 일부 어선은 AIS를 켜지 않았고, 센서 오류로 AIS가 실제 침로·속력과 크게 달랐던 사례도 있었다.", "eSum": "Gard warns that over-reliance on AIS is a recurring factor in collisions. In several casualties, bridge teams neglected visual lookout and systematic radar plotting, relying on AIS-derived CPA/TCPA; some fishing vessels ran without AIS, and in one case AIS-transmitted course/speed diverged sharply from actual values due to faulty sensors. AIS should supplement, not replace, fundamental navigation practice.", "kImp": "AIS는 보조 수단일 뿐 시각 견시·레이더 관측을 대체할 수 없음을 재확인하며, 안전관리시스템(SMS)과 선장 상비명령에 '가용한 모든 수단에 의한 견시' 원칙을 명시할 것을 권고한다. GPS 교란 지역에서 AIS 신뢰도 저하까지 고려한 항행 위험관리가 필요하다.", "eImp": "Reaffirms AIS as a supplement, not a substitute for visual lookout and radar observation, urging SMS and master's standing orders to codify 'lookout by all available means.' Navigation risk management must also account for degraded AIS reliability in GPS-interference zones.", "url": "https://gard.no/en/insights/ais-assisted-collisions-overreliance-risk/"}]}, {"code": "KR", "type": "news", "kTitle": "Section 11. 한국 해운시장", "eTitle": "Section 11. Korean Shipping Market", "items": [{"code": "KR", "title": "항만물류協, 해수부장관 간담회서 하역시장 안정화 등 4대 현안 건의", "src": "쉬핑뉴스넷", "date": "2026-07-14", "kSum": "한국항만물류협회는 7월 9일 황종우 해양수산부 장관과 간담회를 열고 항만물류산업 지속성장을 위한 4대 현안을 건의했다. 컨테이너 하역시장 안정화, 하역요금 인가제 실효성 확보, 항만보안료 현실화, 항만 자동화·스마트화 지원이 핵심이다. 업계는 국내 하역료가 상하이의 3분의 1, LA의 10분의 1 수준으로 과당경쟁에 노출돼 있다고 지적했다.", "eSum": "The Korea Port Logistics Association met Oceans and Fisheries Minister Hwang Jong-woo on July 9 to raise four priorities: stabilizing the container stevedoring market, enforcing the approved-tariff system, updating port security fees, and supporting port automation. The industry warned domestic handling rates are about one-third of Shanghai's and one-tenth of LA's amid excessive competition.", "kImp": "부산·인천 등 국내 항만하역 채산성 악화와 자동화 전환은 항만 경쟁력과 항운노조 인력 문제와 직결되는 정책 이슈다.", "eImp": "Weak stevedoring margins and the automation push at Busan/Incheon are policy issues tied to port competitiveness and dock-labor restructuring.", "url": "https://www.shippingnewsnet.com/news/articleView.html?idxno=71179"}, {"code": "KR", "title": "한화오션, '한화해운 발주' 세 번째 LNG운반선 건조 착수…美 공략 '윈윈'", "src": "더구루", "date": "2026-07-12", "kSum": "한화오션이 미국 자회사 한화해운으로부터 수주한 LNG운반선 4척 중 세 번째 선박 'H2608'의 강재절단식을 거제조선소에서 열고 건조에 착수했다. 지난해 말 첫 선박에 이어 6개월 만에 세 번째 건조를 시작하며 적기 인도에 주력한다. 한화는 미국 조선·해운 생태계 구축과 마스가(MASGA) 프로젝트를 통해 미국 시장 확대를 노린다.", "eSum": "Hanwha Ocean began building 'H2608', the third of four LNG carriers ordered by its U.S. affiliate Hanwha Shipping, holding a steel-cutting ceremony at its Geoje yard—the third start in six months. Hanwha is leveraging a combined U.S. shipbuilding-and-shipping ecosystem and the MASGA initiative to expand in the American market.", "kImp": "한·미 조선협력(MASGA)과 미국 LNG 물류 확대는 한국 조선사의 고부가 수주 파이프라인을 강화한다.", "eImp": "Korea-U.S. shipbuilding cooperation (MASGA) and growing U.S. LNG logistics reinforce Korean yards' high-value order pipeline.", "url": "https://www.theguru.co.kr/news/article.html?no=104278"}, {"code": "KR", "title": "'HD현대·삼성중공업 LOI' 모잠비크 LNG선 17척 발주 또 연기", "src": "더구루", "date": "2026-07-01", "kSum": "토탈에너지스가 모잠비크 LNG 프로젝트용 LNG운반선 17척 발주를 1분기에서 3분기로 다시 연기하며 슬롯 확정일을 9월로 연장 요청했다. HD현대삼호 9척·삼성중공업 8척의 LOI를 확보한 상태로 2020년 이후 6년째 수주를 대기 중이다. 척당 가격은 LOI 당시 1억8000만 달러에서 현재 2억6000만 달러 이상으로 올랐다.", "eSum": "TotalEnergies again pushed its planned order of 17 LNG carriers for the Mozambique LNG project from Q1 to Q3, asking to extend slot confirmation to September. HD Hyundai Samho (9) and Samsung Heavy (8) hold LOIs and have waited six years since 2020; per-ship prices have risen from USD180m at LOI to over USD260m now.", "kImp": "대형 LNG선 발주 지연은 한국 빅3의 하반기 수주 실적과 도크 슬롯 운용에 변수로 작용한다.", "eImp": "The delay in large LNG-carrier orders is a swing factor for the Korean big-three's H2 order intake and dock-slot planning.", "url": "https://www.theguru.co.kr/news/article.html?no=103793"}, {"code": "KR", "title": "'에너지운반선 효과' 한국조선 수주점유율 39개월 만에 최고치", "src": "코리아쉬핑가제트", "date": "2026-06-22", "kSum": "우리나라의 글로벌 선박 수주 점유율이 39개월 만에 최고치를 기록했다. 지난달 에너지 운반선과 원유 운반선 등을 잇따라 수주하면서 전년 대비 점유율이 급등했다. 글로벌 발주량 증가도 한국 조선의 수주 회복을 뒷받침했다.", "eSum": "South Korea's share of global ship orders hit its highest in 39 months, driven by a run of energy-carrier and crude-tanker wins last month that sharply lifted its share versus a year earlier, with rising global ordering also supporting the recovery.", "kImp": "고부가 에너지운반선 중심의 수주 점유율 회복은 중국과의 경쟁에서 한국 조선의 질적 우위를 보여준다.", "eImp": "A share recovery led by high-value energy carriers underscores Korea's qualitative edge over China in shipbuilding.", "url": "https://www.ksg.co.kr/news/main_newsView.jsp?pNum=147457"}, {"code": "KR", "title": "여수광양항, 벌크선 LNG 벙커링·원료 하역 동시 수행", "src": "코리아쉬핑가제트", "date": "2026-06-23", "kSum": "여수광양항만공사(YGPA)는 6월 21~22일 광양항 원료부두에서 9만t급 벌크선에 친환경 선박연료인 LNG 약 1050t을 공급하는 벙커링 작업을 완료했다고 밝혔다. 원료 하역과 LNG 벙커링을 동시에 수행한 것으로, 여수광양항이 올해 처음 원료부두에서 벙커링을 시행한 사례다.", "eSum": "Yeosu Gwangyang Port Authority (YGPA) completed an LNG bunkering of about 1,050 tonnes to a 90,000-dwt bulker at Gwangyang's raw-materials wharf on June 21-22, performing cargo discharge and LNG bunkering simultaneously—its first bunkering at the raw-materials berth this year.", "kImp": "하역과 벙커링 동시 수행은 광양항의 친환경 연료 공급 항만 경쟁력을 높인다.", "eImp": "Simultaneous cargo handling and bunkering strengthens Gwangyang's competitiveness as a green-fuel supply port.", "url": "https://www.ksg.co.kr/news/main_newsView.jsp?pNum=147478"}, {"code": "KR", "title": "'공급망 위기시대의 역설' 해운·선원 안보적 가치 재조명", "src": "코리아쉬핑가제트", "date": "2026-06-24", "kSum": "중동전쟁 장기화로 국제 공급망 단절 우려가 커지면서 전시·비상시 전략물자를 조달하는 경제안보선대 구축과 이에 승선할 전략해기사 양성 필요성이 부각되고 있다. 해운과 선원의 안보적 가치가 재조명되며 관련 제도 마련을 촉구하는 목소리가 높아지고 있다.", "eSum": "With prolonged Middle East conflict heightening fears of supply-chain disruption, calls are growing to build an 'economic-security fleet' to secure strategic goods in wartime/emergencies and to train the strategic seafarers to crew them, re-highlighting the security value of shipping and mariners.", "kImp": "경제안보선대·전략해기사 양성 논의는 한국 선원 정책과 국적선대 유지 정책에 새로운 명분을 제공한다.", "eImp": "Debate over an economic-security fleet and strategic-seafarer training adds new rationale for Korea's seafarer and national-fleet policies.", "url": "https://www.ksg.co.kr/news/main_newsView.jsp?pNum=147482"}]}, {"code": "INS", "type": "news", "kTitle": "Section 12. 해상보험 (H&M)", "eTitle": "Section 12. Marine Insurance (H&M)", "items": [{"code": "INS", "title": "호르무즈 긴장 재고조로 선박 전쟁위험 보험료 선체가치의 3~10%로 급등", "src": "The National", "date": "2026-07-17", "kSum": "미국-이란 간 공격이 재격화되면서 호르무즈 해협(Strait of Hormuz) 통항 선박의 전쟁위험 보험료가 선체가치의 3~10%까지 다시 치솟았다. 전쟁 이전 0.25%(약 25만 달러) 수준이던 1억 달러 유조선 보험료가 이제 300만~1,000만 달러에 달한다. 마시(Marsh)의 마커스 베이커(Marcus Baker)는 요율이 유가 흐름을 따라 롤러코스터처럼 움직였다고 밝혔다.", "eSum": "War-risk premiums for ships transiting the Strait of Hormuz have surged again to 3-10% of hull value as US-Iran attacks intensify, up from 0.25% pre-war. A $100m tanker now faces $3m-$10m in premium versus about $250,000 before. Marsh's Marcus Baker said rates have see-sawed with the oil price, and about 6,000 seafarers are trapped in the region.", "kImp": "전쟁위험 요율 변동성이 H&M·전쟁보험 인수와 유조선 운항 채산성에 직접적 영향을 미치며, IMO와 보험업계(IUMI) 간 요율 적정성 논쟁도 부각된다.", "eImp": "Volatile war-risk pricing directly affects H&M and war-risk underwriting and tanker voyage economics, while an IMO-IUMI dispute over pricing fairness has emerged.", "url": "https://www.thenationalnews.com/business/2026/07/17/war-risk-shipping-premium-surges-again-as-tensions-escalate-at-strait-of-hormuz/"}, {"code": "INS", "title": "런던 해상보험 시장, 7년 만에 연성(soft) 국면 진입… 선체보험 요율 최대 10% 하락", "src": "Cyprus Shipping News", "date": "2026-07-02", "kSum": "BMS의 런던 해상보험 시장 전망 보고서에 따르면 약 7년간의 정상화 끝에 시장이 연성(soft) 국면에 들어서며 원양 선체(H&M) 요율이 최대 10% 하락하고 신규 인수능력이 확대되고 있다. 로이즈(Lloyd's)는 2025년 종합손해율 87.6%로 3년 연속 흑자를 기록했으나 해상·항공·운송(MAT) 부문은 약 104%로 시장 평균을 밑돌았다. 신규 MGA와 미국계 보험사들이 공격적으로 인수능력을 투입하고 있다.", "eSum": "A BMS London-market outlook says marine insurance has entered a soft phase after roughly seven years of remediation, with blue-water hull (H&M) rates down up to 10% and capacity expanding. Lloyd's posted an 87.6% combined ratio in 2025 (third straight profitable year), though the marine, aviation and transport (MAT) line ran near 104%. New MGAs and US carriers are deploying capacity aggressively, opening a buyer's window.", "kImp": "선주에게 유리한 인수 환경이 형성돼 H&M·항만·적하 갱신 협상력이 커졌으나, 재보험 조정이나 대형 손해 발생 시 국면이 반전될 수 있다.", "eImp": "A buyer-friendly market boosts leverage on H&M, ports and cargo renewals, but a reinsurance correction or major loss could reverse it.", "url": "https://cyprusshippingnews.com/2026/07/02/marine-insurance-london-market-outlook/"}, {"code": "INS", "title": "호르무즈 위기, 해상 전쟁보험의 최대 기회로… 전쟁요율 0.125%에서 최대 10%로 폭등", "src": "Insurance Business", "date": "2026-06-26", "kSum": "2026년 이란 분쟁으로 호르무즈 노출 선박의 전쟁위험 요율이 선체가치의 0.125%에서 최대 10%까지 약 80배 급등했다가, 6월 17일 휴전 후 약 5%에서 2%로 반락했다. 미국 국제개발금융공사(DFC)의 400억 달러 규모 해상 재보험 시설(처브(Chubb) 주간사)은 실제 인수 실적이 전무했고, 비즐리(Beazley)는 4월에 10억 달러(선체 5억+적하 5억) 컨소시엄을, 로이즈·처브는 2억+2억 달러 컨소시엄을 출범했다. 하우든 리(Howden Re)는 유조선 피격 손실을 최대 17.5억 달러로 추산했다.", "eSum": "Insurance Business reports the 2026 Iran conflict drove Hormuz war-risk premiums from 0.125% to as high as 10% of hull value (about 80x), before halving from ~5% to ~2% after the June 17 ceasefire. The US DFC's $40bn maritime reinsurance facility (Chubb-led) wrote zero policies; Beazley launched a $1bn consortium in April and Lloyd's/Chubb a $200m+$200m consortium from June 19. Howden Re estimated tanker-strike losses at up to $1.75bn.", "kImp": "지정학 리스크가 전쟁보험 인수능력 확대와 컨소시엄 신설을 촉발하며, 정부 지원 시설과 민간 시장 간 역할 분담이 시장 구조 변화를 주도한다.", "eImp": "Geopolitical risk is spawning new war-risk capacity and consortia, with government-backed facilities and private markets reshaping the sector.", "url": "https://www.insurancebusinessmag.com/us/news/marine/strait-of-hormuz-crisis-why-the-biggest-opportunity-in-marine-war-insurance-lies-ahead-580434.aspx"}, {"code": "INS", "title": "보험업계 '호르무즈 전쟁보험 여전히 가능'… 통항 관련 난제는 상존", "src": "S&P Global Commodity Insights", "date": "2026-06-23", "kSum": "S&P 글로벌(S&P Global)에 따르면 6월 중순 미-이란 양해각서 이후에도 로이즈(Lloyd's)와 런던 시장에서 호르무즈 해협 통항 선박에 대한 전쟁위험 담보가 계속 제공되고 있다. 다만 요율 변동성과 통항 실무상의 난제는 여전히 남아 있다고 보험업계는 밝혔다. 담보는 법적으로 허용되는 범위에서 계속 공급되고 있다.", "eSum": "Per S&P Global, war-risk cover for vessels transiting the Strait of Hormuz remained available in the Lloyd's and London company market following the mid-June US-Iran MoU, though insurers said pricing volatility and practical transit challenges persist. Cover is being offered where legally permissible.", "kImp": "담보 가용성 자체는 유지돼 무역 지속을 뒷받침하지만, 인수 조건과 통항 리스크 평가의 불확실성이 커졌다.", "eImp": "Cover availability underpins continued trade, but underwriting terms and transit-risk assessment remain uncertain.", "url": "https://www.spglobal.com/energy/en/news-research/latest-news/shipping/062326-war-cover-available-for-hormuz-trades-but-transit-challenges-remain-insurers"}, {"code": "INS", "title": "로이즈, 처브 주간 호르무즈 전쟁위험 컨소시엄 출범… 선체·적하 각 2억 달러", "src": "Reinsurance News", "date": "2026-06-19", "kSum": "로이즈(Lloyd's)가 처브(Chubb)를 주간사로 하는 신규 해상 전쟁위험 컨소시엄을 출범해 호르무즈 해협 통항 선박·화물에 대한 추가 인수능력을 제공한다. 선체·P&I 위험에 최대 2억 달러, 적하 위험에 별도 2억 달러 능력을 6월 19일부터 제공하며 제재 스크리닝 등 인수 기준을 충족해야 한다. 처브는 앞서 미국 DFC가 지원하는 걸프 해상보험 시설의 운영도 맡은 바 있다.", "eSum": "Lloyd's launched a new Chubb-led marine war-risk consortium providing extra capacity for vessels and cargo transiting the Strait of Hormuz, with up to $200m for hull and P&I plus a further $200m of dedicated cargo capacity, available from June 19 subject to sanctions screening. Chubb also manages the US DFC-backed Gulf maritime insurance facility.", "kImp": "대형 보험사 주도의 신규 인수능력이 위험지역 통항을 지원하나, 제재 준수 요건이 공급 조건을 좌우한다.", "eImp": "New lead-carrier capacity supports high-risk transits, though sanctions-compliance requirements gate supply.", "url": "https://www.reinsurancene.ws/lloyds-unveils-chubb-led-war-risk-insurance-facility-for-vessels-in-strait-of-hormuz/"}, {"code": "INS", "title": "호르무즈 통항 회복… 유조선 운항 재개로 전쟁위험 노출 완화 조짐", "src": "Insurance Journal", "date": "2026-06-23", "kSum": "인슈어런스 저널(Insurance Journal, 블룸버그 기사)에 따르면 6월 중순 미-이란 양해각서 이후 호르무즈 해협 통항이 회복되기 시작해 화요일 기준 만재 비이란 초대형 유조선 2척을 포함한 7척이 통항했거나 통항 중이었다. 평시 하루 약 135척이 통항하던 수준에는 아직 못 미친다. HMM이 운용하는 VLCC 유니버설 글로리(Universal Glory)는 사우디 원유 200만 배럴을 싣고 한국으로 향했다.", "eSum": "Per Insurance Journal (Bloomberg), Strait of Hormuz traffic began recovering after the mid-June US-Iran MoU, with seven tankers, including two laden non-Iranian VLCCs, in or having crossed the strait on Tuesday, still short of the roughly 135 vessels a day seen in peacetime. The HMM-operated VLCC Universal Glory carried 2m barrels of Saudi crude toward South Korea.", "kImp": "통항 정상화는 전쟁위험 보험 노출과 청구 위험을 낮춰 요율 안정에 기여할 수 있는 시장 신호다.", "eImp": "Normalising transits is a market signal that could ease war-risk exposure and claims, supporting rate stabilisation.", "url": "https://www.insurancejournal.com/news/international/2026/06/23/874880.htm"}, {"code": "INS", "title": "IUMI 2026년 봄 통계 성명… 지정학 리스크 속 화물·선체·해양에너지 시장 점검", "src": "IUMI", "date": "2026-03-26", "kSum": "국제해상보험연맹(IUMI)이 함부르크 봄 회의에서 화물·원양 선체·해양에너지 기술위원회의 시장 업데이트를 담은 봄 통계 성명(Spring Stats Statement)을 발표했다. 특히 중동 지역을 중심으로 한 현재의 지정학적 사건에 초점을 맞췄다. IUMI의 최신 연례 데이터 기준 전 세계 해상보험료는 399.2억 달러, 원양 선체보험료는 96.7억 달러(전년 대비 3.5% 증가)로 집계됐다.", "eSum": "IUMI's Spring Stats Statement, released at its March Hamburg meeting, gave a market update from the Cargo, Ocean Hull and Offshore Energy Technical Committees, focusing on current geopolitical events in the Middle East. IUMI's latest annual data put global marine premiums at $39.92bn and ocean-hull premiums at $9.67bn, up 3.5% year on year.", "kImp": "선체보험료 증가세와 지정학 리스크 부각은 인수 규율 강화와 요율 방향성에 대한 업계 벤치마크를 제공한다.", "eImp": "Rising hull premiums and geopolitical risk set industry benchmarks for underwriting discipline and rate direction.", "url": "https://iumi.com/statistics/spring-stats-statement-2026/"}, {"code": "INS", "title": "처브·세토, 실시간 선박 데이터 기반 로이즈 해상 MGA 출범", "src": "Insurance Journal", "date": "2026-03-25", "kSum": "런던 특화 재·보험사 처브(Chaucer)와 해양기술기업 세토 AI(Ceto AI)가 로이즈(Lloyd's) 커버홀더로 운영되는 신규 해상 MGA를 출범했다. 세토는 처브 신디케이트와 도쿄마린킬른(Tokio Marine Kiln)의 인수능력으로 선체(hull) 위험을 인수하며, 고빈도 선박 기계·성능 데이터를 활용해 인수 판단을 내린다. 세계 선대 평균 선령이 22년을 넘어서면서 선령 등 정적 지표만으로는 위험 판별력이 떨어진다는 문제의식을 반영했다.", "eSum": "Chaucer and maritime-tech firm Ceto AI launched a new marine MGA operating as a Lloyd's coverholder, with Ceto binding hull risks on behalf of Chaucer's syndicate and Tokio Marine Kiln, using high-frequency vessel machinery and performance data to drive underwriting. With the global fleet averaging over 22 years, static indicators like vessel age are increasingly blunt measures of risk.", "kImp": "실시간 운항 데이터 기반 인수는 노후 선대·수리비 상승·지정학 리스크가 겹친 선체보험 시장에서 위험 선별력을 높이는 구조적 변화다.", "eImp": "Data-led underwriting marks a structural shift for a hull market pressured by ageing fleets, rising repair costs and geopolitical risk.", "url": "https://www.insurancejournal.com/news/international/2026/03/25/863407.htm"}, {"code": "INS", "title": "로이즈 시장협회 '호르무즈 통항 감소는 보험 부재 아닌 안전 우려 탓'", "src": "Lloyd's Market Association", "date": "2026-03-23", "kSum": "로이즈 시장협회(LMA)의 로이즈 해상 전쟁보험 시장 설문에서 응답자의 88%가 미국·영국 선박을 포함한 국제 선체 전쟁위험 인수 의향을 유지하고 있으며, 90% 이상이 화물 위험 인수 의향을 유지한다고 답했다. LMA는 호르무즈 통항 감소가 보험 가용성 부족이 아니라 승무원·자산 안전 우려에서 비롯됐다고 강조했다. 평시 선체 전쟁보험료는 사실상 명목 수준에 불과하다고 설명했다.", "eSum": "An LMA survey of the Lloyd's marine war market found 88% of respondents retain appetite to underwrite international (incl. US/UK) hull war risks and over 90% for cargo. The LMA stressed that reduced Strait of Hormuz traffic is driven by crew and asset safety concerns, not insurance availability, noting peacetime hull war premiums are near-notional.", "kImp": "보험 가용성은 충분하다는 시장의 반박으로, 통항 위축의 원인 진단과 정부 개입 논의의 방향에 영향을 준다.", "eImp": "The market's rebuttal that cover remains ample reframes the debate over what is choking transits and whether governments should intervene.", "url": "https://lmalloyds.com/safety-concerns-not-insurance-availability-driving-reduced-vessel-traffic-in-the-strait-of-hormuz/"}]}, {"code": "PNI", "type": "news", "kTitle": "Section 13. P&I 클럽", "eTitle": "Section 13. P&I Clubs", "items": [{"code": "PNI", "title": "UK P&I클럽, TT클럽과의 합병 및 토마스밀러홀딩스 인수 진행상황 회람(12/26)", "src": "UK P&I Club", "date": "2026-07-13", "kSum": "UK P&I클럽(UK P&I Club)이 회람 12/26을 통해 TT클럽(TT Club)과의 합병 및 토마스밀러홀딩스(Thomas Miller Holdings, TMH) 인수 제안 진행상황을 회원에게 업데이트했다. 앞선 회람에 따르면 양 클럽은 6월 초 기본합의서를 체결하고 2027년 2월 20일 합병 완료를 목표로 하며, TMH 인수는 규제당국 승인을 거쳐 2026년 3분기 마무리될 전망이다.", "eSum": "The UK P&I Club issued Circular 12/26 updating Members on the progress of its proposed merger with the TT Club and the acquisition of Thomas Miller Holdings (TMH). Per earlier board circulars the clubs aimed to sign a framework agreement in early June, conclude the merger on 20 February 2027, and complete the TMH purchase in Q3 2026 subject to regulatory approval.", "kImp": "IG(International Group) 내 대형 상호클럽 간 통합으로 자본기반이 확대·다변화되며, 회원의 담보 연속성과 P&I 시장 경쟁구도에 직접적인 영향을 준다.", "eImp": "Consolidation of two major International Group mutuals broadens and diversifies capital, with direct implications for members' cover continuity and the competitive shape of the P&I market.", "url": "https://www.ukpandi.com/news-and-resources/circulars/article/circular-12/26-update-on-club-merger-and-acquisition-proposal/"}, {"code": "PNI", "title": "American Club 연차총회 결과·이사회 개편·2025 회계연도 결산 회람(16/26)", "src": "American Club", "date": "2026-07-14", "kSum": "아메리칸클럽(American Club)이 2026년 7월 14일 발행한 회람 16/26에서 연차총회 결과와 이사회 개편을 알렸다. 로버트 D. 본두란트(Robert D. Bondurant)를 의장, 존 A. 위트 주니어(John A. Witte, Jr.)를 부의장으로 선임하고, 도로테아 이오안누(Dorothea Ioannou) 최고경영자 겸 사무국장과 리로이 램버트(LeRoy Lambert) 법률고문을 유임했다. 2025년 12월 31일 종료 회계연도 연차보고서는 대형 사고의 심도 증가에도 직접 클레임이 개선되는 긍정적 흐름을 보였다고 밝혔다.", "eSum": "American Club Circular 16/26, issued 14 July 2026, reported the outcome of the club's Annual Meeting and board changes, electing Robert D. Bondurant as Chair and John A. Witte, Jr. as Deputy Chair, and re-appointing Dorothea Ioannou as CEO/Secretary and LeRoy Lambert as General Counsel. The Annual Report and Accounts for the year ended 31 December 2025 showed positive momentum with tangible improvement in direct claims despite increased severity in large casualties.", "kImp": "미국계 P&I 상호클럽의 지배구조 안정과 클레임 개선은 재무 건전성 신호로, 회원 요율·서비스 지속성 판단에 참고가 된다.", "eImp": "Governance stability and improving claims at the US-based mutual signal financial resilience, informing members' view of rating and service continuity.", "url": "https://allaboutshipping.co.uk/2026/07/14/american-pi-club-circular-no-16-26/"}, {"code": "PNI", "title": "UK P&I클럽 회람 11/26 - 남서태평양산 니켈광 안전운송 권고", "src": "UK P&I Club", "date": "2026-06-15", "kSum": "UK P&I클럽(UK P&I Club)이 회람 11/26에서 남서태평양(인도네시아·필리핀 등) 지역에서 선적되는 니켈광(nickel ore)의 액상화 위험과 안전운송 방안을 회원에게 안내했다. 이 회람은 IG(International Group)가 인터카고(INTERCARGO) 및 록스버러(Roxburgh)와 공동으로 작성한 것으로, 화물 관련 위험 완화를 위한 구체적 권고를 담고 있다.", "eSum": "UK P&I Club Circular 11/26 advises Members on the liquefaction risks and safe carriage of nickel ore loaded in the south-western Pacific (Indonesia, Philippines). Prepared by the International Group with INTERCARGO and Roxburgh, it sets out recommendations to help mitigate the associated cargo risks.", "kImp": "니켈광 액상화는 벌크선 전복 등 중대사고로 이어질 수 있어, 손해예방·클레임 방지 차원에서 선적 전 점검과 절차 준수가 중요하다.", "eImp": "Nickel ore liquefaction can cause catastrophic bulk carrier casualties, so pre-loading checks and procedural compliance are key to loss prevention and avoiding claims.", "url": "https://www.ukpandi.com/news-and-resources/circulars/article/circular-11/26-safe-carriage-of-nickel-ore-cargoes-in-the-south-western-pacific-ocean/"}, {"code": "PNI", "title": "UK P&I클럽 이사회 결과 회람(09/26) - 사상 최대 자기자본·클레임 동향", "src": "UK P&I Club", "date": "2026-05-22", "kSum": "UK P&I클럽(UK P&I Club)이 이탈리아 라팔로에서 열린 춘계 이사회 결과를 회람 09/26으로 발표했다. 2026년 2월 20일 종료 회계연도에 자유준비금이 사상 최대인 5억8600만 달러로 늘고 합산비율은 105%, 투자수익률 9.4%, 상호가입톤수는 1억6800만 GT로 성장했다. 다만 발티모어 달리(DALI) 사고 여파, 컨테이너선 화재, 미국 인명피해 배상비용 상승 등 클레임 변동성이 지속 논의됐다.", "eSum": "UK P&I Club Circular 09/26 reported the outcome of its spring board meetings in Rapallo, Italy. For the year ended 20 February 2026 free reserves rose to a record USD 586m, the combined ratio was 105%, investment return 9.4%, and mutual tonnage grew to 168m GT. Directors discussed continued claims volatility, including the DALI aftermath, containership fires, and rising US bodily-injury costs.", "kImp": "대형 IG 클럽의 실적 개선과 준비금 확충은 시장 안정 신호이나, 풀 클레임과 미국 배상비용 상승은 향후 요율 압력 요인으로 남는다.", "eImp": "Improved results and reserves at a major IG club signal stability, but pool claims and rising US bodily-injury costs remain upward pressures on future rating.", "url": "https://www.ukpandi.com/news-and-resources/circulars/article/circular-09/26-update-from-the-board/"}, {"code": "PNI", "title": "스팀십뮤추얼 결산·갱신보고 회람(L.481) - 2025/26 회계연도 실적", "src": "Steamship Mutual", "date": "2026-05-28", "kSum": "스팀십뮤추얼(Steamship Mutual)이 회람 L.481로 2025/26 회계연도 결산 및 갱신보고를 발표했다. 클레임 활동 증가 속에서도 자유준비금 5억7800만 달러, S&P A등급, 솔벤시 II 자본비율 220%를 유지했으며 합산비율은 112%를 기록했다. 자가보유톤수는 1억3800만 GT, 용선 포함 총 가입톤수는 2억8300만 GT로 성장했다.", "eSum": "Steamship Mutual issued Circular L.481, its year-end results and renewal report for the 2025/26 financial year. Amid heightened claims activity the club held free reserves of USD 578m, an S&P A rating and a 220% Solvency II ratio, with a combined ratio of 112%. Owned tonnage grew to 138m GT and total entered tonnage including chartered reached 283m GT.", "kImp": "합산비율 112%는 언더라이팅 적자를 뜻하지만 견고한 준비금과 투자수익이 이를 상쇄, 상호클럽 재무 회복력을 보여준다.", "eImp": "A 112% combined ratio implies an underwriting deficit offset by strong reserves and investment income, underscoring the mutual's financial resilience.", "url": "https://www.steamshipmutual.com/l481-year-end-results-and-renewal-report-202526-financial-year-highlights-0"}, {"code": "PNI", "title": "스팀십뮤추얼 회람(L.482) - 영국의 러시아 제재 확대와 해운·에너지·무역 영향", "src": "Steamship Mutual", "date": "2026-05-28", "kSum": "스팀십뮤추얼(Steamship Mutual)이 회람 L.482에서 영국(UK)의 러시아 제재 체계 확대 내용과 그것이 해운·에너지·무역에 미치는 주요 영향을 회원에게 안내했다. 지정 대상 및 금지 거래 확대에 따른 컴플라이언스 리스크와 실무상 유의점을 정리했다.", "eSum": "Steamship Mutual Circular L.482 briefs Members on the UK's expanded Russia sanctions regime and its key implications for maritime, energy and trade. It outlines the compliance risks and practical considerations arising from broadened designations and prohibited dealings.", "kImp": "P&I 담보는 제재 위반 시 배제될 수 있어, 선주는 거래 상대·화물·항로에 대한 강화된 실사와 클럽 제재 자문 활용이 필요하다.", "eImp": "P&I cover can be excluded on sanctions breaches, so owners need enhanced due diligence on counterparties, cargoes and routes and should use club sanctions advice.", "url": "https://www.steamshipmutual.com/l482-uk-expands-russia-sanctions-regime-key-implications-maritime-energy-and-trade"}, {"code": "PNI", "title": "스팀십뮤추얼 회람(L.480) - EU 대러시아 제20차 제재 패키지", "src": "Steamship Mutual", "date": "2026-05-12", "kSum": "스팀십뮤추얼(Steamship Mutual)이 회람 L.480으로 EU(European Union)의 대러시아 제20차 제재 패키지 내용을 회원에게 안내했다. 신규 지정과 무역·해운 관련 조치의 개요 및 회원 유의사항을 담고 있다.", "eSum": "Steamship Mutual Circular L.480 informs Members of the European Union's 20th sanctions package against Russia, summarising the new designations and trade/shipping-related measures together with points for members to note.", "kImp": "제재 패키지가 거듭 강화되면서 선주·클럽 모두 지속적인 명단·거래 모니터링과 회람 반영이 필수적이다.", "eImp": "With sanctions packages successively tightened, both owners and clubs must continuously monitor designations and dealings and reflect updates in their compliance.", "url": "https://www.steamshipmutual.com/l480-eu-sanctions-20th-sanctions-package-against-russia"}, {"code": "PNI", "title": "IG, 2026/27 정책연도 풀·초과손해 재보험(GXL) 구조 확정", "src": "International Group of P&I Clubs", "date": "2025-12-17", "kSum": "국제그룹(International Group, IG)이 2026/27 정책연도의 풀링 및 그룹 초과손해 재보험(GXL) 구조를 확정했다. 개별 클럽 보유는 1000만 달러, 풀은 1000만 초과 9000만 달러이며, GXL은 Layer1 6억5000만(72.5% 공개시장+27.5% 4개 사모물건), Layer2 7억5000만, Layer3는 15억 초과 8억5000만 달러로 확대됐고, 집단 초과담보는 23억5000만 초과 10억 달러로 조정됐다. 선종별 요율은 지속성 유류 -8%, 크린탱커 동결, 드라이 -5%, FCC(컨테이너) +15%, 여객선 -8.5%로 조정됐다.", "eSum": "The International Group finalised its Pooling and Group Excess of Loss (GXL) reinsurance structure for the 2026/27 policy year. Individual club retention stays at USD 10m and the pool at USD 90m xs 10m; Layer 1 is USD 650m (72.5% open market plus 27.5% via four private placements), Layer 2 USD 750m, and Layer 3 expanded to USD 850m xs USD 1.5bn, with Collective Overspill of USD 1bn xs USD 2.35bn. Rate changes are persistent oil -8%, clean tankers nil, dry -5%, FCC (containers) +15% and passenger -8.5%.", "kImp": "IG 재보험 프로그램은 전 세계 원양톤수 약 90%의 담보 한도를 좌우하며, FCC(컨테이너) +15% 인상은 컨테이너 선주의 2026/27 갱신 비용 상승으로 직결된다.", "eImp": "The IG reinsurance programme sets cover limits for about 90% of world ocean tonnage, and the FCC (container) +15% rise translates directly into higher 2026/27 renewal costs for container owners.", "url": "https://www.igpandi.org/article/the-international-group-pooling-and-group-excess-of-loss-reinsurance-contract-gxl-structure-for-the-202627-policy-year-has-now-been-finalised/"}, {"code": "PNI", "title": "가드(Gard), 2026 정책연도 보험료 정책 - 평균 5% 일반요율 인상", "src": "Gard", "date": "2025-11-01", "kSum": "가드(Gard)가 2026 정책연도 보험료 정책 회람을 통해 P&I 부문 평균 5%의 일반요율 인상(general increase)과 함께 선주 대상 10% 일반 할인을 적용한다고 밝혔다. 이는 2026년 2월 20일 갱신을 앞둔 요율·조건 안내로, 세계 최대 P&I 클럽의 갱신 기조를 보여준다. (날짜는 발행 월(2025년 11월)까지 확인, 정확한 일자는 미확인.)", "eSum": "Gard's premium policy circular for the 2026 policy year sets an average 5% general increase for P&I together with a 10% owners' general discount. It frames rating and terms ahead of the 20 February 2026 renewal and signals the renewal stance of the world's largest P&I club. (Date confirmed to publication month, November 2025; exact day not verified.)", "kImp": "최대 상호클럽의 5% 일반인상은 시장 전반의 갱신 요율 방향을 가늠하는 지표로, 선주 예산·재보험 비용 전가 폭 판단에 참고가 된다.", "eImp": "A 5% general increase at the largest mutual is a bellwether for market-wide renewal rating, informing owners' budgeting and the pass-through of reinsurance costs.", "url": "https://www.gard.no/circulars/premium-policy-for-the-2026-policy-year/"}]}, {"code": "VET", "type": "news", "kTitle": "Section 14. 베팅·검사", "eTitle": "Section 14. Vetting & Inspection", "items": [{"code": "VET", "title": "RightShip, 검사 모델 개편 예고 — 저심각도 지적 클로즈아웃 완화·AI 심각도 분류 확대", "src": "RightShip", "date": "2026-05-12", "kSum": "라이트십(RightShip)이 포시도니아(Posidonia) 2026 기간 그리스 포럼에서 검사 체계 개편 방향을 제시했다. 향후 필수 클로즈아웃(closeout)은 고·중 심각도 지적에 집중하고 저심각도 지적은 정식 클로즈아웃 대상에서 제외하며, 기존 PSC 분석에 쓰이던 AI 기반 심각도 분류를 검사에 확대 적용한다. 중복 검사 부담을 줄이고 단일 검사로 여러 보증 수요를 충족하는 것을 지향한다.", "eSum": "At its Greece Forum during Posidonia 2026, RightShip outlined a reshaped inspection model: mandatory closeouts will focus on high- and medium-severity findings while low-severity findings no longer require the formal closeout, and AI-supported severity classification (already used in PSC analysis) will extend to inspections. The goal is to cut duplication so a single inspection can satisfy multiple assurance needs.", "kImp": "저심각도 지적의 행정 부담 경감은 선원·감독자 업무를 줄이지만, AI 심각도 분류 도입으로 지적의 일관성·예측가능성 변화에 대비할 필요가 있다.", "eImp": "Easing admin on low-severity findings reduces crew/superintendent workload, but operators should prepare for shifts in finding consistency as AI severity classification is introduced.", "url": "https://rightship.com/insights/rightship-greece-forum-2026-advancing-rightship-inspections"}, {"code": "VET", "title": "RightShip RISQ 3.2 개정·하이브리드 검사 확대 — 2025년 약 5,000건 검사", "src": "RightShip", "date": "2025-11-26", "kSum": "라이트십(RightShip)이 2025년 11월 26일 딥다이브 웨비나에서 검사선박질문서(RISQ) 3.2 개정을 발표했다. 22개 해운단체와 240여 건의 의견을 반영해 150여 개 항목을 조정하고 30개 문항을 통합·삭제하여 검사 시간을 약 2시간 단축했다. 2025년 100여 개국·800여 항에서 약 5,000건을 검사했으며, 밀폐구역 진입·구명소화설비·해치커버·파일럿 사다리 등이 주요 지적으로 나타났다.", "eSum": "In a 26 November 2025 Deep Dive webinar, RightShip unveiled RISQ 3.2, incorporating input from 22 associations and 240+ submissions, with 150+ adjustments and 30 questions consolidated or removed, cutting about 2 hours of inspection time. RightShip ran ~5,000 inspections across 100+ countries and 800+ ports in 2025, with enclosed-space entry, LSA/FFE, hatch covers and pilot ladders among the most common findings.", "kImp": "하이브리드 검사(평균 11.5시간)와 문서관리센터 사전 제출로 승선 검사 시간이 줄어, 벌크선 관리자는 사전 준비를 통해 검사 부담을 낮출 수 있다.", "eImp": "Hybrid inspections (avg 11.5 hrs) and advance document submission reduce onboard time, letting bulk managers lower inspection burden through preparation.", "url": "https://rightship.com/insights/deep-dive-advancing-vessel-safety-update-risq-3.2-and-rightship-inspections"}, {"code": "VET", "title": "INTERCARGO, 벌크화물 최초 전용 STS(선박간 이송) 표준 발표", "src": "Cyprus Shipping News", "date": "2026-05-22", "kSum": "국제건화물선주협회(INTERCARGO)가 STS(선박간 화물이송) 작업 증가에 대응해 벌크화물 전용 최초의 STS 표준을 발표했다. 이는 DryBMS 등 건화물 부문 운영표준·베팅 체계를 보완하는 조치로, 협회는 싱가포르 반기 집행·기술위원회에서 안전·베팅 현안을 함께 논의했다.", "eSum": "INTERCARGO released the first dedicated ship-to-ship (STS) transfer standard for dry bulk cargoes as STS operations increase, complementing dry bulk operational standards such as DryBMS and vetting frameworks. The association also progressed safety and vetting issues at its semi-annual Executive and Technical Committee meetings in Singapore.", "kImp": "벌크 부문 STS 작업의 표준화는 향후 RightShip 등 제3자 베팅·검사 기준에 반영될 수 있어 벌크선 운영자의 주의가 필요하다.", "eImp": "Standardising dry bulk STS operations may feed into third-party vetting and inspection criteria (e.g., RightShip), warranting attention from bulk operators.", "url": "https://cyprusshippingnews.com/2026/05/22/first-dedicated-sts-standard-for-dry-bulk-released-by-intercargo-as-operations-increase/"}]}, {"code": "CLASS", "type": "news", "kTitle": "Section 15. 선급", "eTitle": "Section 15. Classification Societies", "items": [{"code": "CLASS", "title": "DNV, 2026년 7월판 선급 규칙·표준 발행 - 신규 선급 부호 다수 추가", "src": "DNV", "date": "2026-07-02", "kSum": "DNV(디엔브이)가 2026년 7월 2일 선박·해양구조물용 선급 규칙·표준 2026년 7월판을 발행했다. FL(설계 피로수명), Battery ready(배터리 대응), Shore power ready(육상전원 대응) 등 신규 선급 부호와 가스 벙커링·초저배출(ER(ULEV)) 관련 자격부호가 추가됐다. 개정 규칙은 2027년 1월 1일 발효된다.", "eSum": "DNV published the July 2026 edition of its rules and standards for ships and offshore units on 2 July 2026. New class notations include FL (design fatigue life), Battery ready and Shore power ready, plus new qualifiers for gas bunkering and ultra-low emissions (ER(ULEV)). The updated rules enter into force on 1 January 2027.", "kImp": "신조선 설계·발주 단계에서 대체연료·배터리·육상전원 대응 사양을 조기에 반영해야 하므로 선주·조선소·설계사의 사전 검토가 필요하다.", "eImp": "Owners, yards and designers should review the new notations early, as newbuild specifications for alternative fuels, batteries and shore power must be reflected at the design and ordering stage.", "url": "https://www.dnv.com/news/2026/standards-now-available-the-july-2026-edition-of-the-dnv-class-rules-and-standards-for-ship-and-offshore/"}, {"code": "CLASS", "title": "한국선급-HD현대중공업, 국내 첫 암모니아 이중연료선 시운전…그린 십핑 코리도 추진", "src": "India Shipping News", "date": "2026-07-15", "kSum": "한국선급(KR)이 HD현대중공업(HHI)과 함께 해양수산부 '그린 십핑 코리도 구축 지원사업'의 일환으로 암모니아 추진선의 국내 운항 환경 조성을 추진한다. HHI는 최근 국내 첫 암모니아 이중연료 추진선의 해상 시운전을 실시했다. 확보된 연료공급계통·엔진 운항 데이터는 KR의 친환경 선박 운항 지침 개발에 활용된다.", "eSum": "Korean Register (KR) is working with HD Hyundai Heavy Industries (HHI) under the Ministry of Oceans and Fisheries' Green Shipping Corridor project to build a domestic operating environment for ammonia-fueled vessels. HHI recently conducted a sea trial of Korea's first ammonia dual-fuel propulsion vessel. The operational data on the fuel supply system and engine will inform KR's future guidelines for eco-friendly vessel operation.", "kImp": "국내 암모니아 추진 생태계 구축과 KR·IACS·IMO 기준 마련의 기술 기반이 되는 사업으로, 한국 조선·해운의 탈탄소 경쟁력에 직결된다.", "eImp": "The project builds the technical foundation for Korea's ammonia ecosystem and for KR/IACS/IMO standards, directly supporting the decarbonization competitiveness of Korean shipbuilding and shipping.", "url": "https://indiashippingnews.com/classification-society/kr-and-hd-hyundai-advance-koreas-green-shipping-corridor-through-ammonia-vessel-trial/"}, {"code": "CLASS", "title": "ABS, 컨테이너선 적재 유연성 높이는 'Eagle CRoute' 출시", "src": "ABS", "date": "2026-06-30", "kSum": "ABS(미국선급)가 컨테이너선의 항로 기반 래싱 저감계수를 산출하는 온라인 도구 'Eagle CRoute'를 2026년 6월 30일 출시했다. CLP-V 부호 선박은 전체 항로 계수를, CLP-V(PARR) 부호는 항구별·계절별 분할 계수를 계산한다. 72시간 미만 단거리 항해에 대해서는 기상·파랑 예보 기반의 저감계수도 제공한다.", "eSum": "ABS launched Eagle CRoute on 30 June 2026, an online tool that calculates route-based lashing reduction factors for containerships. For CLP-V vessels it computes whole-route factors, while CLP-V(PARR) yields split port-to-port and seasonal factors. It also provides short-voyage reduction factors for trips under 72 hours using weather and wave forecasts.", "kImp": "블랭크 세일링과 기항지 변경이 잦은 환경에서 안전을 유지하면서 적재량을 최적화할 수 있어 컨테이너 선사의 운영 유연성이 커진다.", "eImp": "The tool lets container operators optimize stowage while maintaining safety amid frequent blank sailings and changing port rotations.", "url": "https://pressreleases.eagle.org/news/abs-launches-eagle-croute-to-improve-containership-loading-flexibility"}, {"code": "CLASS", "title": "ABS, 가스로그 LNG선에 SMART(MHM)+PMP-CBM 부호 세계 첫 동시 부여", "src": "ABS", "date": "2026-06-29", "kSum": "가스로그(GasLog)의 LNG운반선이 ABS SMART(MHM) 기계건전성 모니터링 부호와 예방정비프로그램(PMP)을 결합해 세계 최초로 획득한 상선이 됐다(2026년 6월 29일). 이 부호는 상시 설치형 시스템이 기계 상태를 모니터링하고 성능저하를 예측함을 검증한다. 프로펄션 애널리틱스(Propulsion Analytics)의 플랫폼과 콩스버그(Kongsberg) Vessel Insight 텔레메트리를 활용해 상태기반정비를 구현했다.", "eSum": "A GasLog LNG carrier became the world's first commercial vessel to combine the ABS SMART (MHM) machinery health monitoring notation with the Preventative Maintenance Program (PMP), announced 29 June 2026. The notation validates a permanently installed system that monitors machinery health and predicts degradation. It was built with Propulsion Analytics' platform and Kongsberg Vessel Insight telemetry to enable condition-based maintenance.", "kImp": "상태기반정비 전환으로 계획정비 부담과 다운타임을 줄일 수 있어 디지털 선급·스마트십 확산의 실증 사례가 된다.", "eImp": "The condition-based maintenance approach reduces planned-maintenance burden and downtime, serving as a proof point for digital class and smart-ship adoption.", "url": "https://pressreleases.eagle.org/news/gaslog-vessel-receives-combined-abs-smart-mhm-and-pmp-cbm-notations-in-industry-first"}, {"code": "CLASS", "title": "미 해양혁신센터(ABS 사무국), 해양 원자력 규제 장벽 논의 워크숍 개최", "src": "ABS", "date": "2026-06-26", "kSum": "ABS가 미 해사청(MARAD) 지정 사무국을 맡은 미국해양혁신센터(USCMI)가 2026년 6월 26일 미 해안경비대·MARAD와 함께 선박 원자력 추진의 규제 장벽 해소를 위한 워크숍을 개최했다. 선주·조선소·선급·연방기관(USCG, NRC) 등이 참여했다. 소형모듈원자로(SMR) 인허가 경로, 안전 프레임워크, 국제 규제 조율이 논의됐다.", "eSum": "The U.S. Center for Maritime Innovation (USCMI), whose secretariat is ABS as appointed by MARAD, held a workshop on 26 June 2026 with the U.S. Coast Guard and MARAD to address regulatory barriers to maritime nuclear propulsion. Shipowners, shipbuilders, classification societies and federal agencies (USCG, NRC) took part. Discussions covered SMR licensing pathways, safety frameworks and international regulatory coordination.", "kImp": "원자력 추진이 차세대 무탄소 옵션으로 부상하는 가운데 선급 주도의 규제 정비 논의가 상업화 시점을 좌우할 전망이다.", "eImp": "As nuclear propulsion emerges as a next-generation zero-carbon option, class-led regulatory groundwork will shape its path to commercialization.", "url": "https://pressreleases.eagle.org/news/u-s-center-for-maritime-innovation-convenes-leaders-to-address-regulatory-barriers-to-maritime-nuclear-technologies"}, {"code": "CLASS", "title": "선전항-뷰로베리타스, 그린 십핑 코리도 개발 협력 체결", "src": "Offshore Energy", "date": "2026-07-01", "kSum": "선전항그룹(Shenzhen Port Group)과 뷰로베리타스 마린&오프쇼어(Bureau Veritas)가 2026년 7월 1일 선전에서 그린 십핑 코리도 및 관련 사업 공동 개발을 위한 전략적 협력 협정을 체결했다. 양측은 각자의 자원과 전문성을 결집하기로 했다.", "eSum": "Shenzhen Port Group and Bureau Veritas Marine & Offshore signed a strategic cooperation agreement in Shenzhen on 1 July 2026 to jointly develop green shipping corridors and related businesses. The two sides will pool their respective resources and expertise.", "kImp": "항만-선급 간 협력은 대체연료 공급·인프라 등 그린 코리도 실현의 실무 장벽 해소에 기여한다.", "eImp": "Port-class collaboration helps remove practical barriers to green corridors, such as alternative-fuel supply and infrastructure.", "url": "https://www.offshore-energy.biz/shenzhen-port-and-bureau-veritas-partner-up-for-green-shipping-corridor-development/"}, {"code": "CLASS", "title": "뷰로베리타스, 다이나콤 신조 7만3500dwt 유조선 선급 등록", "src": "Container News", "date": "2026-07-06", "kSum": "뷰로베리타스(Bureau Veritas)가 뉴타임스조선(New Times Shipbuilding)이 건조해 그리스 선주 다이나콤(Dynacom)에 인도한 7만3500dwt 원유·석유제품 운반선 'M/T MODI'를 선급 등록했다(2026년 7월 6일). 이 선박은 CLEANSHIP, GREEN PASSPORT EU, 바이오연료 대응(BIOFUEL-READY), LNG연료 준비(LNGFUEL-PREPARED) 부호를 받았다. 사이버 복원력 요건과 SYS-NEQ-1(원맨 브리지 제어), AUT-PORT(자동 접안) 부호도 부여됐다.", "eSum": "Bureau Veritas classed M/T MODI, a 73,500 dwt crude and product oil tanker built by New Times Shipbuilding for Greek owner Dynacom and delivered in June (reported 6 July 2026). The vessel received CLEANSHIP, GREEN PASSPORT EU, BIOFUEL-READY and LNGFUEL-PREPARED notations. It also earned BV's CYBER RESILIENT requirements plus SYS-NEQ-1 (one-man bridge control) and AUT-PORT (auto-docking) notations.", "kImp": "신조선 수주·인도 실적과 함께 자동화·사이버·대체연료 대응 부호가 표준 사양으로 정착되는 추세를 보여준다.", "eImp": "The delivery shows how automation, cyber and alternative-fuel-ready notations are becoming standard on newbuild tankers.", "url": "https://container-news.com/bureau-veritas-classes-dynacoms-new-73500-dwt-oil-tanker/"}]}, {"code": "COMM", "type": "news", "kTitle": "Section 16. 상업·용선시장", "eTitle": "Section 16. Commercial & Chartering", "items": [{"code": "COMM", "title": "JP Morgan tied to Hanwha VLCC brace", "src": "Splash247", "date": "2026-07-16", "kSum": "미국 금융 대기업 JP모건(JP Morgan)이 한화오션(Hanwha Ocean)에 발주된 VLCC(초대형 원유운반선) 신조 2척의 실소유주로 지목됐다. 금융자본이 탱커 신조 시장에 직접 참여하는 사례로 확인됐다.", "eSum": "US financial giant JP Morgan has been named as the owner behind Hanwha Ocean's latest order for two VLCC newbuildings, an example of financial capital entering the tanker newbuilding market directly.", "kImp": "2026년 VLCC 신조 발주 급증세 속에서 금융 투자자의 참여가 두드러지며, 초대형 원유운반선 공급 확대 흐름을 보여준다.", "eImp": "Financial investor participation amid 2026's VLCC ordering surge underlines the expanding crude tanker supply pipeline.", "url": "https://splash247.com/jp-morgan-tied-to-hanwha-vlcc-brace/"}, {"code": "COMM", "title": "US tariff on Brazilian exports looms amid array of new trade deals", "src": "The Loadstar", "date": "2026-07-16", "kSum": "트럼프 행정부가 일부 브라질산 수입품에 25% 관세를 부과할 예정이며, 이는 잇따라 발표된 여러 신규 무역 협정과 맞물려 나온 조치다. 미국의 관세 정책 변화가 글로벌 무역 흐름에 영향을 주고 있다.", "eSum": "The Trump administration will place a 25% tariff on certain Brazilian imports, the latest move alongside an array of new trade deals reshaping global trade flows.", "kImp": "미국의 대브라질 관세 부과는 남미-북미 무역 물동량과 관련 해상 운송 수요에 변수로 작용한다.", "eImp": "The Brazil tariff introduces uncertainty for South America-North America trade volumes and related ocean shipping demand.", "url": "https://theloadstar.com/us-tariff-on-brazilian-exports-looms-amid-array-of-new-trade-deals/"}, {"code": "COMM", "title": "CMA CGM announces new peak season surcharges on four trade lanes", "src": "Container News", "date": "2026-07-18", "kSum": "CMA CGM이 4개 무역 항로에 새로운 성수기 할증료(PSS)를 도입한다고 발표했다. 주요 선사들의 성수기 운임 조정이 잇따르고 있다.", "eSum": "CMA CGM has announced new peak season surcharges (PSS) across four trade lanes, part of a wave of peak-season pricing adjustments by major carriers.", "kImp": "대형 선사의 성수기 할증료 부과는 해당 항로의 컨테이너 운임 상승 압력을 반영한다.", "eImp": "The carrier's peak season surcharges reflect upward pricing pressure on the affected container trades.", "url": "https://container-news.com/cma-cgm-announces-new-peak-season-surcharges-on-four-trade-lanes/"}, {"code": "COMM", "title": "MSC revises transatlantic network with NEUSEC2 suspension", "src": "Container News", "date": "2026-07-19", "kSum": "MSC가 대서양 횡단 네트워크를 개편하면서 NEUSEC2 서비스를 중단한다. 대서양 항로의 선복 및 서비스 구성 조정이 이뤄지고 있다.", "eSum": "MSC is revising its transatlantic network, suspending the NEUSEC2 service as it adjusts capacity and service coverage on the Atlantic trade.", "kImp": "대서양 항로 서비스 축소는 해당 항로의 수급 조정 움직임을 보여주는 지표다.", "eImp": "The service suspension is an indicator of capacity rebalancing on the transatlantic trade.", "url": "https://container-news.com/msc-revises-transatlantic-network-with-neusec2-suspension/"}, {"code": "COMM", "title": "Sinotrans expands China–India network with new CIW2 service", "src": "Container News", "date": "2026-07-19", "kSum": "시노트란스(Sinotrans)가 신규 CIW2 서비스를 도입해 중국-인도 항로 네트워크를 확장한다. 아시아 역내 및 중국-인도 무역 항로에서의 서비스 신설이 이어지고 있다.", "eSum": "Sinotrans is expanding its China-India network with a new CIW2 service, adding to a run of new service launches on Asia and China-India trade routes.", "kImp": "중국-인도 신규 서비스 개설은 해당 무역로의 물동량 증가 기대와 항로 경쟁 심화를 시사한다.", "eImp": "The new China-India service points to expected volume growth and intensifying competition on that trade lane.", "url": "https://container-news.com/sinotrans-expands-china-india-network-with-new-ciw2-service/"}, {"code": "COMM", "title": "Oakland exports rebound as June volumes climb", "src": "Splash247", "date": "2026-07-18", "kSum": "미국 오클랜드항(Port of Oakland)의 6월 물동량이 18만1,356TEU로 전년 동월 대비 7.7% 증가했다. 수출 적재 컨테이너가 11.5% 늘어난 8만330TEU를 기록하는 등 농산물·냉장화물 기반의 수출 회복이 두드러졌다. 이는 수입 주도 성장으로 공컨테이너 반송이 늘어난 미국 내 다른 주요 항만과 대조된다.", "eSum": "The Port of Oakland handled 181,356 teu in June, up 7.7% year on year. Loaded exports climbed 11.5% to 80,330 teu on stronger agricultural and reefer cargo, contrasting with the import-led empty-box buildup seen at other major US gateways.", "kImp": "미국 서안 수출항의 물동량 회복은 미-아시아 무역흐름 개선과 공컨테이너 재배치 부담 완화를 시사한다.", "eImp": "The export rebound at a US West Coast gateway signals firmer US-Asia trade flows and eased empty-container repositioning pressure.", "url": "https://splash247.com/oakland-exports-rebound-as-june-volumes-climb/"}]}, {"code": "GEO", "type": "news", "kTitle": "Section 17. 지정학", "eTitle": "Section 17. Geopolitics", "items": [{"code": "GEO", "title": "제재 대상 유조선, 오만 해역 보호구역서 기름 유출 정황", "src": "gCaptain", "date": "2026-07-18", "kSum": "러시아산 연료 운송으로 EU와 영국의 제재를 받은 유조선 캐롤라인 베젠기(Caroline Bezengi)가 오만 앞바다 해양 보호구역에서 기름을 유출하고 있는 것으로 위성영상 분석 결과 나타났다. 이 선박은 6월 11일 예멘 앞바다에서 AIS 신호가 끊긴 뒤 표류 중이며, 유출 원인이 노후·손상인지 공격인지는 불분명하다. 노후 그림자 선대를 이용한 제재 회피 운송의 위험성을 재확인시킨다.", "eSum": "Satellite imagery analysis indicates the tanker Caroline Bezengi, sanctioned by the EU and UK for carrying Russian fuel, is likely leaking oil in a protected marine area off Oman. The vessel went dark on AIS on June 11 off Yemen, and the cause, whether decay, damage or attack, is unclear, underscoring the hazards of sanctions-evading trade on aging shadow-fleet tankers.", "kImp": "노후 그림자 선대가 초래하는 환경·안전 리스크를 부각하며, 제재 회피 운송의 부작용과 연안국의 대응 부담을 드러낸다.", "eImp": "Underscores the environmental and safety risks posed by aging shadow-fleet tankers and the burden placed on coastal states by sanctions-evading trade.", "url": "https://gcaptain.com/sanctioned-tanker-is-leaking-oil-near-oman/"}, {"code": "GEO", "title": "덴마크 파야드(Fayard) 조선소, 러시아 LNG선 수리로 정치적 압박 직면", "src": "The Maritime Executive", "date": "2026-07-19", "kSum": "EU에서 마지막으로 러시아 야말(Yamal) LNG용 Arc7 쇄빙 운반선을 정비하는 덴마크 파야드(Fayard) 조선소가 16개국 의원 104명의 공개서한 등 거센 정치적 압박을 받고 있다. 파야드는 현행 EU 규정을 준수하고 있다며 해당 작업을 올해 말 종료하겠다고 밝혔다. 한 분석은 EU가 2026년 상반기에 야말 북극 LNG 대금으로 약 68억 달러를 지불했다고 지적했다.", "eSum": "Denmark's Fayard, reportedly the last EU yard still servicing Russia's Arc7 Yamal LNG carriers, faces mounting political pressure including an open letter from 104 parliamentarians across 16 countries. Fayard says its work complies with current EU rules but will cease at year-end, even as analysis shows the EU paid an estimated $6.82 billion for Yamal Arctic LNG in the first half of 2026.", "kImp": "서방 조선·정비 인프라가 러시아 에너지 수출을 뒷받침하는 회색지대를 조명하며, 2027년 EU 가스 금수 이전 제재 실효성 논쟁을 키운다.", "eImp": "Spotlights the grey zone in which Western shipyard and maintenance infrastructure sustains Russian energy exports, intensifying debate over sanctions efficacy ahead of the 2027 EU gas embargo.", "url": "https://maritime-executive.com/article/fayard-shipyard-under-pressure-for-repairing-russia-serving-lng-carriers"}, {"code": "GEO", "title": "이란, 후티에 홍해 원유 항로 봉쇄 태세 요청… 재점화 우려", "src": "Container News", "date": "2026-07-17", "kSum": "이란이 예멘 후티(Houthi) 세력에게 미국이 이란 전력 인프라를 타격할 경우 홍해 원유 항로를 봉쇄할 태세를 갖추라고 요청한 것으로 전해졌다. 이는 세계에서 가장 민감한 해상 통로 중 하나를 다시 분쟁의 사정권에 두는 움직임이다. 홍해·바브엘만데브 위기의 재점화 가능성을 시사한다.", "eSum": "Iran has reportedly asked Yemen's Houthi movement to be ready to shut the Red Sea oil route should the United States strike Iranian power infrastructure, placing one of the world's most sensitive shipping arteries back in the line of fire and signaling a possible re-escalation of the Red Sea and Bab el-Mandeb crisis.", "kImp": "홍해 위기 재점화 시 수에즈 우회와 희망봉 항로 장기화, 컨테이너 운임·보험료 급등 리스크를 다시 부각한다.", "eImp": "Revives the risk that a renewed Red Sea crisis would prolong Cape of Good Hope diversions around Suez and drive spikes in container freight and insurance costs.", "url": "https://container-news.com/what-houthis-re-activation-could-cause/"}, {"code": "GEO", "title": "Russian Attack on Corn Ship Off Ukraine's Odesa Kills 10", "src": "gCaptain", "date": "2026-07-20", "kSum": "러시아 순항미사일 3발이 우크라이나 오데사(Odesa) 인근에서 옥수수 운반선 골든 레오(Golden Leo, 기니비사우 선적)를 타격해 선원 9명과 도선사 1명 등 10명이 사망했다. 흑해와 아조우해에서 러시아-우크라이나 간 상선·항만 상호 공격이 격화되면서 국제 밀값이 2년 만의 최고치로 올랐다.", "eSum": "Three Russian cruise missiles hit the Guinea-Bissau-flagged corn carrier Golden Leo off Odesa, killing 10 people (nine crew and one maritime pilot). Escalating Russia-Ukraine strikes on Black Sea and Sea of Azov ships and ports have pushed international wheat prices to a two-year high.", "kImp": "흑해 곡물 수출 회랑에 대한 물리적 위협이 상선 안전, 전쟁위험보험료, 곡물 공급망을 직접 타격하고 있다. 우크라이나는 이미 흑해 항만을 통한 수출능력의 약 3분의 1을 상실했다.", "eImp": "Direct threats to the Black Sea grain corridor hit vessel safety, war-risk premiums and food supply chains. Ukraine has already lost about a third of its export capacity via its Black Sea ports.", "url": "https://gcaptain.com/russian-attack-on-corn-ship-off-ukraines-odesa-kills-10/"}, {"code": "GEO", "title": "Sanctioned Heavy-Lift Ships Deliver Key Arctic LNG 2 Modules to Russia, Pointing to Construction Restart", "src": "gCaptain", "date": "2026-07-20", "kSum": "미국 제재 대상인 중량물 운반선 글로리 오션(Glory Ocean)과 브라이트 오션(Bright Ocean)이 중국에서 러시아 노바텍(Novatek)의 벨로카멘카 야드로 아크틱 LNG 2(Arctic LNG 2) 3번 트레인용 핵심 상부 모듈을 운송했다. 위성영상(Synmax) 분석 결과 서방 제재 속에서도 장기 정체됐던 건설이 재개될 정황이 포착됐다.", "eSum": "US-sanctioned heavy-lift vessels Glory Ocean and Bright Ocean delivered key topside modules from China to Novatek's Belokamenka yard for Arctic LNG 2's third production train. Satellite imagery from Synmax offers the clearest indication yet that construction is restarting despite Western sanctions.", "kImp": "그림자 선단과 제재 회피 물류가 러시아 아크틱 LNG 프로젝트를 재가동시키는 정황으로, 서방 제재의 실효성과 향후 글로벌 LNG 수급 전망에 파장을 줄 수 있다.", "eImp": "Sanctions-evading shadow logistics reviving Russia's Arctic LNG project raises questions over the bite of Western sanctions and could reshape the global LNG supply outlook.", "url": "https://gcaptain.com/sanctioned-heavy-lift-ships-deliver-key-arctic-lng-2-modules-to-russia-pointing-to-construction/"}, {"code": "GEO", "title": "Iran primes Houthis to shut Bab el-Mandeb", "src": "Splash247", "date": "2026-07-17", "kSum": "이란이 미국의 이란 전력시설 공격 시 바브엘만데브(Bab el-Mandeb) 해협 봉쇄를 준비하도록 예멘 후티(Houthi)에 요청했다고 로이터가 소식통 3명을 인용해 보도했다. 후티는 이미 미사일과 드론을 해협 인근에 배치하고 공격 명령을 대기 중인 것으로 전해졌다. 홍해 봉쇄 시 사우디 얀부(Yanbu)발 원유 수출로가 위협받는다.", "eSum": "Reuters reports, citing three sources, that Iran has asked Yemen's Houthis to prepare to close the Bab el-Mandeb Strait if the US strikes Iranian power infrastructure, with missiles and drones reportedly already positioned. A closure would threaten Saudi crude exports via the Red Sea port of Yanbu.", "kImp": "홍해 위기 재발 위험이 다시 고조될 경우 희망봉 우회 확대와 운임·보험료 급등이 불가피하다. 컨테이너·벌크·에너지 전반의 공급망 교란이 우려된다.", "eImp": "A renewed Red Sea crisis would force wider Cape of Good Hope diversions and spike freight and insurance costs, threatening disruption across container, bulk and energy supply chains.", "url": "https://splash247.com/iran-primes-houthis-to-shut-bab-el-mandeb/"}, {"code": "GEO", "title": "U.S. Coast Guard Tracks Chinese Icebreakers as They Transit U.S. Arctic Waters", "src": "gCaptain", "date": "2026-07-17", "kSum": "미국 해안경비대가 베링해를 지나 북극으로 향하는 중국 쇄빙연구선 쉐룽(Xue Long)과 쉐룽2(Xue Long 2)를 추적하고 있다고 밝혔다. 이는 올해 첫 중국 선박의 미국 배타적경제수역(EEZ) 통과로, 커터 먼로(Munro)가 '프론티어 센티넬' 작전으로 감시에 나섰다. 북극에서 미-중 전략경쟁이 심화되는 양상이다.", "eSum": "The US Coast Guard said it is monitoring Chinese research icebreakers Xue Long and Xue Long 2 transiting the Bering Sea toward the Arctic, the first Chinese passage through the US EEZ this year. The cutter Munro was deployed under Operation Frontier Sentinel amid intensifying US-China Arctic competition.", "kImp": "북극항로(NSR) 상업화 움직임과 미-중 전략경쟁이 맞물리며, 신흥 아시아-유럽 항로를 둘러싼 지정학 리스크와 거버넌스 문제가 부각된다.", "eImp": "Overlapping NSR commercialization and US-China rivalry heighten geopolitical risk and governance questions over an emerging Asia-Europe shipping route.", "url": "https://gcaptain.com/u-s-coast-guard-tracks-chinese-icebreakers-as-they-transit-u-s-arctic-waters/"}, {"code": "GEO", "title": "European lawmakers demand Fayard drop Arc7 repair work", "src": "Splash247", "date": "2026-07-17", "kSum": "유럽 16개국 의원 100여 명이 덴마크 조선소 파야드(Fayard)에 러시아 아크틱 LNG 수출을 지탱하는 Arc7 쇄빙 탱커 수리를 중단할 것을 요구하는 공개서한을 발표했다. EU의 20차 제재는 2027년부터 러시아 관련 LNG선 정비를 금지하며, 파야드는 사실상 이들 선박을 받아주는 마지막 EU 정비처다.", "eSum": "More than 100 lawmakers from 16 European countries issued an open letter urging Denmark's Fayard shipyard to stop servicing the Arc7 ice-class tankers that keep Russia's Arctic LNG exports moving. The EU's 20th sanctions package bans such maintenance from 2027, and Fayard is effectively the last EU yard still accepting the fleet.", "kImp": "그림자·특수선단의 정비 차단은 러시아 야말 LNG(Yamal LNG) 물류의 핵심 고리를 겨냥한 것으로, 제재 이행 강화 흐름이 러시아 LNG 수출의 지속 가능성을 압박한다.", "eImp": "Cutting off maintenance targets a critical link in Russia's Yamal LNG logistics, with tightening enforcement pressuring the durability of Russian LNG exports.", "url": "https://splash247.com/european-lawmakers-demand-fayard-drop-arc7-repair-work/"}]}, {"code": "TW", "type": "news", "kTitle": "Section 18. TradeWinds 선박관리", "eTitle": "Section 18. TradeWinds Ship Management", "items": [{"code": "TW", "title": "Exmar, 노후 가스선 5척 매각으로 약 3,500만 달러 차익", "src": "TradeWinds", "date": "2026-07-20", "kSum": "벨기에 가스선사 엑스마(Exmar)가 노후 가스운반선 5척을 매각해 약 3,500만 달러의 차익을 실현했다고 TradeWinds가 전했다. 선대 현대화와 자산 유동화를 겸한 거래로 풀이된다.", "eSum": "Belgian gas carrier owner Exmar has booked around $35m in profit from the sale of five older gas ships, according to TradeWinds. The disposal points to fleet renewal alongside asset monetisation.", "kImp": "노후선 매각을 통한 차익 실현은 가스선 자산가치가 높은 시기에 선주들이 선대 교체와 현금화를 병행하는 전략을 보여준다.", "eImp": "Selling older tonnage for a gain shows owners capitalising on firm gas-ship asset values to renew fleets and free up cash.", "url": "https://www.tradewindsnews.com/gas/exmar-banks-35m-profit-as-it-sells-five-older-gas-ships/2-1-2018449"}, {"code": "TW", "title": "차이나머천츠, VLOC 6척에 약 7억 2,800만 달러 발주", "src": "TradeWinds", "date": "2026-07-20", "kSum": "중국 선사 차이나머천츠(China Merchants)가 초대형광석운반선(VLOC) 6척을 약 7억 2,800만 달러에 발주하는 것으로 전해졌다. 대형 벌크 선대 확충 움직임으로 해석된다.", "eSum": "China Merchants is splashing out close to $728m on an order for six very large ore carriers (VLOCs), TradeWinds reports.", "kImp": "대형 중국 선사의 대규모 벌크선 신조 발주는 철광석 장기운송 수요와 중국 조선소 물량 확보 흐름을 반영한다.", "eImp": "A major Chinese owner's large VLOC order reflects long-term iron-ore transport demand and continued newbuilding booking at Chinese yards.", "url": "https://www.tradewindsnews.com/bulkers/china-merchants-splashing-out-close-to-728m-on-six-ship-vloc-order/2-1-2018407"}, {"code": "TW", "title": "난징탱커, 광저우조선소에 MR 탱커 4척 발주", "src": "TradeWinds", "date": "2026-07-20", "kSum": "중국 난징탱커(Nanjing Tanker)가 광저우조선소인터내셔널(Guangzhou Shipyard International)에 MR 프로덕트 탱커 4척을 발주했다고 TradeWinds가 전했다.", "eSum": "Nanjing Tanker has ordered four MR product tankers at Guangzhou Shipyard International, according to TradeWinds.", "kImp": "MR 탱커 신조 발주는 정제유 운송 수요 전망과 중국 선사의 프로덕트 탱커 선대 확대 의지를 보여준다.", "eImp": "The MR order signals confidence in clean-products trades and a Chinese owner's push to grow its product tanker fleet.", "url": "https://www.tradewindsnews.com/tankers/nanjing-tanker-orders-four-mr-tankers-at-guangzhou-shipyard-international/2-1-2018433"}, {"code": "TW", "title": "스와이어 그룹, '적기 도래 시 최고효율 신조선' 예고", "src": "TradeWinds", "date": "2026-07-17", "kSum": "스와이어 그룹(Swire Group)이 시장 여건이 맞으면 '가장 효율적인 신조선'을 발주하겠다고 밝혔다고 TradeWinds가 전했다. 다만 발주 시점은 신중히 저울질하는 모습이다.", "eSum": "Swire Group says it will order its 'most efficient newbuildings' when the time is right, TradeWinds reports, while weighing the timing carefully.", "kImp": "전통 선주의 고효율 신조 방침은 탈탄소 규제 대응과 선대 경쟁력 유지를 위한 투자 방향을 시사한다.", "eImp": "An established owner's focus on high-efficiency newbuildings underscores investment aimed at decarbonisation compliance and fleet competitiveness.", "url": "https://www.tradewindsnews.com/bulkers/swire-group-promises-most-efficient-newbuildings-when-the-time-is-right/2-1-2018090"}, {"code": "TW", "title": "지사이드 캐피털, 플랫폼 전략 구체화하며 대형 탱커 겨냥", "src": "TradeWinds", "date": "2026-07-17", "kSum": "지사이드 캐피털(Zeaside Capital)이 플랫폼 전략을 구체화하면서 더 큰 탱커 확보를 목표로 삼고 있다고 TradeWinds가 전했다.", "eSum": "Zeaside Capital is targeting bigger tankers as its platform strategy takes shape, according to TradeWinds.", "kImp": "신생·자본 주도 선주의 대형 탱커 확대는 탱커 시장에 대한 투자심리와 플랫폼형 선대 성장 모델을 보여준다.", "eImp": "A capital-backed owner scaling into larger tankers reflects investor appetite for the tanker segment and a platform-style growth model.", "url": "https://www.tradewindsnews.com/tankers/zeaside-capital-targets-bigger-tankers-as-platform-strategy-takes-shape/2-1-2016989"}, {"code": "TW", "title": "다이나콤·노르딕 아메리칸·알라푸조스 탱커, 흑해 공격에 피격", "src": "TradeWinds", "date": "2026-07-20", "kSum": "다이나콤(Dynacom), 노르딕 아메리칸 탱커스(Nordic American Tankers), 알라푸조스(Alafouzos)가 소유한 탱커들이 흑해 공격으로 피해를 입은 것으로 전해졌다.", "eSum": "Tankers owned by Dynacom, Nordic American and Alafouzos were hit in Black Sea attacks, TradeWinds reports.", "kImp": "주요 선주 소유 탱커들의 잇단 피격은 흑해 전쟁 위험 확대에 따른 선박·선원 안전과 전쟁보험료 상승 우려를 키운다.", "eImp": "Repeated strikes on major owners' tankers heighten concerns over crew and vessel safety and rising war-risk premiums in the Black Sea.", "url": "https://www.tradewindsnews.com/tankers/dynacom-nordic-american-and-alafouzos-tankers-hit-in-black-sea-attacks/2-1-2018443"}, {"code": "TW", "title": "HD현대 조선소에서 작업자 압사 사고", "src": "TradeWinds", "date": "2026-07-20", "kSum": "HD현대(HD Hyundai) 조선소에서 작업자 한 명이 압사하는 사고가 발생했다고 TradeWinds가 전했다.", "eSum": "A worker was crushed to death at an HD Hyundai shipyard, according to TradeWinds.", "kImp": "조선소 중대재해는 야드 안전관리 강화 필요성과 신조 인도 리스크 측면에서 선주·선박관리사의 주요 관심사다.", "eImp": "A fatal shipyard accident raises yard-safety concerns and delivery risk that matter to owners and managers.", "url": "https://www.tradewindsnews.com/casualties/worker-crushed-to-death-at-hd-hyundai-shipyard/2-1-2018438"}, {"code": "TW", "title": "아프리카 기국, 제재 대상 선박등록 운영사와 관계 단절", "src": "TradeWinds", "date": "2026-07-17", "kSum": "한 아프리카 기국이 제재 대상이 된 선박등록(등록기) 운영사와의 관계를 끊었다고 TradeWinds가 전했다.", "eSum": "An African flag state has severed ties with a sanctioned registry operator, according to TradeWinds.", "kImp": "기국의 제재 대응 강화는 편의치적·그림자 선단 규제 흐름과 함께 선박관리사의 컴플라이언스 부담 증대를 보여준다.", "eImp": "A flag state cutting ties with a sanctioned operator reflects tightening scrutiny of flags and shadow fleets and heavier compliance loads for managers.", "url": "https://www.tradewindsnews.com/insurance/african-flag-state-severs-ties-with-sanctioned-registry-operator/2-1-2018162"}, {"code": "TW", "title": "덴마크 조선소, 러시아 LNG선 작업 중단 요구 재차 거부", "src": "TradeWinds", "date": "2026-07-20", "kSum": "한 덴마크 조선소가 러시아 LNG 운반선 관련 작업을 중단하라는 새로운 요구를 재차 거부했다고 TradeWinds가 전했다.", "eSum": "A Danish shipyard has again rebuffed a fresh call to end its Russian LNG carrier work, TradeWinds reports.", "kImp": "러시아 LNG 관련 작업 지속 여부는 대러 제재 압박과 조선·수리 업계가 직면한 규제·평판 리스크를 부각한다.", "eImp": "Continuing Russian LNG work highlights sanctions pressure and the regulatory and reputational risks facing shipbuilding and repair players.", "url": "https://www.tradewindsnews.com/gas/danish-shipyard-rebuffs-fresh-call-to-end-russian-lng-carrier-work/2-1-2018277"}]}, {"code": "HOT", "type": "news", "kTitle": "Section 19. 핫이슈: 호르무즈 해협", "eTitle": "Section 19. Hot Topic: Strait of Hormuz", "items": [{"code": "HOT", "title": "Readers Speak: Strait of Hormuz seen as key shipping route", "src": "Container News", "date": "2026-07-20", "kSum": "컨테이너뉴스(Container News)의 독자 설문에서 향후 수개월간 가장 주목해야 할 해상 항로로 호르무즈 해협(Strait of Hormuz)이 수에즈 운하(Suez Canal)와 희망봉(Cape of Good Hope)을 제치고 1위에 올랐다. '세 항로 모두 동일하게 중요'라는 응답이 2위를 차지해, 주요 항로들이 서로 밀접하게 연결돼 있다는 인식도 강하게 나타났다. 이는 호르무즈 사태가 여전히 업계 항로·네트워크 계획의 핵심 변수로 남아 있음을 보여준다.", "eSum": "In Container News' latest Readers Speak poll, the Strait of Hormuz was ranked the shipping route most likely to shape decisions in the coming months, ahead of the Suez Canal and the Cape of Good Hope. The option that all three routes matter equally came second, reflecting how interconnected the major corridors have become. The result underscores that Hormuz remains the central variable in industry routing and network planning.", "kImp": "호르무즈 해협은 한국이 수입하는 원유·LNG의 핵심 통과로로, 업계 심리가 이 항로에 집중된다는 것은 운임·전쟁위험할증(war risk premium)·우회 결정에 즉각적 영향을 줄 수 있음을 의미한다. 한국 선사와 화주는 항로 리스크 재평가와 대체 조달 시나리오 점검이 필요하다.", "eImp": "As the Strait of Hormuz is a critical transit route for Korea's crude oil and LNG imports, concentrated industry attention on the corridor signals immediate implications for freight rates, war risk premiums and rerouting decisions. Korean owners and shippers should reassess route risk and contingency sourcing.", "url": "https://container-news.com/readers-speak-strait-of-hormuz-seen-as-key-shipping-route/"}, {"code": "HOT", "title": "Central Command Settles Into New Battle Rhythm as Reinforcements Arrive", "src": "The Maritime Executive", "date": "2026-07-19", "kSum": "미 중부사령부(CENTCOM)가 증원 전력이 도착하는 가운데 걸프 지역에서 새로운 작전 태세로 전환하고 있다고 마리타임 이그제큐티브(The Maritime Executive)가 보도했다. 지난 열흘간 이란 혁명수비대(IRGC)가 호르무즈 해협 남부 오만 수로에서 상선을 공격하고 GCC 국가 지상 목표를 타격하자, 미국은 이란 선박·항만에 대한 제재와 봉쇄를 재부과하고 공격 루트 차단에 나섰다. 항모강습단 2개(에이브러햄 링컨·조지 H.W. 부시)가 잔류한 가운데 7월 17~18일 F-15E·F-16·F-35 전력이 추가 전개됐다.", "eSum": "The Maritime Executive reports that US Central Command is settling into a new battle rhythm in the Gulf as reinforcements arrive. Over the past ten days the IRGC fired on shipping in the southern Omani channel of the Strait of Hormuz and struck ground targets in GCC states, prompting the US to re-impose sanctions and a blockade on Iranian shipping and ports and to interdict supply routes. Two carrier strike groups (Abraham Lincoln and George H.W. Bush) remain in theater, with F-15E, F-16 and F-35 assets moving in on July 17-18.", "kImp": "호르무즈 봉쇄·엔포스먼트가 다시 강화되면 통과 선박의 지연·검문·전쟁위험 노출이 커지며, 한국행 원유·LNG 물류와 선원 안전에 직접적 위험이 된다. 군사 긴장 고조는 보험료 상승과 통항 축소로 이어질 수 있어 면밀한 모니터링이 요구된다.", "eImp": "A renewed blockade and enforcement regime raises the risk of delays, inspections and war-risk exposure for transiting ships, directly threatening Korea-bound crude/LNG logistics and crew safety. Escalating military tension can push up premiums and thin out traffic, warranting close monitoring.", "url": "https://maritime-executive.com/article/us-forces-settle-into-new-battle-rhythm-as-reinforcements-arrive"}, {"code": "HOT", "title": "Splash Singapore: Christoph Toepfer on the lingering aftereffects from Hormuz", "src": "Splash247", "date": "2026-07-16", "kSum": "보레알리스 마리타임(Borealis Maritime)의 크리스토프 퇴퍼(Christoph Toepfer) 대표가 스플래시 싱가포르(Splash Singapore) 행사에서 탱커 업계가 호르무즈 해협의 혼란을 일회성이 아닌 반복되는 리스크로 대비해야 한다고 밝혔다. 그는 사태가 남긴 여파가 상당 기간 지속될 것이라고 경고했다.", "eSum": "Speaking at Splash Singapore, Borealis Maritime chief Christoph Toepfer warned that the tanker industry must prepare for the possibility that disruption in the Strait of Hormuz becomes a recurring rather than a one-off event. He cautioned that the aftereffects of the crisis will linger.", "kImp": "탱커 시장의 구조적 리스크가 상시화되면 용선료·전쟁위험할증·운항 계획의 변동성이 커진다. 한국 정유·가스 수입과 연계된 탱커 확보 전략에 장기적 재검토가 필요하다는 신호다.", "eImp": "If structural risk in the tanker market becomes permanent, volatility in charter rates, war-risk premiums and voyage planning will rise. It signals a need for long-term review of tanker sourcing strategies tied to Korea's refined-product and gas imports.", "url": "https://splash247.com/splash-singapore-christoph-toepfer-on-the-lingering-aftereffects-from-hormuz/"}, {"code": "HOT", "title": "Freightos Weekly Update: Hormuz closure pushing fuel costs back up", "src": "Container News", "date": "2026-07-15", "kSum": "프레이토스(Freightos) 주간 보고서는 이란의 단계적 공격과 미국의 보복이 이어지면서 호르무즈 해협 봉쇄가 연료비를 다시 끌어올리고 있다고 전했다. 양측이 서명했던 양해각서(MoU) 이후 긴장이 재점화되며 비용 압박이 커지고 있다는 분석이다.", "eSum": "The Freightos weekly update reports that the Hormuz closure is pushing fuel costs back up, following weeks of gradually escalating Iranian attacks and US retaliations. The renewed tension after the sides had signed a Memorandum of Understanding is adding to cost pressure across supply chains.", "kImp": "벙커유·연료비 상승은 한국 선사의 운항 원가와 컨테이너 운임에 직접 반영된다. 호르무즈발 에너지·연료 가격 변동은 수출입 물류비 전반의 리스크로 확산될 수 있다.", "eImp": "Rising bunker and fuel costs feed directly into Korean carriers' operating costs and container freight rates. Hormuz-driven energy and fuel price swings can spread into broader trade-logistics cost risk.", "url": "https://container-news.com/freightos-weekly-update-hormuz-closure-pushing-fuel-costs-back-up/"}, {"code": "HOT", "title": "DP World eyes Fujairah port to bypass Hormuz", "src": "Splash247", "date": "2026-07-14", "kSum": "파이낸셜타임스(Financial Times) 보도를 인용해 스플래시247(Splash247)은 DP월드(DP World)가 호르무즈 해협을 우회하기 위해 UAE 동부 후자이라(Fujairah) 해안에 신규 항만·컨테이너 터미널 건설을 추진하고 있다고 전했다. 이는 오만만(Gulf of Oman)으로 직접 접근해 해협 통항 리스크를 줄이려는 구조적 전환이다.", "eSum": "Citing the Financial Times, Splash247 reports that DP World is planning a new port and container terminal on the UAE's Fujairah coast to bypass the Strait of Hormuz. The move would provide direct access to the Gulf of Oman, reducing dependence on transiting the chokepoint.", "kImp": "후자이라·오만만 우회 인프라 확대는 중동 물류 지형을 바꾸고, 한국발/향 화물의 대체 항로·환적 옵션에 영향을 준다. 장기적으로 호르무즈 의존도를 낮추려는 화주·선사에게 새로운 기항 전략을 제시한다.", "eImp": "Expanding Fujairah/Gulf of Oman bypass infrastructure reshapes Middle East logistics and affects alternative routing and transshipment options for Korea-linked cargo. It offers shippers and carriers a new call strategy to cut long-term Hormuz dependence.", "url": "https://splash247.com/dp-world-eyes-fujairah-port-to-bypass-hormuz/"}, {"code": "HOT", "title": "Iran Piles on Pressure and Targets Tanker off Omani LNG Terminal", "src": "The Maritime Executive", "date": "2026-07-14", "kSum": "이란 혁명수비대(IRGC)가 7월 13일 밤 오만 콸하트(Qalhat) LNG 터미널 인근 해상에서 라이베리아 선적 화학제품 탱커 스톨트 마그네슘(Stolt Magnesium, 27,600 dwt)을 공격했다고 마리타임 이그제큐티브(The Maritime Executive)가 보도했다. 인명 피해나 탱크 파열은 없었으나 선원들이 기관실 화재와 사투를 벌였고, 앞서 원유탱커 알 바히야(Al Bahyah)·몸바사 B(Mombasa B)도 해협 인근에서 피격됐다. 이번 공격은 콸하트에서 선적하는 LNG선도 표적이 될 수 있다는 우려를 키웠다.", "eSum": "The Maritime Executive reports that on the night of July 13 the IRGC struck the Liberian-flagged chemical tanker Stolt Magnesium (27,600 dwt) near Oman's Qalhat LNG terminal. There were no injuries or tank rupture, but the crew fought an engine room fire; separately the crude tankers Al Bahyah and Mombasa B were hit near the strait. The attack raised fears that LNG carriers loading at Qalhat could become targets.", "kImp": "LNG 터미널 인근까지 공격 범위가 확대되면서 선원 안전과 LNG 수급 리스크가 동시에 커졌다. 한국의 LNG 조달·용선과 중동 배선 선원 보호 대책에 직접적 경종을 울린다.", "eImp": "With the strike zone widening to near an LNG terminal, both crew safety and LNG supply risk have risen. It is a direct warning for Korea's LNG procurement and chartering and for protecting seafarers deployed to the Middle East.", "url": "https://maritime-executive.com/article/iran-piles-on-pressure-and-targets-tanker-off-omani-lng-terminal"}, {"code": "HOT", "title": "Trump Drops Hormuz Protection Fee Saying Gulf States Will Invest in US", "src": "The Maritime Executive", "date": "2026-07-14", "kSum": "미국이 7월 14일 이란 관련 선박에 대한 봉쇄를 재개하는 가운데, 트럼프(Trump) 대통령이 호르무즈 통항 화물에 20% '보전 수수료'를 부과하려던 방침을 철회했다고 마리타임 이그제큐티브(The Maritime Executive)가 전했다. 대신 걸프 국가들이 미국에 투자하는 방식으로 '보호 비용'을 부담하도록 하겠다고 밝혔다.", "eSum": "As the US resumed its blockade of Iran-related shipping on July 14, President Trump reversed his plan to charge a 20% 'reimbursement fee' on cargoes transiting Hormuz, The Maritime Executive reports. Instead, he said Gulf states would pay for protection by investing in the United States.", "kImp": "통항 수수료·봉쇄 정책의 급변은 통과 선박의 비용·법적 리스크(UNCLOS 관련)와 노선 계획에 불확실성을 더한다. 한국 선사는 정책 변동성에 대비한 계약·정산 조항 점검이 필요하다.", "eImp": "Abrupt shifts in transit-fee and blockade policy add uncertainty to transiting ships' costs, legal exposure (UNCLOS) and route planning. Korean owners should review contract and settlement clauses to guard against policy volatility.", "url": "https://maritime-executive.com/article/trump-drops-hormuz-protection-fee-saying-gulf-states-will-invest-in-us"}, {"code": "HOT", "title": "ADNOC L&S confirms damage to two tankers after Strait of Hormuz attack", "src": "Container News", "date": "2026-07-14", "kSum": "아드녹 물류·서비스(ADNOC Logistics and Services, ADNOC L&S)가 호르무즈 해협을 통항하던 원유 탱커 2척이 발사체에 피격돼 손상됐다고 확인했다고 컨테이너뉴스(Container News)가 보도했다. 이는 해협 통항 선박에 대한 공격이 계속되고 있음을 보여준다.", "eSum": "Container News reports that ADNOC Logistics and Services (ADNOC L&S) confirmed two crude oil tankers were struck by projectiles and damaged while transiting the Strait of Hormuz. The incident shows attacks on transiting vessels are continuing.", "kImp": "국영 선사 소속 대형 원유 탱커까지 피격되면서 통항 자체의 위험도가 재확인됐다. 한국행 원유 수송과 관련 탱커 보험·전쟁위험할증 상승 압력으로 작용한다.", "eImp": "With large crude tankers of a state-owned operator hit, the danger of transit itself is reaffirmed. It adds upward pressure on tanker insurance and war-risk premiums for crude shipments bound for Korea.", "url": "https://container-news.com/adnoc-ls-confirms-damage-to-two-tankers-after-strait-of-hormuz-attack/"}, {"code": "HOT", "title": "Shipping incident: Projectile hits LNG carrier in Strait of Hormuz", "src": "Offshore Energy", "date": "2026-07-08", "kSum": "카타르 가스운송회사 나킬라트(Qatar Gas Transport Company, Nakilat)가 호르무즈 해협에서 자사 선박이 발사체에 피격되는 사고가 발생했다고 밝혔다고 오프쇼어 에너지(Offshore Energy)가 전했다. LNG 운반선까지 공격 대상이 되면서 가스 해상 운송의 안전 우려가 커졌다.", "eSum": "Offshore Energy reports that Qatar Gas Transport Company (Nakilat) disclosed a vessel incident in which a projectile struck an LNG carrier in the Strait of Hormuz. The targeting of an LNG carrier heightened safety concerns for seaborne gas transport.", "kImp": "세계 최대 LNG 선단 운영사 선박이 피격되면서 LNG 해상 공급망 전반의 리스크가 부각됐다. 한국의 LNG 도입·선박 배선 안전과 카타르발 물량 안정성에 직접적 함의를 지닌다.", "eImp": "The strike on a vessel of the world's largest LNG shipping operator highlights risk across the seaborne LNG supply chain. It carries direct implications for Korea's LNG imports, vessel deployment safety and the reliability of Qatari volumes.", "url": "https://www.offshore-energy.biz/shipping-incident-projectile-hits-lng-carrier-in-strait-of-hormuz/"}]}, {"code": "SYS", "type": "news", "kTitle": "Section 20. 시스템·앱", "eTitle": "Section 20. System & App", "items": [{"code": "SYS", "title": "맵시(Mapsea), 한국 해양 AI 플랫폼 프로젝트 주도", "src": "Smart Maritime Network", "date": "2026-07-16", "kSum": "한국 해양 소프트웨어 기업 맵시(Mapsea)가 KT, KT SAT, 포항공과대학교(POSTECH), 경상북도, 포항시와 손잡고 해양 인공지능(AI) 플랫폼 구축 프로젝트를 이끈다. 위성 통신과 지역 연구·행정 자원을 결합해 선박 운항 데이터 기반 AI 서비스를 개발하는 것이 골자다.", "eSum": "Korean maritime software firm Mapsea is leading a maritime AI platform project in partnership with KT, KT SAT, POSTECH, Gyeongsangbuk-do Province and Pohang City. The initiative combines satellite connectivity with regional research and administrative resources to build vessel-data-driven AI services.", "kImp": "국내 통신·학계·지자체가 결합한 해양 AI 플랫폼 컨소시엄으로, 한국 해운 IT 생태계의 데이터 표준화와 상용 서비스화 경쟁에서 선점 효과를 노린 움직임이다.", "eImp": "A domestic consortium of telecom, academia and government points to Korea's push to lead maritime data standardisation and commercial AI services.", "url": "https://smartmaritimenetwork.com/2026/07/16/mapsea-to-lead-korean-maritime-ai-platform-project/"}, {"code": "SYS", "title": "TTI 알헤시라스, 사이버로지텍(CyberLogitec) 스마트 터미널 시스템 도입", "src": "Smart Maritime Network", "date": "2026-07-14", "kSum": "스페인 토탈터미널인터내셔널 알헤시라스(TTI Algeciras)가 한국 해운 소프트웨어 개발사 사이버로지텍(CyberLogitec)과 스마트 터미널 시스템 구축 계약을 체결했다. 터미널 운영 자동화·최적화를 위한 시스템을 적용할 예정이다.", "eSum": "Spain's Total Terminal International Algeciras (TTI Algeciras) has signed an agreement with South Korean maritime software developer CyberLogitec to implement a smart terminal system, aimed at automating and optimising terminal operations.", "kImp": "한국 물류·해운 소프트웨어의 유럽 주요 터미널 수출 사례로, K-해운 IT의 글로벌 레퍼런스 확대를 보여준다.", "eImp": "A Korean logistics-software win at a major European terminal expands the global reference base for Korean maritime IT.", "url": "https://smartmaritimenetwork.com/2026/07/14/tti-algeciras-to-implement-smart-terminal-system/"}, {"code": "SYS", "title": "베슨 노티컬(Veson Nautical), IMOS 통합 AI 플랫폼 '베슨 플랫폼' 출시", "src": "MarineLink", "date": "2026-06-30", "kSum": "해운 소프트웨어 기업 베슨 노티컬(Veson Nautical)이 자사 운영체계인 IMOS와 AI 도구 코캡틴(CoCaptain), 메일, 베슬 인사이트(Vessel Insights), 벙커 인사이트(Bunker Insights)를 단일 인터페이스로 묶은 통합 '베슨 플랫폼(Veson Platform)'을 출시했다. 상업 해운 워크플로우와 협업, 데이터를 한 곳에서 제공한다.", "eSum": "Maritime software provider Veson Nautical has launched the Veson Platform, unifying its IMOS operating system, CoCaptain AI tools, Mail, Vessel Insights and Bunker Insights under a single interface for commercial maritime workflows, collaboration and data.", "kImp": "20년 이상 상업 해운 표준으로 쓰인 IMOS를 AI·데이터 통합 플랫폼으로 재편한 것으로, 용선·항해 소프트웨어 시장의 플랫폼 경쟁 심화를 시사한다.", "eImp": "Rebuilding the long-standing IMOS standard into an AI-and-data platform signals intensifying platform competition in chartering and voyage software.", "url": "https://www.marinelink.com/news/veson-nautical-launches-aipowered-540761"}, {"code": "SYS", "title": "플릿워크(Fleetwork), 포시도니아 2026서 클라우드 해양 ERP 수요 급증 확인", "src": "MarineLink", "date": "2026-07-02", "kSum": "그리스에서 개발된 최초의 완전 클라우드 기반 해양 ERP 플랫폼 개발사 플릿워크(Fleetwork)는 포시도니아 2026(Posidonia 2026) 참가 후 선주·운항사의 AI·클라우드 도입이 혁신 과제에서 운영 우선순위로 전환됐다고 밝혔다. 선대관리 현대화와 데이터 가치화 수요가 컸다고 전했다.", "eSum": "Fleetwork, developer of a fully cloud-based maritime ERP platform built in Greece, said that following Posidonia 2026, AI and cloud-native technologies have shifted from innovation projects to operational priorities for shipowners seeking to modernise fleet management.", "kImp": "클라우드 네이티브 해양 ERP가 틈새 실험을 넘어 운영 필수 도구로 자리잡고 있음을 보여주는 시장 신호다.", "eImp": "A market signal that cloud-native maritime ERP is moving from niche experiment to operational necessity.", "url": "https://www.marinelink.com/news/fleetwork-posidonia-signals-turning-point-540885"}, {"code": "SYS", "title": "30억 달러 '포트 알파(Port Alpha)' 프로젝트, 소프트웨어 주도 미국 조선 재편 목표", "src": "The Digital Ship", "date": "2026-07-20", "kSum": "30억 달러 규모의 '포트 알파(Port Alpha)' 프로젝트가 소프트웨어 주도 생산 방식을 통해 미국 조선업을 재정의하는 것을 목표로 추진된다. 디지털·자동화 기반 생산 체계로 조선 생산성을 높이겠다는 구상이다.", "eSum": "The $3bn Port Alpha project aims to redefine US shipbuilding through software-driven production, using digital and automation-based manufacturing to boost shipyard productivity.", "kImp": "조선 생산의 소프트웨어 정의(software-defined) 전환 시도로, 야드 IT·디지털 트윈·생산관리 시스템 수요 확대를 예고한다.", "eImp": "A move toward software-defined shipbuilding that foreshadows rising demand for yard IT, digital twins and production-management systems.", "url": "https://thedigitalship.com/news/maritime-software/3bn-port-alpha-project-aims-to-redefine-us-shipbuilding-through-software-driven-production/"}, {"code": "SYS", "title": "BW LNG, 클라우드 네이티브 해양 ERP '배스넷 네오(BASSnet Neo)' 채택", "src": "Seatrade Maritime News", "date": "2026-05-05", "kSum": "BW LNG가 시장의 약 30개 솔루션을 검토한 끝에 배스 소프트웨어(BASS Software)의 차세대 클라우드 네이티브 해양 ERP '배스넷 네오(BASSnet Neo)'를 LNG 운반선·FSRU 함대에 도입하기로 했다. 정비, 자재·재고, 조달, 입거(dry-docking) 모듈과 모바일 앱을 SaaS로 제공받는다.", "eSum": "BW LNG has selected BASS Software's next-generation cloud-native maritime ERP BASSnet Neo across its LNG carrier and FSRU fleet after evaluating up to 30 solutions, adopting maintenance, materials, procurement and dry-docking modules delivered as SaaS.", "kImp": "대형 LNG 선사가 광범위한 비교 평가 끝에 클라우드 ERP를 채택한 사례로, PMS·ERP 시장의 클라우드 전환 가속을 보여준다.", "eImp": "A major LNG owner choosing a cloud ERP after a broad bake-off underscores the accelerating cloud shift in the PMS/ERP market.", "url": "https://www.seatrade-maritime.com/maritime-technology/bw-lng-chooses-bassnet-neo-cloud-native-maritime-erp"}, {"code": "SYS", "title": "ABB, 해양 자동화 강화 위해 회글룬(Høglund) 인수", "src": "Seatrade Maritime News", "date": "2026-07-02", "kSum": "ABB가 해양 자동화 사업 확대를 위해 노르웨이 자동화 전문기업 회글룬(Høglund)을 인수한다고 밝혔다. 통합 자동화·전력관리 역량을 강화하려는 행보다.", "eSum": "ABB is to acquire Norwegian automation specialist Høglund to expand its marine automation business, strengthening its integrated automation and power-management capabilities.", "kImp": "선박 자동화·통합제어 시스템 시장의 대형 인수합병으로, 대형 벤더 중심의 통합 플랫폼 경쟁 재편을 시사한다.", "eImp": "A sizeable M&A in vessel automation and integrated control points to consolidation around large-vendor integrated platforms.", "url": "https://www.seatrade-maritime.com/maritime-technology/abb-to-acquire-h-glund-to-expand-marine-automation-business"}, {"code": "SYS", "title": "ABS, 산업 사이버보안 기업 RMC 글로벌(RMC Global) 인수", "src": "Seatrade Maritime News", "date": "2026-05-08", "kSum": "미국선급(ABS)의 컨설팅 부문 ABS 컨설팅(ABS Consulting)이 산업 사이버보안·리스크관리·복원력 솔루션 제공사 RMC 글로벌(RMC Global)을 인수했다. 커지는 운영 리스크·사이버 위협·규제 압박에 대응해 통합 솔루션 역량을 강화한다는 목적이다.", "eSum": "ABS Consulting has acquired RMC Global, a provider of industrial cybersecurity, risk management and resiliency solutions, to strengthen integrated offerings against rising operational risk, cyber threats and regulatory pressure.", "kImp": "선급이 해양 사이버보안·리스크 소프트웨어 역량을 내재화하는 흐름으로, 규제 강화 속 OT 사이버보안 시장 확대를 보여준다.", "eImp": "A class society internalising maritime cyber and risk software reflects the expanding OT cybersecurity market amid tightening rules.", "url": "https://www.seatrade-maritime.com/maritime-technology/abs-acquires-rmc-global"}, {"code": "SYS", "title": "쉽매치(ShipMatch), 용선 이메일 과부하 겨냥한 AI 플랫폼 출시", "src": "Splash247", "date": "2026-07-09", "kSum": "쉽매치(ShipMatch)가 브로커, 선주, 화주, 용선 담당자와 대리점을 연결·매칭하도록 설계된 AI 기반 해운 소프트웨어 플랫폼을 출시했다. 방대한 용선 이메일 처리 부담을 줄이는 것을 목표로 한다.", "eSum": "ShipMatch has launched an AI-powered maritime software platform designed to help brokers, owners, cargo owners, chartering teams and agents match cargoes and vessels, aiming to cut chartering email overload.", "kImp": "용선 업무의 반복적 이메일·매칭 과정을 AI로 자동화하려는 시도로, 상업 해운 워크플로우 소프트웨어의 AI 경쟁을 보여준다.", "eImp": "Automating repetitive chartering email and matching with AI illustrates the AI race in commercial maritime workflow software.", "url": "https://splash247.com/shipmatch-targets-chartering-email-overload-with-ai-platform/"}, {"code": "SYS", "title": "NYK, 마이크로소프트와 디지털 전환 협약 체결", "src": "Splash247", "date": "2026-07-08", "kSum": "일본 대형 선사 니폰유센(NYK)이 마이크로소프트 재팬(Microsoft Japan)과 디지털 전환을 가속하기 위한 전략적 프레임워크 협약을 체결했다. 클라우드·AI 기반으로 운영 전반의 디지털화를 추진한다.", "eSum": "Japanese shipping major NYK has signed a strategic framework agreement with Microsoft Japan to accelerate digital transformation, driving cloud- and AI-based digitalisation across its operations.", "kImp": "대형 선사가 글로벌 클라우드 사업자와 전사 디지털 전환을 추진하는 사례로, 하이퍼스케일러의 해운 IT 진출 확대를 보여준다.", "eImp": "A major carrier partnering a global cloud provider on enterprise-wide transformation signals hyperscalers' deepening push into maritime IT.", "url": "https://splash247.com/nyk-signs-digital-transformation-deal-with-microsoft/"}, {"code": "SYS", "title": "NAVTOR expands e-navigation platform to 18,000 vessels", "src": "PortNews", "date": "2026-07-09", "kSum": "노르웨이 나브토르(NAVTOR)가 보이저 월드와이드(Voyager Worldwide) 고객 이전을 완료하며 e-내비게이션 플랫폼 사용 선박을 약 1만8천 척으로 확대했다. 배출규제·전자 항해일지 등으로 서비스 범위를 넓히고 있다.", "eSum": "NAVTOR expanded its e-navigation platform to about 18,000 vessels after migrating Voyager Worldwide customers, broadening into emissions compliance and digital logbooks.", "kImp": "세계 최대 전자해도 배포망을 기반으로 선박-육상 통합 소프트웨어 플랫폼을 구축 중이며, 일본을 차기 핵심 성장시장으로 삼아 MOL과 전자 항해일지 협업을 진행한다.", "eImp": "Building on the largest electronic-chart base, NAVTOR is developing an integrated ship-shore software platform, targeting Japan for growth and working with MOL on e-logbooks.", "url": "https://en.portnews.ru/news/393966/"}, {"code": "SYS", "title": "Navarino and LEDGID create portable digital trust for seafarers", "src": "The Digital Ship", "date": "2026-06-01", "kSum": "나바리노(Navarino)와 레짓(LEDGID)이 선원의 자격증·규정 준수 기록·경력 정보를 안전하게 이동·검증할 수 있는 '휴대형 디지털 신뢰(digital trust)' 프레임워크 개발에 협력한다.", "eSum": "Navarino and LEDGID partnered to develop a portable digital trust framework that makes seafarer credentials, compliance records and professional history securely portable and verifiable.", "kImp": "종이·분산 기록에 의존하던 선원 신원·자격 관리를 디지털화해 승선 절차와 크루 체인지 효율을 높이는 디지털 선원 ID 흐름을 가속한다.", "eImp": "The initiative digitises seafarer identity and credential management, advancing digital crew-ID adoption and streamlining onboarding and crew changes.", "url": "https://thedigitalship.com/news/maritime-software/navarino-and-ledgid-join-forces-to-create-portable-digital-trust-for-seafarers/"}, {"code": "SYS", "title": "GTT Marine unites Danelec, Ascenz Marorka and VPS under one digital brand", "src": "The Digital Ship", "date": "2026-06-03", "kSum": "GTT 마린(GTT Marine)이 다넬렉(Danelec), 아센츠 마로르카(Ascenz Marorka), VPS(Vessel Performance Solutions)의 역량을 단일 조직·디지털 브랜드로 통합했다.", "eSum": "GTT Marine combined the capabilities of Danelec, Ascenz Marorka and Vessel Performance Solutions into a single organisation and digital brand.", "kImp": "약 1만7천 척 규모의 통합 디지털 네트워크를 기반으로 선박 성능·데이터 서비스를 일원화해 선사·선박관리사에 통합 성능관리 솔루션을 제공한다.", "eImp": "The combined ~17,000-vessel digital network consolidates vessel-performance and data services, offering owners and managers a unified performance-management platform.", "url": "https://thedigitalship.com/news/maritime-software/gtt-marine-assembles-17000-vessel-digital-network-through-danelec-ascenz-marorka-and-vps-integration/"}]}, {"code": "SMGR", "type": "news", "kTitle": "Section 21. 선박관리사", "eTitle": "Section 21. Ship Managers", "items": [{"code": "SMGR", "title": "Anglo-Eastern marks Day of the Seafarer 2026 with focus on crew welfare", "src": "Anglo-Eastern", "date": "2026-06-25", "kSum": "앵글로-이스턴(Anglo-Eastern)이 2026년 '선원의 날'을 맞아 글로벌 무역에서 선원이 하는 핵심적 역할과 이들이 직면한 위험을 조명했다. 비외른 호이고르(Bjorn Hojgaard) CEO는 해상 인력에 대한 장기적 돌봄 방침을 강조했다.", "eSum": "Anglo-Eastern marked Day of the Seafarer 2026, with CEO Bjorn Hojgaard highlighting seafarers' vital role in global trade and the company's long-term approach to caring for its people at sea.", "kImp": "세계 최대 독립 선박관리사 중 하나가 선원 복지를 전면에 내세운 것은 인력 확보 경쟁이 치열한 업계에서 긍정적 브랜딩 신호다.", "eImp": "One of the world's largest independent ship managers foregrounding crew welfare signals positive employer branding amid an intensifying seafarer talent race.", "url": "https://www.angloeastern.com/news-and-insights/day-of-the-seafarer-2026/"}, {"code": "SMGR", "title": "Anglo-Eastern holds inaugural Technical Summit 2026 to align fleet standards", "src": "Anglo-Eastern", "date": "2026-06-11", "kSum": "앵글로-이스턴(Anglo-Eastern)이 첫 기술 서밋(Technical Summit)을 개최해 조직 전반의 고위 리더와 기술 전문가를 모아 경험 공유와 선대 표준 정렬을 도모했다. 홍콩·싱가포르·아테네·안트베르펜 등 4개 지역에서 순회 개최됐다.", "eSum": "Anglo-Eastern held its inaugural Technical Summit 2026, bringing senior leaders and technical experts together across four editions in Hong Kong, Singapore, Athens and Antwerp to share experience and align fleet standards.", "kImp": "지정학·운항 복잡성이 커지는 환경에서 기술 표준을 일원화하려는 시도로, 선박관리 품질 향상에 기여한다.", "eImp": "A move to unify technical standards amid rising geopolitical and operational complexity, supporting higher ship-management quality.", "url": "https://www.angloeastern.com/news-and-insights/anglo-eastern-technical-summit-2026-shared-learning-stronger-standards/"}, {"code": "SMGR", "title": "Anglo-Eastern strengthens Greece presence with refreshed leadership commitment", "src": "Anglo-Eastern", "date": "2026-05-19", "kSum": "앵글로-이스턴 유니반 그룹(Anglo-Eastern Univan Group)이 세계에서 가장 경쟁이 치열한 해운 시장 중 하나인 그리스에서의 입지를 리더십 재정비와 함께 강화했다. 이는 그리스 시장에 대한 장기적 약속의 일환이다.", "eSum": "Anglo-Eastern Univan Group strengthened its presence in Greece with a refreshed leadership commitment, as part of its long-term commitment to one of the world's most prominent and competitive shipping markets.", "kImp": "그리스 선주 시장 확대는 제3자 선박관리 수주 기반을 넓히는 전략적 지역 투자다.", "eImp": "Expanding in the Greek owner market is a strategic regional investment that broadens the base for third-party management mandates.", "url": "https://www.angloeastern.com/news-and-insights/anglo-eastern-further-strengthens-its-greece-presence-with-refreshed-leadership-commitment/"}, {"code": "SMGR", "title": "V.Group presents first Annual Safety Catch Award to seafarer", "src": "V.Group", "date": "2026-07-07", "kSum": "브이그룹(V.Group)이 첫 연례 세이프티 캐치 어워드(Annual Safety Catch Award)를 나이지리아 라고스 모항에서 소방원 제임스 샤이부(James Shaibu)에게 수여했다. 위험을 사전에 발견·보고한 선원을 포상하는 신설 제도다.", "eSum": "V.Group presented its first Annual Safety Catch Award to Fireman James Shaibu at his home port of Lagos, Nigeria, recognising seafarers who proactively spot and report safety hazards.", "kImp": "선제적 안전문화 강화를 위한 인센티브 제도로, 선원 참여형 리스크 관리의 모범 사례다.", "eImp": "An incentive scheme reinforcing a proactive safety culture and modelling crew-driven risk management.", "url": "https://vgrouplimited.com/presenting-the-first-v-group-annual-safety-catch-award/"}, {"code": "SMGR", "title": "V. and International Seaways' female cadet programme enters second year", "src": "V.Group", "date": "2026-05-18", "kSum": "브이십스(V.Ships)와 인터내셔널 시웨이즈(International Seaways)가 여성 생도(cadet) 양성 프로그램 2년 차에 진입했다. 해상 성 다양성 확대와 업계 인력난 완화를 목표로 한다.", "eSum": "On the International Day for Women in Maritime, V.Ships and International Seaways entered the second year of their female cadet programme, aimed at boosting gender diversity at sea and easing the industry skills shortage.", "kImp": "여성 인력 확대는 장기 선원 공급난 대응과 ESG(사회) 성과 측면에서 긍정적이다.", "eImp": "Expanding the female talent pool is positive for long-term seafarer supply and for social-ESG performance.", "url": "https://vgrouplimited.com/female-cadets-programme-in-partnership-with-insw-2/"}, {"code": "SMGR", "title": "Pertamina shipping arm eyes global expansion with Columbia Shipmanagement tie-up", "src": "S&P Global", "date": "2026-06-08", "kSum": "페르타미나 인터내셔널 시핑(Pertamina International Shipping)이 컬럼비아 십매니지먼트(Columbia Shipmanagement)와의 협력을 통해 글로벌 확장을 모색하고 있다. 양사 제휴는 선대 관리 역량 강화와 국제 시장 진출을 목표로 한다.", "eSum": "Pertamina's shipping arm is eyeing global expansion through a tie-up with Columbia Shipmanagement, aimed at strengthening fleet management capability and international market reach.", "kImp": "국영 에너지사 선대와의 제휴는 컬럼비아의 제3자 관리 수주 확대와 중동·아시아 입지 강화에 기여한다.", "eImp": "A partnership with a state energy company's fleet supports Columbia's third-party mandate growth and its Middle East and Asia footprint.", "url": "https://www.spglobal.com/energy/en/news-research/latest-news/crude-oil/060826-pertamina-shipping-arm-eyes-global-expansion-with-columbia-shipmanagement-tie-up"}, {"code": "SMGR", "title": "Fleet Management receives Outstanding Performance Award in Port State Control inspection", "src": "Fleet Management", "date": "2026-06-12", "kSum": "플릿 매니지먼트(Fleet Management)가 항만국통제(PSC) 점검에서 우수 성과상(Outstanding Performance Award)을 수상했다. 선대 안전·규정 준수 수준을 입증하는 성과다.", "eSum": "Fleet Management received an Outstanding Performance Award in Port State Control inspection, underscoring the safety and compliance standards of its managed fleet.", "kImp": "PSC 우수 실적은 선주에게 관리 품질을 증명하는 지표로, 신규 수주 경쟁력에 긍정적이다.", "eImp": "Strong PSC performance is a proof point of management quality that supports competitiveness for new mandates.", "url": "https://www.fleetship.com/news/fleet-management-receives-outstanding-performance-award-in-port-state-control-inspection"}, {"code": "SMGR", "title": "Northern Marine Company Wellbeing Day promotes wellbeing and community support", "src": "Northern Marine Group", "date": "2026-06-22", "kSum": "노던 마린(Northern Marine)의 글래스고 임직원들이 웰빙 데이(Wellbeing Day)에 모여 웰빙 증진, 유대 강화, 지역사회 지원을 위한 다양한 활동에 참여했다. 조직 문화와 직원 복지를 강조하는 행사다.", "eSum": "Northern Marine colleagues in Glasgow came together for a Company Wellbeing Day, with activities designed to support wellbeing, encourage connection and provide community support.", "kImp": "육상 인력의 웰빙과 유대를 강화하는 활동은 인재 유지와 조직 문화 측면에서 긍정적이다.", "eImp": "Activities boosting shore-staff wellbeing and connection are positive for retention and organisational culture.", "url": "https://www.nmg-stena.com/company-wellbeing-day-promotes-wellbeing-connection-and-community-support/"}, {"code": "SMGR", "title": "Fleet Management wins Social Leader honour at ESG Shipping Awards for third consecutive year", "src": "Fleet Management", "date": "2026-05-18", "kSum": "플릿 매니지먼트(Fleet Management)가 ESG 시핑 어워드(ESG Shipping Awards)에서 3년 연속 사회 부문 리더(Social Leader) 상을 수상했다. 선원 복지, 경력 개발, 가족 돌봄에 대한 지속적 노력을 인정받았다.", "eSum": "Fleet Management won the Social Leader honour at the ESG Shipping Awards for a third consecutive year, recognising its sustained commitment to seafarer wellbeing, career development and family care.", "kImp": "ESG 사회 부문 3연속 수상은 관리사의 선원 중심 경영을 대외적으로 입증하는 성과다.", "eImp": "A third straight social-ESG award externally validates the manager's crew-centric approach.", "url": "https://www.fleetship.com/news/fleet-management-awarded-social-leader-honour-at-esg-shipping-awards-for-third-consecutive-year"}, {"code": "SMGR", "title": "Wilhelmsen Ship Management launches vessel-lifecycle company Cyclus Marine", "src": "The Maritime Executive", "date": "2026-04-15", "kSum": "빌헬름센 선박관리(Wilhelmsen Ship Management)가 신조·입거·개조·리사이클링 등 선박 전(全) 생애주기 서비스를 전담하는 신설 법인 사이클러스 마린(Cyclus Marine)을 출범했다. 싱가포르·함부르크·쿠알라룸푸르·아테네에서 운영한다.", "eSum": "Wilhelmsen Ship Management launched Cyclus Marine, a dedicated vessel-lifecycle company covering newbuilding, drydocking, retrofits, conversions and recycling, operating from Singapore, Hamburg, Kuala Lumpur and Athens.", "kImp": "50여 년의 선박 인도 경험을 바탕으로 자산가치 보호와 리스크 저감을 지원하며, 이후 로이드선급(Lloyd's Register)과 책임 있는 선박 리사이클링 확대를 위한 MOU도 체결했다.", "eImp": "Building on 50+ years of deliveries, it aims to protect asset value and cut risk; Cyclus Marine subsequently signed an MoU with Lloyd's Register to scale responsible ship recycling.", "url": "https://maritime-executive.com/corporate/wilhelmsen-ship-management-launches-vessel-lifecycle-company-cyclus-marine"}, {"code": "SMGR", "title": "Fleet Management launches Pulse app for 27,000 seafarers", "src": "The Manila Times", "date": "2026-07-01", "kSum": "플릿 매니지먼트(Fleet Management Limited)가 세계 선원의 날(6월 25일)에 맞춰 600여 척·2만7천 명 선원을 위한 통합 모바일 앱 '펄스(Pulse)'를 출시했다. 승선 절차·업무·복지 서비스를 하나로 모았다.", "eSum": "Fleet Management launched Pulse, a single mobile app for its 27,000 seafarers across 600+ vessels, uniting onboarding, operational, administrative and welfare services, timed to the Day of the Seafarer (25 June).", "kImp": "출시 직후 목표(1,000건)를 크게 웃도는 7천 건 이상 다운로드를 기록하며, 선원 복지·연결성을 강화하는 디지털 크루 지원 확대 흐름을 보여준다.", "eImp": "Pulse passed 7,000 downloads shortly after launch, well above its 1,000 target, underscoring the expansion of digital crew-support tools for welfare and connectivity.", "url": "https://www.manilatimes.net/2026/07/01/business/maritime/fleet-management-launches-pulse-app-for-seafarers/2375579"}, {"code": "SMGR", "title": "Northern Marine partners with Achilles on supply-chain ESG", "src": "The Digital Ship", "date": "2026-06-03", "kSum": "스테나(Stena) 그룹 계열 노던 마린(Northern Marine Group)이 공급망 리스크관리 기업 아킬레스(Achilles)와 손잡고 공급업체 사전심사·리스크관리를 표준화하고 ESG 성과를 일상 의사결정에 반영한다.", "eSum": "Northern Marine Group (part of Stena) partnered with supply-chain risk specialist Achilles to standardise supplier prequalification and embed ESG considerations into everyday decision-making.", "kImp": "외부 검증 기반의 공급업체 관리 체계로 투명성과 컴플라이언스를 강화하고, 대형 입찰 참여 시 진입장벽을 낮춰 사업 성장을 뒷받침한다.", "eImp": "An externally validated supplier framework strengthens transparency and compliance and removes barriers when bidding for larger contracts, supporting business growth.", "url": "https://thedigitalship.com/news/maritime-software/northern-marine-partners-with-achilles-to-strengthen-supply-chain-transparency-and-esg-credentials/"}, {"code": "SMGR", "title": "Synergy Marine named Ship Management Company of the Year 2026", "src": "Synergy Marine Group", "date": "2026-04-27", "kSum": "시너지 마린 그룹(Synergy Marine Group)이 인도 티루바난타푸람에서 열린 제1회 마포츠 글로벌(Marports Global) 컨퍼런스·엑설런스 어워드 2026에서 '올해의 선박관리사(Ship Management Company of the Year)'로 선정됐다.", "eSum": "Synergy Marine Group was named Ship Management Company of the Year at the inaugural Marports Global Conference & Excellence Awards 2026 in Thiruvananthapuram, India.", "kImp": "풍력보조추진·게이트러더·LNG/메탄올 등 신기술 선박을 다수 관리에 편입한 성과가 인정된 것으로, 안전·컴플라이언스·효율 운항 역량을 대외적으로 입증했다.", "eImp": "The award recognised Synergy's onboarding of vessels with wind-assisted propulsion, gate rudders and LNG/methanol capability, validating its safe, compliant and efficient operations.", "url": "https://www.synergymarinegroup.com/shore-awards/ship-management-award-marports-global-2026/"}]}]};